# --- CLASS: QuickWinOptimizer ---
class QuickWinOptimizer:
    """Оптимизатор быстрых побед с минимальными издержками"""
    
    def __init__(self, digital_twin: UlyanovskDigitalTwin):
        self.dt = digital_twin
        self.quick_wins = []
        
    def identify_quick_wins(self) -> List[Dict]:
        """Идентификация проектов с быстрой отдачей"""
        wins = []
        
        # 1. Оптимизация логистики между УАЗ и авиазаводом
        wins.append({
            "name": "Логистический хаб УАЗ-Авиастар",
            "description": "Совместное использование складских и транспортных мощностей",
            "investment_required": 120,  # млн руб
            "payback_period": 1.8,      # лет
            "annual_savings": 67,       # млн руб
            "synergy_effect": 0.45,
            "implementation_time": 6    # месяцев
        })
        
        # 2. Внедрение AI-оптимизации энергопотребления
        wins.append({
            "name": "AI-Энергоменеджер промзоны",
            "description": "Система предиктивной оптимизации энергозатрат",
            "investment_required": 85,
            "payback_period": 1.2,
            "annual_savings": 71,
            "synergy_effect": 0.38,
            "implementation_time": 4
        })
        
        # 3. Создание центра компетенций композитных материалов
        wins.append({
            "name": "Композитный R&D центр",
            "description": "Объединение компетенций авиационной и автомобильной отраслей",
            "investment_required": 350,
            "payback_period": 2.5,
            "annual_profit": 140,
            "synergy_effect": 0.72,
            "implementation_time": 9
        })
        
        self.quick_wins = wins
        return wins
    
    def prioritize_projects(self, max_investment: float = 500) -> List[Dict]:
        """Приоритизация проектов по критерию ROI/время"""
        if not self.quick_wins:
            self.identify_quick_wins()
            
        # Рассчитываем ROI для каждого проекта
        for project in self.quick_wins:
            if "annual_savings" in project:
                annual_return = project["annual_savings"]
            else:
                annual_return = project["annual_profit"]
                
            project["roi"] = annual_return / project["investment_required"]
            project["score"] = (project["roi"] * 0.6 + 
                              (1/project["implementation_time"]) * 0.4)
        
        # Сортируем по убыванию score
        sorted_projects = sorted(self.quick_wins, key=lambda x: x["score"], reverse=True)
        
        # Выбираем проекты в рамках бюджета
        selected = []
        total_investment = 0
        
        for project in sorted_projects:
            if total_investment + project["investment_required"] <= max_investment:
                selected.append(project)
                total_investment += project["investment_required"]
        
        return selected

# --- CLASS: EconomicDashboard ---
class EconomicDashboard:
    """Панель управления экономикой региона"""
    
    def __init__(self, digital_twin: UlyanovskDigitalTwin):
        self.dt = digital_twin
        self.setup_style()
        
    def setup_style(self):
        """Настройка стиля графиков"""
        plt.style.use('seaborn-v0_8')
        sns.set_palette("husl")
        
    def plot_industrial_balance(self):
        """Визуализация баланса отраслей"""
        current = self.dt.current_state["industrial_assets"]
        target = self.dt.target_state
        
        industries = list(current.keys())
        current_weights = [current[i]["weight"] for i in industries]
        target_weights = [target[i]["weight"] for i in industries]
        
        x = np.arange(len(industries))
        width = 0.35
        
        fig, ax = plt.subplots(figsize=(12, 6))
        ax.bar(x - width/2, current_weights, width, label='Текущее состояние', alpha=0.7)
        ax.bar(x + width/2, target_weights, width, label='Целевое состояние', alpha=0.7)
        
        ax.set_xlabel('Отрасли промышленности')
        ax.set_ylabel('Вес в экономике')
        ax.set_title('Балансировка отраслевой структуры Ульяновской области')
        ax.set_xticks(x)
        ax.set_xticklabels(industries, rotation=45)
        ax.legend()
        
        plt.tight_layout()
        return fig
    
    def plot_synergy_heatmap(self):
        """Тепловая карта синергии между отраслями"""
        synergy_matrix = self.dt.calculate_synergy_matrix()
        industries = list(self.dt.current_state["industrial_assets"].keys())
        
        fig, ax = plt.subplots(figsize=(10, 8))
        im = ax.imshow(synergy_matrix, cmap='YlOrRd', vmin=0, vmax=1)
        
        ax.set_xticks(np.arange(len(industries)))
        ax.set_yticks(np.arange(len(industries)))
        ax.set_xticklabels(industries, rotation=45)
        ax.set_yticklabels(industries)
        
        # Добавляем текстовые аннотации
        for i in range(len(industries)):
            for j in range(len(industries)):
                text = ax.text(j, i, f'{synergy_matrix[i, j]:.2f}',
                              ha="center", va="center", color="black")
        
        ax.set_title("Матрица синергии между отраслями Ульяновской области")
        fig.colorbar(im, ax=ax)
        plt.tight_layout()
        
        return fig

# --- CLASS: UlyanovskDigitalTwin ---
class UlyanovskDigitalTwin:
    """Цифровой двойник экономики Ульяновской области с φ√5-балансировкой"""
    
    def __init__(self):
        self.phi = (1 + math.sqrt(5)) / 2  # Золотое сечение
        self.sqrt5 = math.sqrt(5)
        
        # 📊 Текущее состояние региона (данные Росстат + моделирование)
        self.current_state = {
            "industrial_assets": {
                "automotive": {"weight": 0.45, "efficiency": 0.72, "synergy_potential": 0.35},
                "aviation": {"weight": 0.25, "efficiency": 0.81, "synergy_potential": 0.68},
                "machine_tools": {"weight": 0.15, "efficiency": 0.63, "synergy_potential": 0.72},
                "food_industry": {"weight": 0.10, "efficiency": 0.85, "synergy_potential": 0.45},
                "renewable_energy": {"weight": 0.05, "efficiency": 0.91, "synergy_potential": 0.88}
            },
            "debt_metrics": {
                "current_debt_billion": 45.3,
                "debt_to_income_ratio": 0.87,
                "servicing_cost_annual": 3.2
            },
            "human_capital": {
                "workforce_quality": 0.71,
                "stem_specialists": 0.65,
                "migration_balance": -0.12
            }
        }
        
        # 🎯 Целевое состояние (φ-сбалансированное)
        self.target_state = self._calculate_target_balance()
        
    def _calculate_target_balance(self) -> Dict:
        """Расчет идеального баланса по принципу золотого сечения"""
        total_weight = 1.0
        current_weights = [asset["weight"] for asset in self.current_state["industrial_assets"].values()]
        
        # φ-оптимизация весов
        optimal_weights = self._golden_section_optimization(current_weights)
        
        target = {}
        assets = list(self.current_state["industrial_assets"].keys())
        for i, asset in enumerate(assets):
            target[asset] = {
                "weight": optimal_weights[i],
                "efficiency_target": 0.95,  # Целевая эффективность 95%
                "synergy_target": 0.85     # Целевая синергия 85%
            }
        
        return target
    
    def _golden_section_optimization(self, current_weights: List[float]) -> List[float]:
        """Оптимизация весов по методу золотого сечения"""
        # Увеличиваем вес перспективных отраслей (ВИЭ, авиация)
        boost_factors = [1.0, 1.3, 1.2, 1.0, 1.8]  # Коэффициенты усиления
        
        optimized = []
        for i, weight in enumerate(current_weights):
            new_weight = weight * boost_factors[i] * self.phi
            optimized.append(new_weight)
        
        # Нормализация к сумме 1.0
        total = sum(optimized)
        return [w/total for w in optimized]
    
    def calculate_synergy_matrix(self) -> np.ndarray:
        """Матрица синергии между отраслями"""
        industries = list(self.current_state["industrial_assets"].keys())
        n = len(industries)
        synergy_matrix = np.zeros((n, n))
        
        # Заполняем матрицу синергии на основе паттернов
        for i in range(n):
            for j in range(n):
                if i == j:
                    synergy_matrix[i][j] = 1.0
                else:
                    # Автомобильная + авиационная = композитные материалы
                    if (industries[i] == "automotive" and industries[j] == "aviation") or \
                       (industries[i] == "aviation" and industries[j] == "automotive"):
                        synergy_matrix[i][j] = 0.75
                    # Станкостроение + ВИЭ = оборудование для ВИЭ
                    elif (industries[i] == "machine_tools" and industries[j] == "renewable_energy"):
                        synergy_matrix[i][j] = 0.82
                    else:
                        synergy_matrix[i][j] = 0.3  # Базовая синергия
        
        return synergy_matrix

# --- CLASS: RealTimeEconomicMonitor ---
class RealTimeEconomicMonitor:
    """Мониторинг экономических показателей в реальном времени"""
    
    def __init__(self):
        self.metrics = {
            "industrial_output": [],
            "employment_rate": [],
            "investment_inflow": [],
            "debt_dynamics": [],
            "innovation_index": []
        }
        
    def add_data_point(self, metric: str, value: float):
        """Добавление новой точки данных"""
        self.metrics[metric].append(value)
        
    def calculate_trend(self, metric: str) -> float:
        """Расчет тренда показателя"""
        data = self.metrics[metric]
        if len(data) < 2:
            return 0.0
        
        x = np.arange(len(data))
        y = np.array(data)
        slope = np.polyfit(x, y, 1)[0]
        
        return slope

    def generate_alert(self, metric: str, threshold: float = 0.1) -> str:
        """Генерация предупреждений при отклонениях"""
        trend = self.calculate_trend(metric)
        
        if abs(trend) > threshold:
            direction = "рост" if trend > 0 else "спад"
            return f"🚨 ВНИМАНИЕ: {metric} показывает значительный {direction} ({trend:.3f})"
        else:
            return f"✅ {metric}: стабильное состояние"

