# --- CLASS: QuantumObserver ---
class QuantumObserver:
    def __init__(self, consciousness_level=1.0):
        """
        consciousness_level: от 0 (нет сознания) до 1 (полное осознание)
        """
        self.chi = consciousness_level
        self.phase = np.random.random() * 2*np.pi  # начальная фаза намерения
        self.focus = 0.0  # уровень фокусировки на квантовой системе
        
    def observe(self, quantum_state):
        """
        Воздействие наблюдателя на квантовое состояние
        """
        # Оператор наблюдения:
        # χ̂ = |ψ_obs⟩⟨ψ_obs| ⊗ e^{iφ(t)}
        
        # Эффект наблюдения зависит от:
        # 1. Уровня сознания (chi)
        # 2. Фокусировки (focus)
        # 3. Фазы намерения (phase)
        
        observation_strength = self.chi * self.focus
        
        # Коллапс волновой функции пропорционален силе наблюдения
        collapsed_state = quantum_state * np.exp(1j * self.phase * observation_strength)
        
        # Нормировка
        norm = np.sqrt(np.sum(np.abs(collapsed_state)**2))
        if norm > 0:
            collapsed_state /= norm
            
        return collapsed_state
    
    def update_focus(self, new_focus):
        """Изменение уровня фокусировки"""
        self.focus = max(0.0, min(1.0, new_focus))
        
    def update_intention(self, new_phase):
        """Изменение намерения (фазы)"""
        self.phase = new_phase % (2*np.pi)

