# --- CLASS: SpiderWeaver ---
class SpiderWeaver:
    def __init__(self, pattern_type="radial"):
        self.pattern = pattern_type
        self.tension_sensor = 0.0

    def weave(self, speed, tension_threshold=0.5):
        # Генерация точек плетения в зависимости от паттерна
        if self.pattern == "radial":
            points = self.generate_radial_points(8)  # 8 лучей
        elif self.pattern == "spiral":
            points = self.generate_spiral_points()
        else:
            raise ValueError("Unknown pattern")

        # Движение робота по точкам с контролем натяжения
        for point in points:
            self.move_to(point)
            self.adjust_tension(speed, tension_threshold)

    def generate_radial_points(self, n_rays):
        angles = np.linspace(0, 2*np.pi, n_rays, endpoint=False)
        radius = 1.0
        return [(radius * np.cos(angle), radius * np.sin(angle)) for angle in angles]

    def move_to(self, point):
        print(f"Moving to {point}")

    def adjust_tension(self, speed, threshold):
        # Считываем показания датчика натяжения
        current_tension = self.read_tension_sensor()
        if current_tension > threshold:
            self.reduce_speed(speed * 0.9)
        else:
            self.maintain_speed(speed)

    def read_tension_sensor(self):
        # Здесь реальное считывание с датчика
        return self.tension_sensor

# --- CLASS: ProjectData ---
class ProjectData:
    def __init__(self):
        # Инициализируем данные строго по EMOJI_MAP
        self.data: Dict[str, Dict[str, Any]] = {emoji: {} for emoji in EMOJI_MAP.values()}
        self.history = []
        # При создании объекта проверяем, что он корректный
        self._validate_invariant()

    def _validate_invariant(self) -> None:
        """Приватный метод для проверки ключевого инварианта системы.
        Гарантирует, что структура self.data всегда соответствует EMOJI_MAP.
        Вызывается после операций, которые потенциально могут его нарушить."""
        # 1. Проверяем, что ключи в self.data в точности совпадают с EMOJI_MAP
        if set(self.data.keys()) != set(EMOJI_MAP.values()):
            raise ValueError(
                f"Нарушен инвариант структуры данных. "
                f"Ожидались ключи: {set(EMOJI_MAP.values())}, "
                f"получены: {set(self.data.keys())}"
            )
        # 2. Проверяем, что значения являются словарями
        for emoji, content in self.data.items():
            if not isinstance(content, dict):
                raise TypeError(
                    f"Нарушен инвариант типа данных в разделе {emoji}. "
                    f"Ожидался dict, получен {type(content)}."
                )
        # Если все проверки прошли, инвариант соблюден
        print("✅ Инвариант структуры данных соблюден.")

    def update_section(self, section_emoji: str, updates: Dict[str, Any]) -> None:
        if section_emoji not in self.data:
            raise ValueError(f"Раздел с эмодзи {section_emoji} не найден")
        self.data[section_emoji].update(updates)
        self.history.append({
            'timestamp': datetime.now().isoformat(),
            'section': section_emoji,
            'updates': updates
        })
        # После изменения данных проверяем инвариант
        self._validate_invariant()

