# --- CLASS: FractalNode ---
class FractalNode:
    """Узел фрактального контейнера. Самоподобен на каждом уровне."""

    __slots__ = ("name", "_data", "_children", "_meta", "_frozen", "_hash")

    def __init__(self, name: str, data: Any = None, meta: Optional[dict] = None):
        self.name = name
        self._data = data
        self._children: dict[str, "FractalNode"] = {}
        self._frozen = False
        self._hash: Optional[str] = None
        self._meta = meta or {
            "created": time.time(),
            "modified": time.time(),
            "version": 1,
        }

    # ── Доступ по пути "a.b.c" ──────────────────────────────
    def __getitem__(self, path: str) -> Any:
        parts = path.split(".")
        node = self
        for p in parts:
            if p in node._children:
                node = node._children[p]
            else:
                raise KeyError(f"Путь не найден: {path!r} (сломался на {p!r})")
        return node._data

    def __setitem__(self, path: str, value: Any) -> None:
        if self._frozen:
            raise RuntimeError(f"Узел {self.name!r} заморожен — нельзя менять.")
        parts = path.split(".")
        node = self
        for p in parts[:-1]:
            if p not in node._children:
                node._children[p] = FractalNode(p)
            node = node._children[p]
        last = parts[-1]
        if last in node._children:
            node._children[last]._data = value
            node._children[last]._touch()
        else:
            node._children[last] = FractalNode(last, value)
        self._touch()

    def __contains__(self, path: str) -> bool:
        try:
            self[path]
            return True
        except KeyError:
            return False

    def __iter__(self) -> Iterator[str]:
        """Итерация по путям листьев."""
        for name, child in self._children.items():
            if child._children:
                for sub in child:
                    yield f"{name}.{sub}"
            else:
                yield name

    def __repr__(self) -> str:
        marker = "🔒" if self._frozen else "🔓"
        return f"<FractalNode {marker} {self.name!r} children={len(self._children)}>"

    # ── Данные и потомки ────────────────────────────────────
    @property
    def data(self) -> Any:
        return self._data

    @property
    def children(self) -> dict[str, "FractalNode"]:
        return dict(self._children)

    @property
    def is_frozen(self) -> bool:
        return self._frozen

    def add_child(self, name: str, data: Any = None) -> "FractalNode":
        if self._frozen:
            raise RuntimeError(f"Узел {self.name!r} заморожен.")
        if name not in self._children:
            self._children[name] = FractalNode(name, data)
        self._touch()
        return self._children[name]

    def get_child(self, name: str) -> Optional["FractalNode"]:
        return self._children.get(name)

    # ── Заморозка (для сохранения) ──────────────────────────
    def freeze(self) -> "FractalNode":
        """Заморозить узел и всё поддерево. После — только чтение."""
        self._frozen = True
        self._hash = self._compute_hash()
        for child in self._children.values():
            child.freeze()
        return self

    def unfreeze(self) -> "FractalNode":
        self._frozen = False
        for child in self._children.values():
            child.unfreeze()
        return self

    # ── Целостность ─────────────────────────────────────────
    def _compute_hash(self) -> str:
        payload = json.dumps(
            self.to_dict(), sort_keys=True, ensure_ascii=False,
        ).encode("utf-8")
        return hashlib.sha256(payload).hexdigest()

    def verify(self) -> bool:
        """Проверить, что узел не менялся после freeze()."""
        if not self._frozen or self._hash is None:
            return True
        return self._hash == self._compute_hash()

    # ── Сериализация ────────────────────────────────────────
    def to_dict(self) -> dict:
        return {
            "name": self.name,
            "data": self._data,
            "meta": self._meta,
            "children": {n: c.to_dict() for n, c in self._children.items()},
        }

    @classmethod
    def from_dict(cls, d: dict) -> "FractalNode":
        node = cls(d["name"], d.get("data"), d.get("meta"))
        for name, child_dict in (d.get("children") or {}).items():
            node._children[name] = cls.from_dict(child_dict)
        return node

    # ── Кодирование в компактную строку ─────────────────────
    def dumps(self, compress: bool = True) -> str:
        """Сериализовать в строку (JSON → gzip → base64)."""
        raw = json.dumps(self.to_dict(), ensure_ascii=False).encode("utf-8")
        if compress:
            raw = gzip.compress(raw, compresslevel=9)
        return base64.b64encode(raw).decode("ascii")

    @classmethod
    def loads(cls, s: str, compressed: bool = True) -> "FractalNode":
        """Загрузить из строки."""
        raw = base64.b64decode(s.encode("ascii"))
        if compressed:
            raw = gzip.decompress(raw)
        return cls.from_dict(json.loads(raw.decode("utf-8")))

    # ── Внутренние ──────────────────────────────────────────
    def _touch(self) -> None:
        self._meta["modified"] = time.time()
        self._meta["version"] = self._meta.get("version", 1) + 1

    # ── Рекурсивные операции ────────────────────────────────
    def walk(self, prefix: str = "") -> Iterator[tuple[str, "FractalNode"]]:
        """Обойти всё дерево, отдавая (путь, узел)."""
        for name, child in self._children.items():
            full = f"{prefix}{name}"
            yield full, child
            yield from child.walk(prefix=f"{full}.")

    def merge(self, other: "FractalNode") -> "FractalNode":
        """Слить другое дерево в это (по узлам, другие не трогаем)."""
        if self._frozen:
            raise RuntimeError(f"Узел {self.name!r} заморожен.")
        if other.data is not None:
            self._data = other.data
        for name, child in other._children.items():
            if name in self._children:
                self._children[name].merge(child)
            else:
                self._children[name] = child
        self._touch()
        return self

