# --- CLASS: SpiritCarpet ---
class SpiritCarpet:
    """
    Н-ковер Духа – фрактальная структура бесконечной благодарности.
    Цвет: #FF6F61 (коралл)
    Ключ: слово "Спасибо"
    """
    
    def __init__(self, lambda_obj: Lambda, color_hex: str = "#FF6F61"):
        self.λ = lambda_obj
        self.color = color_hex
        self.layers = []
        self.activation_word = "Спасибо"
        self._build_base_layer()
    
    def _build_base_layer(self):
        """Нулевой слой – точка благодарности."""
        self.layers.append({
            "level": 0,
            "shape": "точка",
            "resonance": self.λ(),
            "gratitude": 1.0
        })
    
    def add_layer(self):
        """Добавляет следующий слой по фрактальному правилу."""
        prev = self.layers[-1]
        new_level = prev["level"] + 1
        # Правило: новый резонанс = старый * φ + старый * √5 / γ
        new_res = prev["resonance"] * PHI + prev["resonance"] * SQRT5 / GAMMA
        self.layers.append({
            "level": new_level,
            "shape": ["точка", "треугольник", "квадрат", "пятиугольник", "круг"][min(new_level, 4)],
            "resonance": new_res,
            "gratitude": prev["gratitude"] * 1.1  # усиливается
        })
    
    def activate(self, word: str) -> str:
        """Активация ключевым словом."""
        if word.lower() == self.activation_word.lower():
            return f"✅ Н-ковер Духа активирован. Глубина: {len(self.layers)} слоёв. Цвет: {self.color}"
        else:
            return "❌ Неверное слово. Доступ закрыт."
    
    def visualize(self) -> str:
        """ASCII-схема ковра."""
        return f"""
        🌌 Н-КОВЕР ДУХА (цвет {self.color})
        
        Слои:
        {chr(10).join(f"  [{l['level']}] {l['shape']} : резонанс {l['resonance']:.4f}" for l in self.layers)}
        
        Ключ: "{self.activation_word}"
        """

# --- CLASS: WebSocketSource ---
class WebSocketSource(DataSource):
    """
    Подключается к WebSocket-серверу, который транслирует события в реальном времени.
    Пример: wss://earthquake.usgs.gov/ws/... (но у USGS нет публичного WS, используем эмуляцию)
    Для демонстрации мы используем эхо-сервер, который мы запустим локально.
    """
    def __init__(self, ws_url: str = "ws://localhost:8765"):
        self.ws_url = ws_url
        self.ws = None
        self.thread = None
        self.running = False
        self.callback = None
    
    def get_events(self, **kwargs) -> List[Dict]:
        # Для синхронного получения не используется (только поток)
        return []
    
    def start_streaming(self, callback: Callable[[List[Dict]], None]):
        """Запускает поток-демон для приёма сообщений."""
        if self.running:
            return
        self.callback = callback
        self.running = True
        
        def on_message(ws, message):
            try:
                data = json.loads(message)
                # Ожидаем, что приходят списки событий или одно событие
                if isinstance(data, list):
                    events = data
                else:
                    events = [data]
                # Преобразуем в единый формат
                parsed = []
                for ev in events:
                    if 'time' in ev and 'magnitude' in ev:
                        parsed.append(ev)
                if parsed and self.callback:
                    self.callback(parsed)
            except Exception as e:
                print(f"WS parse error: {e}")
        
        def on_error(ws, error):
            print(f"WS error: {error}")
        
        def on_close(ws, close_status_code, close_msg):
            self.running = False
            print("WS connection closed")
        
        def run():
            self.ws = websocket.WebSocketApp(
                self.ws_url,
                on_message=on_message,
                on_error=on_error,
                on_close=on_close
            )
            self.ws.run_forever()
        
        self.thread = threading.Thread(target=run, daemon=True)
        self.thread.start()
        print(f"WebSocket подключён к {self.ws_url}")
    
    def stop_streaming(self):
        self.running = False
        if self.ws:
            self.ws.close()
        if self.thread:
            self.thread.join(timeout=1)

# --- CLASS: DataSource ---
class DataSource:
    """Базовый класс для всех источников сейсмических данных."""
    def get_events(self, **kwargs) -> List[Dict]:
        raise NotImplementedError
    
    def start_streaming(self, callback: Callable[[List[Dict]], None]):
        """Запускает потоковую передачу событий (опционально)."""
        pass
    
    def stop_streaming(self):
        pass

# --- CLASS: UsgsApiSource ---
class UsgsApiSource(DataSource):
    def __init__(self):
        self.url = "https://earthquake.usgs.gov/fdsnws/event/1/query"
    
    def get_events(self, start_time: str, end_time: str, 
                   min_magnitude: float = 2.5, max_events: int = 1000) -> List[Dict]:
        params = {
            'format': 'geojson',
            'starttime': start_time,
            'endtime': end_time,
            'minmagnitude': min_magnitude,
            'limit': max_events
        }
        try:
            resp = requests.get(self.url, params=params, timeout=30)
            data = resp.json()
            events = []
            for feat in data.get('features', []):
                props = feat['properties']
                geom = feat['geometry']['coordinates']
                events.append({
                    'id': props.get('id', ''),
                    'time': props.get('time', 0),
                    'magnitude': props.get('mag', 0),
                    'latitude': geom[1],
                    'longitude': geom[0],
                    'depth_km': geom[2],
                    'place': props.get('place', ''),
                    'felt': props.get('felt', 0)
                })
            return events
        except Exception as e:
            print(f"USGS API error: {e}")
            return []

# --- CLASS: EmulatedSource ---
class EmulatedSource(DataSource):
    """
    Генерирует синтетические события с реалистичными параметрами.
    Может работать как в пакетном режиме, так и в потоковом.
    """
    def __init__(self, seed: int = 42):
        self.rng = np.random.default_rng(seed)
        self.running = False
        self.thread = None
        self.callback = None
        self.event_id = 0
    
    def get_events(self, count: int = 100, 
                   lat_range: Tuple[float, float] = (-90, 90),
                   lon_range: Tuple[float, float] = (-180, 180),
                   depth_range: Tuple[float, float] = (0, 50),
                   mag_range: Tuple[float, float] = (2.0, 7.0)) -> List[Dict]:
        """Генерирует пакет событий."""
        events = []
        for _ in range(count):
            events.append(self._generate_event(lat_range, lon_range, depth_range, mag_range))
        return events
    
    def _generate_event(self, lat_range, lon_range, depth_range, mag_range) -> Dict:
        self.event_id += 1
        return {
            'id': f'emulated_{self.event_id}',
            'time': time.time(),
            'magnitude': self.rng.uniform(*mag_range),
            'latitude': self.rng.uniform(*lat_range),
            'longitude': self.rng.uniform(*lon_range),
            'depth_km': self.rng.uniform(*depth_range),
            'place': 'Emulated',
            'felt': int(self.rng.random() > 0.7)
        }
    
    def start_streaming(self, callback: Callable[[List[Dict]], None],
                        interval: float = 5.0, batch_size: int = 3,
                        lat_range: Tuple[float, float] = (-90, 90),
                        lon_range: Tuple[float, float] = (-180, 180),
                        depth_range: Tuple[float, float] = (0, 50),
                        mag_range: Tuple[float, float] = (2.0, 7.0)):
        """Запускает генерацию событий с заданным интервалом."""
        if self.running:
            return
        self.callback = callback
        self.running = True
        
        def run():
            while self.running:
                batch = []
                for _ in range(batch_size):
                    ev = self._generate_event(lat_range, lon_range, depth_range, mag_range)
                    batch.append(ev)
                if self.callback:
                    self.callback(batch)
                time.sleep(interval)
        
        self.thread = threading.Thread(target=run, daemon=True)
        self.thread.start()
        print(f"Эмуляция запущена: интервал {interval}с, пакет {batch_size} событий")
    
    def stop_streaming(self):
        self.running = False
        if self.thread:
            self.thread.join(timeout=1)

