# --- CLASS: SeismoPhononAnalyzer ---
class SeismoPhononAnalyzer:
    def __init__(self, source: DataSource = None):
        self.source = source or UsgsApiSource()
        self.events = []
        self.phonon_model = None
        self.analyzer = PatternAnalyzer()
        self.dashboard = None
        self.report = {}
        self.streaming_active = False
    
    def load_data(self, **kwargs):
        """Загружает исторические данные из текущего источника."""
        if isinstance(self.source, UsgsApiSource):
            # Передаём параметры для USGS
            self.events = self.source.get_events(**kwargs)
        elif isinstance(self.source, EmulatedSource):
            self.events = self.source.get_events(**kwargs)
        else:
            print("Источник не поддерживает пакетную загрузку")
        return self.events
    
    def start_live_feed(self, callback: Optional[Callable] = None):
        """
        Запускает потоковое получение данных.
        При каждом новом пакете вызывается callback или обновляется внутренний буфер.
        """
        def default_callback(new_events):
            self.events.extend(new_events)
            # Ограничим размер буфера, чтобы не переполнять память
            if len(self.events) > 10000:
                self.events = self.events[-5000:]
            print(f"Получено {len(new_events)} новых событий. Всего: {len(self.events)}")
            # Здесь можно автоматически запускать анализ или воздействие
            # Например, вызвать метод для обработки порции данных
        
        cb = callback or default_callback
        if hasattr(self.source, 'start_streaming'):
            self.source.start_streaming(cb)
            self.streaming_active = True
        else:
            print("Источник не поддерживает потоковый режим.")
    
    def stop_live_feed(self):
        if hasattr(self.source, 'stop_streaming'):
            self.source.stop_streaming()
            self.streaming_active = False

# --- CLASS: MessageParser ---
class MessageParser:
    """
    Универсальный парсер для сообщений WebSocket.
    Настраивается через конфигурацию преобразования полей.
    """
    def __init__(self, config: Optional[Dict] = None):
        """
        config — словарь с настройками:
        {
            'event_path': список ключей для извлечения списка событий,
            'field_mapping': { 'time': 'properties.time', 'magnitude': 'properties.mag', ... },
            'is_array': False,  # True если сообщение уже массив событий
            'id_field': 'id',
            'time_converter': 'timestamp_ms',  # или 'iso', или 'epoch'
            'defaults': { 'felt': 0 }
        }
        """
        self.config = config or {}
        self._compiled_paths = {}
        # Если задан field_mapping, компилируем пути
        if 'field_mapping' in self.config:
            for dst, src in self.config['field_mapping'].items():
                self._compiled_paths[dst] = src.split('.')
    
    def parse(self, raw_message: str) -> List[Dict]:
        """
        Основной метод: принимает сырую строку, возвращает список событий.
        """
        try:
            data = json.loads(raw_message)
        except json.JSONDecodeError:
            print("Неверный JSON")
            return []
        
        # Если конфигурация говорит, что это массив
        if self.config.get('is_array', False):
            events_data = data if isinstance(data, list) else []
        else:
            # Иначе извлекаем по пути event_path
            events_data = self._extract_by_path(data, self.config.get('event_path', []))
            if not isinstance(events_data, list):
                # Может быть одно событие, обернём в список
                events_data = [events_data] if events_data else []
        
        # Преобразуем каждое событие
        parsed_events = []
        for raw_event in events_data:
            if not isinstance(raw_event, dict):
                continue
            event = self._transform_event(raw_event)
            if event:
                parsed_events.append(event)
        
        return parsed_events
    
    def _extract_by_path(self, data: Any, path: List[str]) -> Any:
        """Извлекает значение по вложенным ключам."""
        current = data
        for key in path:
            if isinstance(current, dict) and key in current:
                current = current[key]
            else:
                return None
        return current
    
    def _transform_event(self, raw: Dict) -> Optional[Dict]:
        """Преобразует сырое событие в единый формат."""
        event = {}
        # Если есть field_mapping — применяем его
        if self._compiled_paths:
            for dst, src_path in self._compiled_paths.items():
                value = self._extract_by_path(raw, src_path)
                if value is not None:
                    event[dst] = value
                else:
                    # Ищем в defaults
                    if dst in self.config.get('defaults', {}):
                        event[dst] = self.config['defaults'][dst]
        else:
            # Если маппинга нет, пытаемся использовать стандартные ключи
            for key in ['id', 'time', 'magnitude', 'latitude', 'longitude', 'depth_km', 'place', 'felt']:
                if key in raw:
                    event[key] = raw[key]
                elif key in self.config.get('defaults', {}):
                    event[key] = self.config['defaults'][key]
        
        # Обязательные поля
        required = ['time', 'magnitude', 'latitude', 'longitude']
        if not all(k in event for k in required):
            return None  # пропускаем неполные события
        
        # Конвертация времени
        if 'time' in event and 'time_converter' in self.config:
            event['time'] = self._convert_time(event['time'], self.config['time_converter'])
        
        return event
    
    def _convert_time(self, value, converter_type: str):
        """Преобразует время в Unix-миллисекунды (для единообразия)."""
        if converter_type == 'timestamp_ms':
            return int(value)  # уже миллисекунды
        elif converter_type == 'timestamp_s':
            return int(value * 1000)
        elif converter_type == 'iso':
            from datetime import datetime
            dt = datetime.fromisoformat(value.replace('Z', '+00:00'))
            return int(dt.timestamp() * 1000)
        else:
            return value

# --- CLASS: UniverseNoiseGenerator ---
class UniverseNoiseGenerator:
    """
    Генерирует многокомпонентный звуковой сигнал, имитирующий шум космоса,
    сейсмический гул и квантовые флуктуации.
    """
    def __init__(self, duration=10.0, sample_rate=44100):
        self.duration = duration
        self.sample_rate = sample_rate
        self.t = np.linspace(0, duration, int(sample_rate * duration))
        self.frequencies = []
        self.amplitudes = []

    def add_cmb_spectrum(self):
        """Реликтовое излучение — шум с пиком ~160 ГГц, но мы масштабируем в слышимый диапазон."""
        # Масштабируем в диапазон 100-2000 Гц
        freqs = np.linspace(100, 2000, 50)
        # Планковский спектр (приближённо)
        T = 2.725  # K
        h = 6.626e-34
        k = 1.38e-23
        # Для видимости, просто гауссов пик
        amplitudes = np.exp(-((freqs - 1000)**2) / (200**2))
        self.frequencies.extend(freqs)
        self.amplitudes.extend(amplitudes * 0.5)

    def add_seismic_rumble(self):
        """Сейсмические колебания (0.01-10 Гц), сдвигаем в слышимый диапазон."""
        freqs = np.linspace(1, 50, 30)
        amplitudes = 1 / (freqs + 1)  # спадает с частотой
        self.frequencies.extend(freqs * 10)  # сдвиг вверх
        self.amplitudes.extend(amplitudes * 0.3)

    def add_quantum_noise(self):
        """Квантовые флуктуации — высокочастотный треск."""
        freqs = np.linspace(2000, 8000, 20)
        amplitudes = np.random.uniform(0.1, 0.5, len(freqs))
        self.frequencies.extend(freqs)
        self.amplitudes.extend(amplitudes * 0.2)

    def add_string_harmonics(self):
        """Струнные гармоники (φ, √5, γ)."""
        phi = 1.618
        sqrt5 = 2.236
        gamma = 7.0
        base_freqs = [phi * 100, sqrt5 * 100, gamma * 20]
        for base in base_freqs:
            for mult in [1, 2, 3, 4, 5]:
                self.frequencies.append(base * mult)
                self.amplitudes.append(1.0 / (mult + 0.5))

    def generate_signal(self):
        """Суммирует все компоненты и возвращает звуковой сигнал."""
        self.add_cmb_spectrum()
        self.add_seismic_rumble()
        self.add_quantum_noise()
        self.add_string_harmonics()

        signal = np.zeros_like(self.t)
        for f, a in zip(self.frequencies, self.amplitudes):
            signal += a * np.sin(2 * np.pi * f * self.t + np.random.uniform(0, 2*np.pi))
        # Нормализация
        signal = signal / np.max(np.abs(signal))
        return signal, self.t

# --- CLASS: AudioToImageMapper ---
class AudioToImageMapper:
    """
    Обучается на парах (звуковой спектр → изображение) и генерирует картинку из звука.
    """
    def __init__(self):
        self.model = None
        self.image_size = 64

    def generate_training_data(self, n_samples=200):
        """
        Создаёт синтетические данные: спектры и соответствующие им галактики/звёздные поля.
        """
        X = []  # спектры (векторы частот)
        y = []  # изображения (уплощённые)
        for _ in range(n_samples):
            # Генерируем случайный спектр (имитация частот)
            freqs = np.random.uniform(0.1, 1.0, 50)
            spec = np.random.uniform(0, 1, 50) * np.exp(-freqs * 2)
            # Генерируем изображение: набор точек (галактик)
            img = np.zeros((self.image_size, self.image_size))
            n_points = np.random.randint(5, 20)
            for _ in range(n_points):
                x = np.random.randint(0, self.image_size)
                y = np.random.randint(0, self.image_size)
                r = np.random.randint(2, 8)
                img[x-r:x+r, y-r:y+r] += 1.0 / (1 + np.abs(np.arange(-r, r)))
            img = img / np.max(img)
            X.append(spec)
            y.append(img.flatten())
        return np.array(X), np.array(y)

    def train(self):
        """Обучает нейросеть на синтетических данных."""
        X, y = self.generate_training_data(300)
        self.model = MLPRegressor(hidden_layer_sizes=(100, 50), max_iter=200, random_state=42)
        self.model.fit(X, y)
        print("ML-модель обучена на синтетических данных.")
        return self.model

    def predict_image(self, spectrum):
        """
        Преобразует спектр в изображение.
        spectrum: вектор амплитуд частот.
        """
        if self.model is None:
            self.train()
        X_input = np.array(spectrum).reshape(1, -1)
        img_flat = self.model.predict(X_input)[0]
        img = img_flat.reshape(self.image_size, self.image_size)
        # Нормализация
        img = (img - img.min()) / (img.max() - img.min() + 1e-8)
        return img

# --- CLASS: UniverseAudioInterfaceV2 ---
class UniverseAudioInterfaceV2:
    def __init__(self, duration=10.0):
        self.duration = duration
        self.noise_gen = UniverseNoiseGenerator(duration=duration)
        self.mapper = AudioToImageMapper()
        self.mapper.train()
        self.signal, self.t = self.noise_gen.generate_signal()
        self.sample_rate = self.noise_gen.sample_rate

    def play_audio(self):
        """Проигрывает звук в Jupyter."""
        return display.Audio(self.signal, rate=self.sample_rate, autoplay=True)

    def run_live_demo(self, update_interval=0.3):
        """
        Запускает анимацию: в реальном времени меняет изображение,
        синхронизированное со звуком (звук идёт отдельно через Audio).
        """
        # Воспроизводим звук
        print("🔊 Включаю звук Вселенной...")
        audio_display = self.play_audio()
        display.display(audio_display)

        # Готовим фигуру
        fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(12, 6))
        ax1.set_title('Спектр текущего фрагмента')
        ax1.set_xlabel('Частота (Гц)')
        ax1.set_ylabel('Амплитуда')
        ax2.set_title('Образ Вселенной')
        ax2.axis('off')

        fs = self.sample_rate
        window_size = 2048
        step = int(fs * update_interval)

        # Функция обновления
        def update(frame_idx):
            start = frame_idx * step
            if start + window_size > len(self.signal):
                return
            chunk = self.signal[start:start+window_size]
            spectrum = np.abs(fft(chunk))[:window_size//2]
            freq_axis = np.linspace(0, fs/2, len(spectrum))

            # Ограничиваем до интересующего диапазона (0-4000 Гц)
            mask = freq_axis <= 4000
            freq_axis = freq_axis[mask]
            spectrum = spectrum[mask]

            ax1.clear()
            ax1.plot(freq_axis, spectrum, color='cyan')
            ax1.set_title('Спектр')
            ax1.set_xlim(0, 4000)

            # Логарифмический спектр для модели
            log_spec = np.log1p(spectrum[:100])  # первые 100 бинов
            if len(log_spec) < 100:
                log_spec = np.pad(log_spec, (0, 100 - len(log_spec)))
            img = self.mapper.predict_image(log_spec)
            ax2.clear()
            ax2.imshow(img, cmap='inferno', origin='lower')
            ax2.axis('off')
            ax2.set_title('Галактическое поле')

        frames = (len(self.signal) - window_size) // step
        ani = FuncAnimation(fig, update, frames=frames, interval=update_interval*1000, blit=False)
        plt.tight_layout()
        plt.show()
        return ani

# --- CLASS: UniverseAudioInterface ---
class UniverseAudioInterface:
    """
    Главный класс. В реальном времени генерирует звук, преобразует в образ,
    и отображает анимацию.
    """
    def __init__(self):
        self.noise_gen = UniverseNoiseGenerator()
        self.mapper = AudioToImageMapper()
        self.mapper.train()
        self.spectrum_history = []
        self.image_history = []

    def run_live_demo(self, duration=10):
        """
        Запускает демонстрацию: генерирует шум, каждые 0.5 сек обновляет образ.
        """
        print("🌌 Запуск интерфейса «Услышать Вселенную»")
        print("Генерация звукового шума и визуализация...")
        signal, t = self.noise_gen.generate_signal()
        # Параметры спектра
        fs = self.noise_gen.sample_rate
        window_size = 1024
        overlap = 512

        # Подготовка анимации
        fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(12, 6))
        ax1.set_title('Спектр')
        ax1.set_xlabel('Частота (Гц)')
        ax1.set_ylabel('Амплитуда')
        ax2.set_title('Изображение (галактическое поле)')
        ax2.axis('off')

        # Обновляемая функция
        def update(frame):
            # Берём кусок сигнала
            start = frame * 512
            if start + window_size > len(signal):
                return
            chunk = signal[start:start+window_size]
            # Спектр
            f, spectrum = np.abs(fft(chunk))[:window_size//2], np.abs(fft(chunk))[:window_size//2]
            freq_axis = np.linspace(0, fs/2, len(spectrum))
            # Показываем спектр
            ax1.clear()
            ax1.plot(freq_axis[:200], spectrum[:200])  # первые 200 частот
            ax1.set_title('Спектр')
            # Генерируем изображение из спектра (усредняем по логарифмической шкале)
            log_spectrum = np.log1p(spectrum[:100])  # 100 частотных бинов
            img = self.mapper.predict_image(log_spectrum)
            ax2.clear()
            ax2.imshow(img, cmap='viridis', origin='lower')
            ax2.axis('off')
            ax2.set_title('Вселенная (сгенерированный образ)')
            return ax1, ax2

        ani = FuncAnimation(fig, update, frames=len(signal)//512, interval=200, blit=False)
        plt.tight_layout()
        plt.show()
        return ani

# --- CLASS: AerosolEnv ---
class AerosolEnv(gym.Env):
    def __init__(self, grid_size=30, world_size=1000, max_mass=200, capture_radius=50,
                 wind=(5.0, 0.0), D=10.0, ws=0.1, dt=1.0):
        super(AerosolEnv, self).__init__()
        self.grid_size = grid_size
        self.world_size = world_size
        self.cell_size = world_size / grid_size
        self.max_mass = max_mass
        self.capture_radius = capture_radius
        self.wind = np.array(wind, dtype=np.float32)
        self.D = D
        self.ws = ws
        self.dt = dt

        # Наблюдение: сетка концентрации
        self.observation_space = spaces.Box(low=0, high=np.inf, shape=(grid_size, grid_size), dtype=np.float32)
        # Действие: [x, y, mass]  (x,y ∈ [-500,500] чтобы не вылетать за границы)
        self.action_space = spaces.Box(low=np.array([-world_size/2, -world_size/2, 0]),
                                       high=np.array([world_size/2, world_size/2, max_mass]),
                                       dtype=np.float32)

        self.reset()

    def reset(self):
        self.puffs = []
        self.remaining_mass = self.max_mass
        self.time = 0.0
        self.steps = 0
        self.captured = False
        self.done = False
        self.concentration = np.zeros((self.grid_size, self.grid_size))
        return self._get_state()

    def _get_state(self):
        return self.concentration.copy()

    def _compute_concentration(self):
        conc = np.zeros((self.grid_size, self.grid_size))
        for puff in self.puffs:
            age = self.time - puff.t0
            if age <= 0:
                continue
            sigma = np.sqrt(2 * self.D * age)
            # Дрейф
            x_center = puff.x0 + self.wind[0] * age
            y_center = puff.y0 + self.wind[1] * age
            # Диапазон влияния (3 сигмы)
            rad = 3 * sigma
            # Определяем индексы клеток, попадающих в квадрат [x_center-rad, x_center+rad]
            ix_min = max(0, int((x_center - rad + self.world_size/2) // self.cell_size))
            ix_max = min(self.grid_size-1, int((x_center + rad + self.world_size/2) // self.cell_size))
            iy_min = max(0, int((y_center - rad + self.world_size/2) // self.cell_size))
            iy_max = min(self.grid_size-1, int((y_center + rad + self.world_size/2) // self.cell_size))
            for i in range(ix_min, ix_max+1):
                for j in range(iy_min, iy_max+1):
                    x_cell = (i - self.grid_size//2) * self.cell_size
                    y_cell = (j - self.grid_size//2) * self.cell_size
                    dx = x_cell - x_center
                    dy = y_cell - y_center
                    r2 = dx*dx + dy*dy
                    if r2 > (3*sigma)**2:
                        continue
                    conc[j,i] += puff.mass / (2 * np.pi * sigma**2) * np.exp(-r2 / (2*sigma**2))
        return conc

    def step(self, action):
        x, y, mass = action
        mass = np.clip(mass, 0, self.remaining_mass)
        self.remaining_mass -= mass
        # Добавляем новый пуфф, если масса > 0
        if mass > 0:
            self.puffs.append(Puff(x, y, mass, self.time))

        # Обновляем время
        self.time += self.dt
        self.steps += 1

        # Пересчитываем концентрацию
        self.concentration = self._compute_concentration()

        # Проверка захвата
        captured = self._check_capture()
        reward = 0.0
        if captured:
            reward = 1000 - 0.01 * (self.max_mass - self.remaining_mass) - 0.1 * self.steps
            self.done = True
            return self._get_state(), reward, True, {'captured': True}

        # Награда за каждый шаг: штраф за использованную массу и время
        reward = -0.01 * (self.max_mass - self.remaining_mass) - 0.05

        # Если кончилось вещество или слишком много шагов
        if self.remaining_mass <= 0:
            reward -= 100
            self.done = True
        if self.steps >= 300:
            reward -= 50
            self.done = True

        return self._get_state(), reward, self.done, {}

    def _check_capture(self):
        # Цель в центре (0,0)
        target_cell = (self.grid_size//2, self.grid_size//2)
        # Просто проверяем концентрацию в центральной клетке
        if self.concentration[target_cell[1], target_cell[0]] > 0.05:
            return True
        return False

    def render(self, mode='human'):
        plt.imshow(self.concentration, origin='lower',
                   extent=[-self.world_size/2, self.world_size/2,
                           -self.world_size/2, self.world_size/2],
                   cmap='viridis')
        plt.colorbar()
        plt.title(f'Concentration, t={self.time:.0f}s, mass left={self.remaining_mass:.1f}kg')
        plt.show()

# --- CLASS: AntennaField ---
class AntennaField:
    """
    Модель поля от массива антенн с учётом диаграммы направленности.
    Каждая антенна характеризуется:
        - позицией (x,y,z)
        - амплитудой A
        - фазой phi
        - направлением главного луча (unit vector)
        - шириной луча (beamwidth, в радианах)
    Поле вычисляется как сумма вкладов каждой антенны:
        E_i(r) = A_i * exp(1j*phi_i) * G_i(θ) / |r - r_i|
    где G_i(θ) = exp(-θ²/(2σ²))  (гауссов луч), σ = beamwidth.
    """
    def __init__(self, positions, amplitudes=None, phases=None,
                 directions=None, beamwidth=0.5):
        """
        positions: (N,3) массив координат антенн
        amplitudes: (N,) амплитуды (по умолчанию 1)
        phases: (N,) фазы (радианы) (по умолчанию 0)
        directions: (N,3) единичные векторы направления луча (по умолчанию [0,0,1])
        beamwidth: ширина луча (радианы), по умолчанию 0.5 (~28°)
        """
        self.positions = np.asarray(positions, dtype=np.float32)
        self.N = len(self.positions)
        self.amplitudes = np.ones(self.N, dtype=np.float32) if amplitudes is None else np.asarray(amplitudes)
        self.phases = np.zeros(self.N, dtype=np.float32) if phases is None else np.asarray(phases)
        if directions is None:
            # по умолчанию все смотрят вверх (ось Z)
            self.directions = np.array([[0,0,1]] * self.N, dtype=np.float32)
        else:
            self.directions = np.asarray(directions, dtype=np.float32)
            # нормируем
            norms = np.linalg.norm(self.directions, axis=1, keepdims=True)
            self.directions = self.directions / norms
        self.beamwidth = beamwidth

    def _pattern(self, r_vecs, dirs):
        """
        Вычисляет значение диаграммы направленности для каждого вектора r_vecs
        относительно соответствующих направлений dirs.
        r_vecs: (...,3) массив векторов от антенны к точке
        dirs: (...,3) массив направлений лучей (широковещательно совместим)
        Возвращает массив pattern той же формы, что и r_vecs[...,0]
        """
        # Вычисляем косинус угла между r_vec и dir
        # Нормализуем r_vecs
        r_norm = np.linalg.norm(r_vecs, axis=-1, keepdims=True)
        # Избегаем деления на ноль
        r_norm = np.maximum(r_norm, 1e-8)
        unit_r = r_vecs / r_norm
        cos_theta = np.sum(unit_r * dirs, axis=-1)
        cos_theta = np.clip(cos_theta, -1, 1)
        theta = np.arccos(cos_theta)
        # Гауссов луч
        pattern = np.exp(-(theta**2) / (2 * self.beamwidth**2))
        return pattern

    def compute_field(self, X, Y, Z):
        """
        Вычисляет комплексное поле E в точках сетки (X,Y,Z).
        X,Y,Z - meshgrid (3D массивы).
        Возвращает комплексный массив E той же формы.
        """
        E = np.zeros_like(X, dtype=np.complex64)
        for i in range(self.N):
            # Вектор от антенны к точке
            rx = X - self.positions[i,0]
            ry = Y - self.positions[i,1]
            rz = Z - self.positions[i,2]
            r = np.sqrt(rx**2 + ry**2 + rz**2)
            r = np.maximum(r, 0.5)  # избегаем сингулярности
            # Направление от антенны к точке (для каждой точки)
            dir_x = rx / r
            dir_y = ry / r
            dir_z = rz / r
            # Формируем массив векторов (...,3)
            r_vec = np.stack([dir_x, dir_y, dir_z], axis=-1)
            # Направление луча для этой антенны (широковещательно)
            beam_dir = self.directions[i][None, None, None, :]
            pattern = self._pattern(r_vec, beam_dir)
            # Вклад антенны
            Ei = self.amplitudes[i] * pattern / r * np.exp(1j * self.phases[i])
            E += Ei
        return E

    def potential(self, X, Y, Z):
        """
        Пондеромоторный потенциал U = -|E|^2
        """
        E = self.compute_field(X, Y, Z)
        return -np.abs(E)**2

    def set_phases(self, phases):
        """Установить новые фазы"""
        self.phases = np.asarray(phases, dtype=np.float32)

    def set_amplitudes(self, amplitudes):
        self.amplitudes = np.asarray(amplitudes, dtype=np.float32)

    def set_directions(self, directions):
        self.directions = np.asarray(directions, dtype=np.float32)
        norms = np.linalg.norm(self.directions, axis=1, keepdims=True)
        self.directions = self.directions / norms

# --- CLASS: Puff ---
class Puff:
    def __init__(self, x, y, mass, t0):
        self.x0 = x
        self.y0 = y
        self.mass = mass
        self.t0 = t0

# --- CLASS: AcousticClassifier ---
class AcousticClassifier:
    def __init__(self):
        self.model = RandomForestClassifier(n_estimators=50, max_depth=10)
        self.is_trained = False
        self.feature_buffer = deque(maxlen=1000)
        self.label_buffer = deque(maxlen=1000)

    def extract_features(self, audio_chunk):
        # Эмуляция извлечения MFCC/спектральных признаков
        # В реальности здесь был бы librosa.feature.mfcc
        # Для симуляции — случайный вектор
        return np.random.randn(13)  # 13 MFCC-коэффициентов

    def train(self):
        if len(self.feature_buffer) < 50:
            return
        X = np.array(self.feature_buffer)
        y = np.array(self.label_buffer)
        self.model.fit(X, y)
        self.is_trained = True
        print(f"Модель обучена на {len(X)} примерах")

    def predict(self, audio_chunk):
        features = self.extract_features(audio_chunk)
        if self.is_trained:
            pred = self.model.predict([features])[0]
            proba = self.model.predict_proba([features])[0]
            return pred, max(proba)
        else:
            return -1, 0.0

    def add_sample(self, audio_chunk, label):
        features = self.extract_features(audio_chunk)
        self.feature_buffer.append(features)
        self.label_buffer.append(label)

# --- CLASS: LSTMPredictor ---
class LSTMPredictor(nn.Module):
    def __init__(self, input_size=1, hidden_size=64, num_layers=2, output_size=1):
        super().__init__()
        self.lstm = nn.LSTM(input_size, hidden_size, num_layers, batch_first=True)
        self.fc = nn.Linear(hidden_size, output_size)

    def forward(self, x):
        out, _ = self.lstm(x)
        out = self.fc(out[:, -1, :])
        return out.squeeze()

# --- CLASS: LpiDetector ---
class LpiDetector:
    def __init__(self, model_path, device='cpu', tfa_type='spectrogram'):
        self.device = torch.device(device)
        self.tfa_type = tfa_type  # 'spectrogram' or 'cwd'
        # Загружаем модель "студента"
        self.model = StudentModel(N_CLASSES=13, embed_dim=128)
        self.model.load_state_dict(torch.load(model_path, map_location=self.device))
        self.model.to(self.device)
        self.model.eval()
        # Словарь классов (пример)
        self.classes = ['Barker', 'Costas', 'LFM', 'Frank', 'Rect', 'P1', 'P2', 'P3', 'P4', 'T1', 'T2', 'T3', 'T4']

    def _compute_spectrogram(self, iq_samples, fs=2e6, nperseg=256):
        """Преобразует I/Q данные в спектрограмму (логарифмическую)"""
        f, t, Sxx = spectrogram(iq_samples, fs=fs, nperseg=nperseg, return_onesided=False)
        Sxx_log = 10 * np.log10(np.abs(Sxx) + 1e-12)
        # Нормализация к [0,1]
        Sxx_norm = (Sxx_log - Sxx_log.min()) / (Sxx_log.max() - Sxx_log.min())
        # Превращаем в 3D тензор (1, height, width) для Conv2d
        return torch.tensor(Sxx_norm, dtype=torch.float32).unsqueeze(0)

    def _compute_cwd(self, iq_samples):
        """Упрощённая версия CWD (псевдо-код, нужна реализация)"""
        # Здесь должна быть реализация Choi-Williams distribution
        # Для демонстрации используем спектрограмму
        return self._compute_spectrogram(iq_samples)

    def preprocess(self, iq_samples):
        if self.tfa_type == 'spectrogram':
            img = self._compute_spectrogram(iq_samples)
        elif self.tfa_type == 'cwd':
            img = self._compute_cwd(iq_samples)
        else:
            raise ValueError("Unsupported TFA type")
        # Добавляем размерность канала (1, H, W) -> (1, 1, H, W)
        return img.unsqueeze(0).to(self.device)

    def predict(self, iq_samples):
        """Принимает массив I/Q комплексных отсчётов, возвращает предсказанный класс и уверенность"""
        input_tensor = self.preprocess(iq_samples)
        with torch.no_grad():
            logits = self.model(input_tensor)
            probs = torch.softmax(logits, dim=1)
            conf, idx = torch.max(probs, dim=1)
        return self.classes[idx.item()], conf.item()

    def visualize_3d(self, iq_samples):
        """Создаёт 3D-визуализацию частотно-временной плоскости с наложением результата"""
        # Вычисляем спектрограмму для визуализации
        f, t, Sxx = spectrogram(iq_samples, fs=2e6, nperseg=256)
        Sxx_db = 10 * np.log10(np.abs(Sxx) + 1e-12)
        # Создаём meshgrid
        T, F = np.meshgrid(t, f)
        # Используем mayavi для поверхности
        mlab.figure(size=(800,600), bgcolor=(0,0,0))
        mlab.surf(T, F, Sxx_db, colormap='viridis', warp_scale='auto')
        mlab.title('3D Time-Frequency Representation')
        mlab.show()

# --- CLASS: CognitiveShieldForge ---
class CognitiveShieldForge(QuantumForge):
    def __init__(self, shield):
        super().__init__()
        self.shield = shield
        shield.forge = self

    def scan_shield_state(self):
        features = super().scan_shield_state()
        # Добавляем данные об акустике
        if self.shield.acoustic.is_trained:
            features['acoustic_accuracy'] = accuracy_score(
                self.shield.acoustic.label_buffer,
                self.shield.acoustic.model.predict(np.array(self.shield.acoustic.feature_buffer))
            )
        else:
            features['acoustic_accuracy'] = 0
        # Успешность резонанса
        if len(self.shield.history) > 0:
            successes = sum(1 for e in self.shield.history if e.get('success', False))
            features['resonance_success_rate'] = successes / len(self.shield.history)
        else:
            features['resonance_success_rate'] = 0
        return features

    def generate_resonance_hypotheses(self, drone_type='unknown'):
        # Используем константы для генерации частот
        base_freq = 1000 * self.phi  # 1618 Гц
        freq_candidates = [
            base_freq / self.sqrt5,   # ~723
            base_freq * self.sqrt5,   # ~3618
            base_freq * self.gamma / self.Lambda  # ~20490
        ]
        hypotheses = []
        for f in freq_candidates:
            hypotheses.append({
                'type': 'resonance',
                'frequency': f,
                'drone_type': drone_type,
                'confidence': 0.5 + 0.3 * np.random.rand(),
                'basis': 'constant_based'
            })
        return hypotheses

    def update_acoustic_strategy(self):
        # Получаем гипотезы для последнего обнаруженного типа
        if self.shield.detected_signals:
            last_type = self.shield.detected_signals[-1].get('type', 'unknown')
            hypotheses = self.generate_resonance_hypotheses(last_type)
            for hyp in hypotheses:
                self.shield.resonance_freqs[hyp['drone_type']] = hyp['frequency']
                print(f"🔊 Предложена частота {hyp['frequency']:.1f} Гц для {hyp['drone_type']}")
        return hypotheses

# --- CLASS: Antenna ---
class Antenna:
    def __init__(self, position, amplitude=1.0, phase=0.0, direction=(0,0,1), beam_width=np.pi/6):
        self.position = np.array(position, dtype=np.float32)
        self.amplitude = amplitude
        self.phase = phase
        self.direction = np.array(direction, dtype=np.float32)
        self.direction /= np.linalg.norm(self.direction)   # нормализация
        self.beam_width = beam_width                       # радианы
        self.sigma_beam = beam_width / 2.355               # для гауссовой аппроксимации

    def field(self, X, Y, Z):
        # X,Y,Z — meshgrid массивы
        # возвращает комплексное поле E (такой же формы)
        dx = X - self.position[0]
        dy = Y - self.position[1]
        dz = Z - self.position[2]
        r = np.sqrt(dx**2 + dy**2 + dz**2)
        r = np.maximum(r, 0.5)   # защита от деления на 0
        # угол между направлением и вектором к точке
        dot = (dx*self.direction[0] + dy*self.direction[1] + dz*self.direction[2]) / r
        dot = np.clip(dot, -1, 1)
        theta = np.arccos(dot)
        # гауссова диаграмма
        pattern = np.exp(- (theta**2) / (2 * self.sigma_beam**2))
        E = self.amplitude * pattern / r * np.exp(1j * self.phase)
        return E

# --- CLASS: Generator1729 ---
class Generator1729:
    def __init__(self):
        self.freq = 178.92  # Гц
        self.phi = (1+5**0.5)/2
        self.pi = 3.141592653589793
        self.dim = 6  # измерение
        self.base = 64
        self.n1729 = 1729
        self.n1723 = 1723
        
    def resonance(self):
        # Формула из третьей части (исправленная)
        a = self.n1729 / self.base / self.phi  # примерно 16.8
        b = self.n1729 / self.base / self.pi   # примерно 8.6
        return (a * self.phi + b * self.pi) / self.dim * self.base
    
    def spiral_length(self):
        return self.n1729 * self.phi / 1000  # метры
    
    def torus_radius(self):
        return self.n1729 / self.pi / 100  # метры
    
    def __str__(self):
        return f"1729(64)φπ-генератор: частота {self.freq:.2f} Гц, резонанс {self.resonance():.2f}"

# --- CLASS: CognitiveShieldDashboard ---
class CognitiveShieldDashboard:
    def __init__(self, shield, forge):
        self.shield = shield
        self.forge = forge
        self.last_update = 0
        
    def get_drone_positions(self):
        # Извлекаем данные из shield
        if hasattr(self.shield, 'drone_tracks'):
            return self.shield.drone_tracks
        return []
    
    def get_audio_spectrum(self):
        # Получаем спектрограмму из акустического модуля
        if hasattr(self.shield.acoustic, 'spectrogram'):
            return self.shield.acoustic.spectrogram
        return np.zeros((20, 50))
    
    def get_predictions(self):
        # Прогнозы от shield
        pred = {}
        if hasattr(self.shield, 'last_prediction'):
            pred['type'] = self.shield.last_prediction.get('type', 'Unknown')
            pred['next_freq'] = self.shield.last_prediction.get('freq', 0)
            pred['probability'] = self.shield.last_prediction.get('confidence', 0)
