# --- CLASS: QuantumForge ---
class QuantumForge:
    def __init__(self):
        # ... (предыдущая инициализация) ...
        self.time_explorer = TimeAgnosticExplorer()  # <-- НОВЫЙ МОДУЛЬ
        self.time_states = []  # история состояний вне времени
        self.time_current = None

    # ------------------- НОВЫЙ МЕТОД: ЭВОЛЮЦИЯ ВНЕ ВРЕМЕНИ -------------------
    def evolve_timeless(self, dimensions=4, steps=30, num_nodes=30, mode='spiral'):
        """
        Запускает эволюцию системы вне времени, используя TimeAgnosticExplorer.
        """
        self.time_explorer.dimensions = dimensions
        self.time_explorer.generate_state_space(num_nodes=num_nodes)
        if mode == 'spiral':
            self.time_states = self.time_explorer.evolve_without_time(steps)
        elif mode == 'massive':
            self.time_states = self.time_explorer.massive_iteration(iterations=100, batch_size=10)
        else:
            self.time_states = self.time_explorer.evolve_without_time(steps)
        self.time_current = self.time_states[-1] if self.time_states else None
        return self.time_states

    # ------------------- НОВЫЙ МЕТОД: АНАЛИЗ КОРРЕЛЯЦИЙ -------------------
    def analyze_time_correlations(self):
        """
        Возвращает меру запутанности и причинности из текущего состояния.
        """
        if self.time_current is None:
            return {'error': 'Сначала запустите эволюцию вне времени.'}
        corr = self.time_current.get('correlations')
        if corr is None:
            return {'error': 'Нет корреляций.'}
        return {
            'entanglement_measure': self.time_current.get('entanglement_measure', 0),
            'total_correlation': np.sum(np.abs(corr)),
            'avg_correlation': np.mean(np.abs(corr)),
            'dimensions': self.time_explorer.dimensions,
            'num_nodes': self.time_explorer.state_space['num_nodes'] if self.time_explorer.state_space else 0
        }

    # ------------------- НОВЫЙ МЕТОД: ВИЗУАЛИЗАЦИЯ -------------------
    def plot_time_state(self, state_index=-1):
        """
        Визуализирует состояние вне времени.
        """
        if not self.time_states:
            print("Нет состояний. Запустите evolve_timeless().")
            return
        self.time_explorer.plot_state(state_index)

    # ------------------- ОБНОВЛЁННЫЙ ИНТЕРФЕЙС -------------------
    def create_interface(self):
        # ... существующие кнопки ...
        # ДОБАВЛЯЕМ НОВЫЕ КНОПКИ
        time_btn = widgets.Button(description='🌀 Абсолютное настоящее', button_style='danger')
        time_analyze_btn = widgets.Button(description='📊 Анализ корреляций', button_style='info')
        time_plot_btn = widgets.Button(description='🖼️ Показать состояние', button_style='success')

        # --- Обработчики ---
        def on_time_evolve(b):
            with self.output:
                clear_output()
                status.value = "<b>Статус:</b> Эволюция вне времени..."
                # Запускаем с параметрами по умолчанию
                steps = self.time_steps_slider.value if hasattr(self, 'time_steps_slider') else 30
                dims = self.time_dims_slider.value if hasattr(self, 'time_dims_slider') else 4
                self.evolve_timeless(dimensions=dims, steps=steps, num_nodes=30, mode='spiral')
                print(f"Выполнено {len(self.time_states)} состояний в {self.time_explorer.dimensions}D.")
                # Обновляем статус
                status.value = f"<b>Статус:</b> Эволюция завершена ({len(self.time_states)} состояний)."
                # Показываем меру запутанности
                corr_info = self.analyze_time_correlations()
                if 'error' not in corr_info:
                    print(f"Мера запутанности: {corr_info['entanglement_measure']:.3f}")

        def on_time_analyze(b):
            with self.output:
                clear_output()
                corr_info = self.analyze_time_correlations()
                if 'error' in corr_info:
                    print(corr_info['error'])
                else:
                    print("=== АНАЛИЗ КОРРЕЛЯЦИЙ ===")
                    print(f"Размерность: {corr_info['dimensions']}")
                    print(f"Число узлов: {corr_info['num_nodes']}")
                    print(f"Мера запутанности: {corr_info['entanglement_measure']:.4f}")
                    print(f"Суммарная корреляция: {corr_info['total_correlation']:.4f}")
                    print(f"Средняя корреляция: {corr_info['avg_correlation']:.4f}")

        def on_time_plot(b):
            with self.output:
                clear_output()
                if not self.time_states:
                    print("Нет состояний. Запустите 'Абсолютное настоящее'.")
                    return
                self.plot_time_state(-1)

        time_btn.on_click(on_time_evolve)
        time_analyze_btn.on_click(on_time_analyze)
        time_plot_btn.on_click(on_time_plot)

        # Добавляем ползунки для времени (если их нет)
        self.time_dims_slider = widgets.IntSlider(value=4, min=3, max=7, step=1, description='Измерений:')
        self.time_steps_slider = widgets.IntSlider(value=30, min=5, max=100, step=5, description='Шагов:')

        # Обновляем ui
        self.ui = widgets.VBox([
            widgets.HBox([self.scan_btn, self.evolve_btn, self.tech_btn, self.report_btn]),
            widgets.HBox([self.time_dims_slider, self.time_steps_slider]),
            widgets.HBox([self.time_btn, self.time_analyze_btn, self.time_plot_btn]),
            self.status,
            self.output
        ])
        return self.ui

