# --- CLASS: SessionAccumulator ---
class SessionAccumulator:
    """
    Универсальный накопитель данных сессии с поддержкой итеративного обновления
    и возможностями глубокого анализа. Эмодзи-код: 🌌⚡🧠✨🤖📈🛠️🔬🌱🚀
    """
    
    def __init__(self, session_name: str = "ВЭФ_Сессия"):
        self.session_name = session_name
        self.created = datetime.now().isoformat()
        self.last_updated = self.created
        self.modules: Dict[str, Dict] = {}
        self.dataframes: Dict[str, pd.DataFrame] = {}
        self.relations = {}
        self.history = []
        
        # Инициализация базовых модулей системы
        self._init_base_modules()
    
    def _init_base_modules(self):
        """Инициализация базовых модулей системы"""
        base_modules = {
            "🌌": {"name": "Космическое мышление", "description": "Масштабные проекты и видение"},
            "⚡": {"name": "Энергетика", "description": "Энергетические системы и решения"},
            "🧠": {"name": "ИИ и аналитика", "description": "Интеллектуальные системы анализа"},
            "✨": {"name": "Инновации", "description": "Креативные и инновационные решения"},
            "🤖": {"name": "Автоматизация", "description": "Роботизация и автоматизация процессов"},
            "📈": {"name": "Экономика", "description": "Экономические показатели и модели"},
            "🛠️": {"name": "Технологии", "description": "Технологические разработки"},
            "🔬": {"name": "Наука", "description": "Научные исследования и разработки"},
            "🌱": {"name": "Устойчивое развитие", "description": "Экология и устойчивое развитие"},
            "🚀": {"name": "Прорывные проекты", "description": "Высокорисковые прорывные проекты"}
        }
        
        for emoji, data in base_modules.items():
            self.add_module(emoji, data)
    
    def add_module(self, emoji: str, data: Dict[str, Any]):
        """Добавление или обновление модуля"""
        self.modules[emoji] = {
            **data,
            "created": datetime.now().isoformat(),
            "last_updated": datetime.now().isoformat()
        }
        self._log_change(f"Добавлен модуль {emoji}: {data.get('name', '')}")
    
    def add_data(self, module_emoji: str, data: Dict[str, Any], 
                 dataframe: Optional[pd.DataFrame] = None):
        """Добавление данных к модулю"""
        if module_emoji not in self.modules:
            raise ValueError(f"Модуль {module_emoji} не существует")
        
        # Обновление данных модуля
        self.modules[module_emoji]["data"] = data
        self.modules[module_emoji]["last_updated"] = datetime.now().isoformat()
        
        # Добавление DataFrame если предоставлен
        if dataframe is not None:
            self.dataframes[module_emoji] = dataframe
            
        self._log_change(f"Обновлены данные модуля {module_emoji}")
    
    def add_relation(self, from_module: str, to_module: str, relation_type: str, weight: float = 1.0):
        """Добавление связи между модулями"""
        self.relations[(from_module, to_module)] = {
            "type": relation_type,
            "weight": weight,
            "created": datetime.now().isoformat()
        }
        self._log_change(f"Добавлена связь {from_module} -> {to_module} ({relation_type})")
    
    def _log_change(self, action: str):
        """Логирование изменений"""
        self.history.append({
            "timestamp": datetime.now().isoformat(),
            "action": action
        })
        self.last_updated = datetime.now().isoformat()
    
    def get_module_stats(self) -> pd.DataFrame:
        """Получение статистики по модулям в виде DataFrame"""
        stats_data = []
        for emoji, data in self.modules.items():
            stats_data.append({
                "emoji": emoji,
                "name": data.get("name", ""),
                "description": data.get("description", ""),
                "last_updated": data.get("last_updated", ""),
                "has_data": "data" in data,
                "has_dataframe": emoji in self.dataframes
            })
        return pd.DataFrame(stats_data)
    
    def get_relations_network(self) -> Dict[str, List]:
        """Получение данных о связях для построения сетевого графа"""
        nodes = [{"id": emoji, "name": data.get("name", "")} 
                for emoji, data in self.modules.items()]
        
        links = []
        for (source, target), rel_data in self.relations.items():
            links.append({
                "source": source,
                "target": target,
                "type": rel_data["type"],
                "weight": rel_data["weight"]
            })
        
        return {"nodes": nodes, "links": links}
    
    def export_to_json(self, filepath: str):
        """Экспорт данных сессии в JSON файл"""
        export_data = {
            "session_name": self.session_name,
            "created": self.created,
            "last_updated": self.last_updated,
            "modules": self.modules,
            "relations": self.relations,
            "history": self.history
        }
        
        with open(filepath, 'w', encoding='utf-8') as f:
            json.dump(export_data, f, ensure_ascii=False, indent=2)
    
    def import_from_json(self, filepath: str):
        """Импорт данных сессии из JSON файла"""
        with open(filepath, 'r', encoding='utf-8') as f:
            import_data = json.load(f)
        
        self.session_name = import_data.get("session_name", self.session_name)
        self.created = import_data.get("created", self.created)
        self.last_updated = import_data.get("last_updated", self.last_updated)
        self.modules = import_data.get("modules", self.modules)
        self.relations = import_data.get("relations", self.relations)
        self.history = import_data.get("history", self.history)
    
    def analyze_correlations(self):
        """Анализ корреляций между модулями (заглушка для расширения)"""
        # Здесь может быть реализован сложный анализ взаимосвязей
        print("Анализ корреляций между модулями...")
        
        # Пример простого анализа
        correlation_data = []
        for (source, target), rel_data in self.relations.items():
            correlation_data.append({
                "source": source,
                "target": target,
                "strength": rel_data["weight"],
                "type": rel_data["type"]
            })
        
        return pd.DataFrame(correlation_data)

# --- CLASS: ClimateMonitor ---
class ClimateMonitor:
    """Модуль учёта погодных влияний и определения зон вылова"""
    
    THERMAL_PREFS = {
        'горбуша': {'min': 10, 'max': 14, 'barrier_temp': 18},
        'кета': {'min': 8, 'max': 13, 'barrier_temp': 17},
        'нерка': {'min': 6, 'max': 12, 'barrier_temp': 16},
        'тунец': {'min': 18, 'max': 26, 'barrier_temp': None}  # теплолюбивый
    }
    
    def __init__(self, hub):
        self.hub = hub
        self.sst_data = {}  # sea surface temperature by zone
        self.barrier_zones = []
    
    def update_sst(self, zone: str, temp: float, date: str):
        """Обновление температуры поверхности моря"""
        self.sst_data[zone] = {'temp': temp, 'date': date}
        self.hub.upd(PS.ECO, {
            f'sst_{zone}': temp,
            f'sst_date_{zone}': date
        }, author='climate_monitor')
    
    def find_barriers(self, species: str) -> list:
        """Поиск термических барьеров для вида"""
        prefs = self.THERMAL_PREFS.get(species, {})
        barrier_temp = prefs.get('barrier_temp')
        if not barrier_temp:
            return []
        barriers = []
        for zone, data in self.sst_data.items():
            if data['temp'] > barrier_temp:
                barriers.append({
                    'zone': zone,
                    'temp': data['temp'],
                    'excess': data['temp'] - barrier_temp,
                    'status': 'БЛОКИРОВКА'
                })
        self.barrier_zones = barriers
        return barriers
    
    def find_optimal_zones(self, species: str) -> list:
        """Определение зон, пригодных для вылова"""
        prefs = self.THERMAL_PREFS.get(species, {})
        optimal = []
        for zone, data in self.sst_data.items():
            if prefs['min'] <= data['temp'] <= prefs['max']:
                optimal.append({'zone': zone, 'temp': data['temp']})
        return optimal
    
    def adapt_quota(self, species: str, base_quota: float) -> float:
        """Адаптивная корректировка квоты с учётом барьеров"""
        barriers = self.find_barriers(species)
        if not barriers:
            return base_quota
        # Коэффициент снижения: чем больше барьеров, тем ниже квота
        penalty = min(0.6, len(barriers) * 0.15)
        return base_quota * (1 - penalty)

