# --- CLASS: PS ---
class PS(Enum):
    INFRA='🚄 Инфраструктура'; FIN='💰 Финансы'; PROD='🏭 Производство'
    LOG='📦 Логистика'; MKT='🛒 Маркетинг'; ECO='🌿 Экология'; INN='💡 Инновации'

# --- CLASS: Upd ---
class Upd:
    ts: str; section: PS; changes: Dict; author: str='system'
    def to_dict(self): return asdict(self)

# --- CLASS: FishHub ---
class FishHub:
    def __init__(self, name='Рыбхоз-Трансформация'):
        self.name=name; self.created=datetime.now().isoformat()
        self.data={s:{} for s in PS}
        self.history=[]; self.kpis={}; self.links={}

    def upd(self, section:PS, updates:Dict, author='system'):
        old=self.data[section]; changes={}
        for k,v in updates.items():
            if old.get(k)!=v:
                changes[k]={'old':old.get(k),'new':v}; old[k]=v
        if changes:
            self.history.append(Upd(datetime.now().isoformat(), section, changes, author))

    def get(self, section:PS): return self.data[section].copy()

    def add_kpi(self, name, val, target=None):
        self.kpis[name]={'cur':val,'tgt':target,'prog':val/target if target else None,'upd':datetime.now().isoformat()}

    def link(self, src:PS, tgt:PS, rel:str):
        key=f"{src.value}->{tgt.value}"
        self.links.setdefault(key,[]).append(rel)

    def hist(self, section:PS):
        return [u for u in self.history if u.section==section]

    def impact(self, section:PS):
        rels=[]; updates=self.hist(section)
        for k,v in self.links.items():
            if section.value in k: rels.extend(v)
        return {'sec':section.value,'upd_cnt':len(updates),'rels':rels,'recent':[u.ts for u in updates[-5:]]}

    def export(self, incl_hist=True):
        out={'meta':{'name':self.name,'created':self.created,'updates':len(self.history),'export':datetime.now().isoformat()},
             'sections':{s.value:self.data[s] for s in PS},'kpis':self.kpis,'links':self.links}
        if incl_hist: out['history']=[u.to_dict() for u in self.history]
        return json.dumps(out, ensure_ascii=False, indent=2, default=str)

    def summary(self):
        return {'name':self.name,'active_sections':sum(1 for s in PS if self.data[s]),'updates':len(self.history),'kpis':len(self.kpis),'links':len(self.links),'last':self.history[-1].ts if self.history else None}

