# --- CLASS: ThermalManagementMixin ---
class ThermalManagementMixin:
    """
    Миксин для MetaphysicalAI, добавляющий управление тепловыми потоками.
    """
    def __init__(self):
        self.session_data["🔥"] = {
            "thermal_materials": [],   # база материалов с их фононными спектрами
            "thermal_devices": [],     # спроектированные устройства (диоды, каналы)
            "simulations": [],         # истории тепловых симуляций
            "ml_models": {}            # модели для оптимизации управления
        }
        self.default_material = {
            "name": "silicon",
            "density": 2330,           # кг/м³
            "specific_heat": 700,      # Дж/(кг·К)
            "thermal_conductivity": 148, # Вт/(м·К) (в реальности зависит от температуры)
            "phonon_mean_free_path": 100e-9, # метры
            "phonon_spectrum": None    # будет заполнено из наших кристаллов
        }

    # ------------------- 1. Моделирование теплопереноса -------------------
    def simulate_heat_flow(self, material_params: Dict, geometry: Dict, heat_source: Dict, time_steps: int = 100) -> Dict:
        """
        Симулирует распространение тепла в материале с учётом фононной структуры.
        Использует уравнение теплопроводности с микроструктурными поправками.
        """
        # Извлекаем параметры
        k = material_params.get('thermal_conductivity', 148)
        rho = material_params.get('density', 2330)
        cp = material_params.get('specific_heat', 700)
        # Размеры сетки
        nx = geometry.get('nx', 50)
        ny = geometry.get('ny', 50)
        Lx = geometry.get('Lx', 1e-3)  # метры
        Ly = geometry.get('Ly', 1e-3)
        dx = Lx / nx
        dy = Ly / ny
        # Время
        dt = 0.01 * min(dx, dy)**2 / (k / (rho * cp))  # устойчивость
        # Инициализация поля температуры
        T = np.ones((nx, ny)) * 300  # K (комнатная)
        # Источник тепла
        source_x = int(heat_source.get('x', 0.5) * nx)
        source_y = int(heat_source.get('y', 0.5) * ny)
        source_power = heat_source.get('power', 100)  # Вт
        # Массив для сохранения истории
        history = []
        # Основной цикл (явная схема)
        for t in range(time_steps):
            T_new = T.copy()
            # Добавляем источник
            T_new[source_x, source_y] += source_power * dt / (rho * cp * dx * dy)
            # Диффузия
            for i in range(1, nx-1):
                for j in range(1, ny-1):
                    T_new[i,j] = T[i,j] + k * dt / (rho * cp) * (
                        (T[i+1,j] - 2*T[i,j] + T[i-1,j]) / dx**2 +
                        (T[i,j+1] - 2*T[i,j] + T[i,j-1]) / dy**2
                    )
            # Граничные условия (изолированные края)
            T_new[0,:] = T_new[1,:]
            T_new[-1,:] = T_new[-2,:]
            T_new[:,0] = T_new[:,1]
            T_new[:,-1] = T_new[:,-2]
            T = T_new
            # Сохраняем каждые 10 шагов
            if t % 10 == 0:
                history.append(T.copy())
        result = {
            'final_temperature': T.tolist(),
            'history': [h.tolist() for h in history],
            'max_temp': np.max(T),
            'mean_temp': np.mean(T),
            'params': material_params,
            'geometry': geometry,
            'source': heat_source
        }
        self.session_data["🔥"]["simulations"].append(result)
        return result

    # ------------------- 2. Проектирование теплового диода -------------------
    def design_thermal_diode(self, forward_params: Dict, backward_params: Dict) -> Dict:
        """
        Создаёт тепловой диод на основе двух материалов с разной теплопроводностью.
        В прямом направлении тепло проходит хорошо, в обратном — плохо.
        """
        # Используем материалы с анизотропией: разная теплопроводность по направлениям
        # forward_params: параметры для прямого направления
        # backward_params: параметры для обратного
        # В реальности это могут быть фононные кристаллы с разными спектрами
        k_forward = forward_params.get('k', 200)
        k_backward = backward_params.get('k', 10)
        # Коэффициент диодности
        rectification_ratio = k_forward / k_backward
        diode = {
            'type': 'thermal_diode',
            'k_forward': k_forward,
            'k_backward': k_backward,
            'rectification_ratio': rectification_ratio,
            'forward_material': forward_params,
            'backward_material': backward_params,
            'efficiency': 1 - 1/rectification_ratio if rectification_ratio > 1 else 0
        }
        self.session_data["🔥"]["thermal_devices"].append(diode)
        return diode

    # ------------------- 3. Активное управление теплом -------------------
    def active_heat_management(self, device: Dict, target_temp: float, current_temp: float, control_signal: float = 0) -> Dict:
        """
        Управляет тепловым потоком через устройство, изменяя его эффективную теплопроводность
        с помощью внешнего поля (электрического, механического напряжения).
        control_signal: от -1 до 1 (отрицательное — уменьшать проводимость, положительное — увеличивать)
        """
        base_k = device.get('k_forward', 100)
        # Регулируем проводимость в зависимости от сигнала
        # Например, используем эффект фононного резонанса
        modulation = 1 + control_signal * 0.5  # от 0.5 до 1.5
        effective_k = base_k * modulation
        # Оцениваем изменение температуры
        delta_T = (current_temp - target_temp) * (1 - effective_k / (base_k * 1.5))
        result = {
            'effective_k': effective_k,
            'delta_T': delta_T,
            'control_signal': control_signal,
            'target_temp': target_temp,
            'current_temp': current_temp
        }
        return result

    # ------------------- 4. Интеграция с квантовым процессором -------------------
    def cool_quantum_processor(self, processor: Dict, target_temp: float = 0.01) -> Dict:
        """
        Система охлаждения квантового процессора на основе фононного управления.
        Использует тепловые диоды и активное управление для отвода тепла.
        """
        # Извлекаем тепловые характеристики процессора
        num_qubits = processor.get('num_qubits', 4)
        # Генерируем тепловую модель процессора (распределение источников тепла)
        heat_map = np.random.uniform(0.1, 0.5, (num_qubits, num_qubits))  # условно
        # Проектируем тепловой канал для отвода тепла
        diode = self.design_thermal_diode(
            {'k': 150, 'name': 'forward_material'},
            {'k': 10, 'name': 'backward_material'}
        )
        # Симулируем охлаждение
        initial_temp = 1.0  # Кельвин (для квантового процессора)
        current_temp = initial_temp
        cooling_power = 0.01  # Вт (условно)
        time_steps = 100
        temp_history = []
        for step in range(time_steps):
            # Активное управление: увеличиваем эффективную проводимость для отвода тепла
            control = -1.0  # максимальное увеличение проводимости
            management = self.active_heat_management(diode, target_temp, current_temp, control)
            # Уменьшение температуры
            current_temp -= management['delta_T'] * 0.1 + cooling_power * 0.01
            current_temp = max(current_temp, target_temp)
            temp_history.append(current_temp)
        result = {
            'initial_temp': initial_temp,
            'final_temp': current_temp,
            'temp_history': temp_history,
            'diode': diode,
            'cooling_power': cooling_power,
            'target_temp': target_temp,
            'processor_info': processor
        }
        self.session_data["🔥"]["thermal_devices"].append(result)
        return result

    # ------------------- 5. ML-оптимизация управления теплом -------------------
    def train_thermal_ml_model(self, num_samples: int = 200) -> Dict:
        """
        Обучает модель для предсказания оптимального управляющего сигнала
        на основе текущей температуры и целевой.
        """
        X = []  # признаки: current_temp, target_temp, device_params
        y = []  # целевая: control_signal
        for _ in range(num_samples):
            current = np.random.uniform(0.01, 1.0)
            target = np.random.uniform(0.01, 0.5)
            # Симуляция отклика
            # Эвристика: требуемый сигнал пропорционален разности температур
            signal = (current - target) / (current + target) * 2
            signal = np.clip(signal, -1, 1)
            X.append([current, target])
            y.append(signal)
        X = np.array(X)
        y = np.array(y)
        model = RandomForestRegressor(n_estimators=50, random_state=42)
        model.fit(X, y)
        self.session_data["🔥"]["ml_models"]["thermal_control"] = model
        return {'model': model, 'accuracy': model.score(X, y)}

    # ------------------- 6. Визуализация тепловых полей -------------------
    def plot_thermal_field(self, sim_result: Dict):
        """
        Визуализирует распределение температуры.
        """
        T = np.array(sim_result['final_temperature'])
        plt.figure(figsize=(8,6))
        plt.imshow(T, cmap='hot', origin='lower', aspect='auto')
        plt.colorbar(label='Температура, K')
        plt.title('Тепловое поле')
        plt.show()

# --- CLASS: Session ---
class Session(BaseModel):
    model_config = ConfigDict(extra="allow", str_strip_whitespace=True)
    id: str = Field(..., pattern=r"^session_\d{4}_\d{2}_\d{2}_\d{3}$")
    # Ограничиваем дату разумными рамками
    date: date = Field(..., ge=date(1900, 1, 1), le=date(2100, 12, 31))
    platform: Literal["DeepSeek", "ChatGPT", "Claude", "Local"]
    title: str = Field(..., max_length=300)
    summary: str = Field(..., max_length=5000)
    key_ideas: List[str] = []
    artifacts: List[Artifact] = []
    decisions: List[Decision] = []
    open_questions: List[str] = []
    emotions: List[Literal["calm", "pride", "fatigue", "insight", "anxiety", "drive", "inspiration"]] = []
    phrases: List[str] = []
    tags: List[str] = []

    @model_validator(mode="after")
    def scan_all_fields_fz117(self):
        for path, text in walk_strings(self.model_dump()):
            try:
                check_fz117(text)
            except ValueError as e:
                raise ValueError(f"Ошибка в {path}: {e}")
        return self

    @model_validator(mode="after")
    def id_matches_date(self):
        expected_prefix = f"session_{self.date:%Y_%m_%d}_"
        if not self.id.startswith(expected_prefix):
            raise ValueError(f"ID {self.id!r} не соответствует дате {self.date}")
        return self

    # Вернули защиту от дублей
    @field_validator("tags", "emotions", "key_ideas", "phrases", "open_questions")
    @classmethod
    def check_uniqueness(cls, v: List[str]) -> List[str]:
        if len(set(v)) != len(v):
            raise ValueError("Обнаружены дубликаты в списке (tags/ideas/phrases)")
        return v

# --- CLASS: Artifact ---
class Artifact(BaseModel):
    # extra="allow" используется, чтобы артефакты могли накапливать метаданные.
    # Это безопасно, так как walk_strings сканирует их на ФЗ-117.
    model_config = ConfigDict(extra="allow")
    type: Literal["code", "concept", "document", "dataset", "schema"]
    name: str = Field(..., max_length=200)
    preview: str
    path: Optional[str] = None
    zchain_hash: Optional[str] = Field(None, pattern=r"^[a-f0-9]{16,64}$")

# --- CLASS: Decision ---
class Decision(BaseModel):
    # Для решений наоборот: запрещаем лишние поля, чтобы не было скрытых статусов.
    model_config = ConfigDict(extra="forbid")
    decision: str
    status: Literal["applied", "pending", "rejected", "cancelled"] = "pending"
    applied_at: Optional[datetime] = None

    @model_validator(mode="after")
    def check_applied_timestamp(self):
        if self.status == "applied" and self.applied_at is None:
            raise ValueError("status='applied' требует явного applied_at")
        return self
        
    @field_validator("applied_at")
    @classmethod
    def require_timezone(cls, v: Optional[datetime]) -> Optional[datetime]:
        if v is not None and v.tzinfo is None:
            raise ValueError("applied_at должен содержать таймзону (например +00:00)")
        return v

# --- CLASS: ZStrannik ---
class ZStrannik:
    def __init__(self, strict: bool = True):
        self.sessions: Dict[str, Session] = {}
        self.strict = strict

    def add_session(self, session_data: dict) -> Optional[Session]:
        try:
            session = Session(**session_data)
            if session.id in self.sessions:
                raise ValueError(f"Сессия {session.id} уже существует.")
            self.sessions[session.id] = session
            logging.info(f"✅ Сессия {session.id} добавлена.")
            return session
        except ValueError as e:
            if self.strict:
                raise
            logging.warning(f"❌ Отклонено: {e}")
            return None

    def export_json(self, filename="strannik_data.json"):
        data = {
            "schema_version": STRANNIK_SCHEMA_VERSION,
            "sessions": [s.model_dump(mode="json") for k, s in sorted(self.sessions.items())]
        }
        with open(filename, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=4)
        logging.info(f"💾 Данные сохранены в {filename}")

    def import_json(self, filename="strannik_data.json", clear_existing=False) -> int:
        """
        Атомарный импорт сессий из JSON-файла.

        Проверяет версию схемы и тип данных, валидирует все сессии во временном
        буфере, и только при полном успехе применяет изменения к self.sessions.

        Параметры:
            filename       — путь к JSON-файлу экспорта.
            clear_existing — True: заменить всё содержимое; False: слить с текущим.

        Возвращает:
            Количество успешно загруженных сессий.

        Raises:
            ValueError — при несовпадении schema_version, неверном типе данных,
                         дубликате ID внутри файла или коллизии с существующими ID.

        Внимание:
            В отличие от add_session, метод ВСЕГДА бросает исключение при ошибке,
            независимо от self.strict. Это сделано намеренно: файл нельзя
            применять частично (иначе состояние контейнера будет испорчено).
        """
        with open(filename, "r", encoding="utf-8") as f:
            data = json.load(f)
            
        if not isinstance(data, dict):
            raise ValueError(f"Ожидался объект (dict), получен {type(data).__name__}")
            
        version = data.get("schema_version", "unknown")
        if version != STRANNIK_SCHEMA_VERSION:
            raise ValueError(f"Ожидалась схема {STRANNIK_SCHEMA_VERSION}, получена {version!r}")

        sessions_data = data.get("sessions")
        if not isinstance(sessions_data, list):
            raise ValueError(f"Ожидался список сессий, получен {type(sessions_data).__name__}")

        # Шаг 1: буферизация и валидация всех сессий БЕЗ записи в self.sessions
        new_sessions: Dict[str, Session] = {}
        for s_data in sessions_data:
            s = Session(**s_data)
            if s.id in new_sessions:
                raise ValueError(f"Дубликат ID в файле: {s.id}")
            new_sessions[s.id] = s

        # Шаг 2: атомарное применение (только после полной валидации)
        if clear_existing:
            self.sessions = new_sessions
        else:
            collisions = set(new_sessions) & set(self.sessions)
            if collisions:
                raise ValueError(f"ID уже существуют: {sorted(collisions)}")
            self.sessions.update(new_sessions)

        logging.info(f"📂 Импортировано {len(new_sessions)} сессий.")
        return len(new_sessions)

# --- CLASS: HologramStealth ---
class HologramStealth:  
    def __init__(self, object_size=(3,3,3), hologram_size=(10,10,10)):  
        self.object_pos = np.array([0, 0, 0])  # Центр голограммы  
        self.holo_size = hologram_size  
        self.quantum_grid = self._init_quantum_grid()  

    def _init_quantum_grid(self):  
        # Создаём квантовую сетку из 27 кубитов (3x3x3)  
        qc = QuantumCircuit(27)  
        qc.h(range(27))  # Суперпозиция всех позиций  
        simulator = Aer.get_backend('statevector_simulator')  
        result = simulator.run(qc).result()  
        return result.get_statevector()  

    def update_hologram(self, new_object_pos):  
        # Корректируем голограмму через квантовые измерения  
        delta = new_object_pos - self.object_pos  
        probability = np.abs(self.quantum_grid)**2  
        distortion = np.sum(delta**2) / (self.holo_size[0]**2)  
        if distortion < 0.1:  # Порог устойчивости  
            self.object_pos = new_object_pos  
            print("Голограмма адаптирована! Невидимость сохранена.")  
        else:  
            print("⚠️ Объект слишком близко к краю голограммы! Риск обнаружения.")

