# --- CLASS: QuantumHologram ---
class QuantumHologram:  
    def __init__(self, size=10):  
        self.size = size  # Размер голограммы (10x10x10)  
        self.object_pos = np.array([5, 5, 5])  # Центр  
        self.qc = QuantumCircuit(3)  # 3 кубита для 3D-позиции  
        self._init_quantum_states()  

    def _init_quantum_states(self):  
        # Инициализация кубитов в суперпозицию  
        self.qc.h(0)  
        self.qc.h(1)  
        self.qc.h(2)  
        self.qc.cx(0, 1)  
        self.qc.cx(1, 2)  

    def update_position(self, new_pos):  
        # Квантовая коррекция позиции объекта  
        delta = new_pos - self.object_pos  
        theta = np.arctan(np.linalg.norm(delta) / self.size)  
        self.qc.ry(theta, 0)  
        self.qc.rz(theta, 1)  
        self.object_pos = new_pos  

    def render_hologram(self):  
        # Визуализация голограммы  
        simulator = Aer.get_backend('statevector_simulator')  
        result = execute(self.qc, simulator).result()  
        state = result.get_statevector()  
        fig = plot_bloch_multivector(state)  
        plt.title(f"Голограмма: объект в {self.object_pos}")  
        plt.show()

