# --- CLASS: SargaBathUniverse ---
class SargaBathUniverse:
    """Модель Вселенной на основе ванны САРГА 1600×1000×450"""
    
    def __init__(self):
        # Фактические размеры в метрах
        self.length = 1.6      # м
        self.width = 1.0       # м  
        self.height = 0.45     # м
        
        # Крещенские параметры
        self.water_temp = 4.0    # °C (температура закалки)
        self.flow_rate = 0.005   # м³/с (типичный расход)
        
        # Космологические аналоги
        self.scale_factor = self.calculate_scale_factor()
        
    def calculate_scale_factor(self):
        """Вычисление масштабного фактора из геометрии"""
        # Объём ванны ~ объём наблюдаемой Вселенной в планковских единицах
        volume = self.length * self.width * self.height * 0.75  # коэффициент формы
        
        # Масштабный фактор a(t)
        return volume**(1/3)
    
    def bath_profile_equation(self, x):
        """
        Профиль ванны САРГА в сечении
        x - расстояние от крана (0 до 1.6 м)
        """
        # Эллиптический профиль с параметрами кометной орбиты
        a = 0.8  # большая полуось
        e = 0.7  # эксцентриситет (кометные орбиты ~ 0.6-0.9)
        
        # Уравнение эллипса в полярных координатах
        # r = a(1-e²)/(1+e·cosθ)
        theta = np.pi * x / self.length  # преобразование координат
        
        r = a * (1 - e**2) / (1 + e * np.cos(theta))
        
        # Учёт высоты бортов
        z = self.height * np.sqrt(1 - (r/a)**2)
        
        return {
            'radial_distance': r,
            'height': z,
            'curvature': self.calculate_curvature(r, theta),
            'orbit_type': 'cometary' if e > 0.6 else 'planetary'
        }
    
    def calculate_curvature(self, r, theta):
        """Кривизна профиля (аналог кривизны пространства-времени)"""
        # Формула кривизны для эллипса
        a, b = 0.8, 0.5
        curvature = (a*b) / (a**2 * np.sin(theta)**2 + b**2 * np.cos(theta)**2)**(3/2)
        return curvature
    
    def water_wave_dynamics(self, time_points):
        """
        Динамика волн в ванне с учётом её формы
        """
        # Параметры волн
        wave_speed = np.sqrt(9.8 * 0.1)  # скорость для глубины ~0.1м
        wavelengths = []
        amplitudes = []
        
        for t in time_points:
            # Положение вдоль ванны
            x = wave_speed * t
            
            if x < self.length:
                profile = self.bath_profile_equation(x)
                
                # Эффект формы на волны
                width_factor = profile['radial_distance'] / 0.5
                curvature_factor = 1 / (1 + profile['curvature'])
                
                # Длина волны изменяется из-за геометрии
                wavelength = 0.1 * width_factor * curvature_factor
                amplitude = 0.01 / width_factor
                
                wavelengths.append(wavelength)
                amplitudes.append(amplitude)
        
        return {
            'time': time_points[:len(wavelengths)],
            'wavelengths': wavelengths,
            'amplitudes': amplitudes,
            'form_factor': self.form_factor_analysis()
        }
    
    def form_factor_analysis(self):
        """Анализ фактора формы ванны"""
        # Отношение сторон
        aspect_ratio = self.length / self.width  # 1.6
        
        # Эллиптичность
        ellipticity = 1 - (self.width / self.length)  # 0.375
        
        # Объёмный коэффициент
        volume_coeff = (self.length * self.width * self.height) / (1.6*1.0*0.45)
        
        return {
            'aspect_ratio': aspect_ratio,
            'ellipticity': ellipticity,
            'volume_coefficient': volume_coeff,
            'cometary_orbit_similarity': self.compare_with_comet_orbits()
        }
    
    def compare_with_comet_orbits(self):
        """Сравнение с параметрами кометных орбит"""
        # Известные кометы с высоким эксцентриситетом
        comets = {
            'Halley': {'e': 0.967, 'a': 17.8},
            'Hale-Bopp': {'e': 0.995, 'a': 186},
            'Hyakutake': {'e': 0.9998, 'a': 1700}
        }
        
        # Расчёт эквивалентных параметров для ванны
        bath_eccentricity = 0.7  # из профиля
        bath_semi_major = 0.8
        
        comparisons = []
        for name, params in comets.items():
            # Нормированное сравнение
            e_similarity = 1 - abs(bath_eccentricity - params['e'])
            scale_similarity = bath_semi_major / (params['a'] / 1000)  # нормировка
            
            comparisons.append({
                'comet': name,
                'eccentricity_similarity': e_similarity,
                'scale_similarity': scale_similarity,
                'match_percentage': (e_similarity + scale_similarity) / 2 * 100
            })
        
        return comparisons

