# --- CLASS: EpiphanyUniverseModel ---
class EpiphanyUniverseModel:
    """Формальная модель, основанная на крещенском наблюдении"""
    
    def __init__(self):
        # Параметры из вашей теории
        self.ε = 1.12e-46  # квант нуля
        self.Ω = 8.94e45   # квант бесконечности
        self.t_epiphany = 0.0  # момент "крещенского наблюдения"
        
    def bath_geometry_factor(self, x):
        """
        Геометрический фактор формы ванны
        x - положение вдоль ванны (0 - кран, 1 - дальний конец)
        """
        # Эллиптический профиль ванны
        a, b = 1.0, 0.6  # полуоси эллипса
        return np.sqrt(1 - (x**2 / a**2)) * b
    
    def wave_equation_in_bath(self, t, y, k):
        """
        Уравнение волн в эллиптической ванне
        y = [h, dh/dt] - амплитуда и скорость волны
        k - волновое число
        """
        h, dh = y
        
        # Геометрический фактор влияет на скорость волн
        geometric_factor = self.bath_geometry_factor(h)
        
        # "Крещенский фактор" - момент особой синхронизации
        epiphany_factor = np.exp(-(t - self.t_epiphany)**2 / 0.1)
        
        # Модифицированная частота
        omega = k * (1 + 0.5 * geometric_factor) * (1 + 0.1 * epiphany_factor)
        
        return [dh, -omega**2 * h]
    
    def simulate_universe_expansion(self):
        """Симуляция расширения Вселенной по аналогии с ванной"""
        # Начальные условия - "крещенский момент"
        t_span = [0, 10]  # от начала до установления
        y0 = [0.01, 0]    # маленькое начальное возмущение
        
        # Разные масштабы (волновые числа)
        results = {}
        for k in [0.5, 1.0, 2.0, 5.0]:
            sol = solve_ivp(
                lambda t, y: self.wave_equation_in_bath(t, y, k),
                t_span,
                y0,
                dense_output=True
            )
            results[k] = sol
            
        return results

