# --- CLASS: MultiScaleMathematics ---
class MultiScaleMathematics:
    """Математические модели мультимасштабных систем"""
    
    def fractal_dimension_estimation(self, surface_profile):
        """
        Оценка фрактальной размерности поверхности
        surface_profile - массив высот поверхности
        """
        # Метод счётных ящиков (box-counting)
        sizes = [2, 4, 8, 16, 32]  # Размеры ячеек
        counts = []
        
        for size in sizes:
            # Упрощенный подсчет ячеек, покрывающих поверхность
            count = len(surface_profile) / size
            counts.append(count)
        
        # Линейная регрессия в логарифмических координатах
        log_sizes = np.log(sizes)
        log_counts = np.log(counts)
        
        # Фрактальная размерность = наклон
        coeffs = np.polyfit(log_sizes, log_counts, 1)
        fractal_dim = -coeffs[0]  # Отрицательный наклон
        
        return {
            'fractal_dimension': fractal_dim,
            'interpretation': [
                'D = 1: Идеально гладкая линия',
                'D = 2: Идеально гладкая поверхность',
                '1 < D < 2: Фрактальная кривая',
                '2 < D < 3: Фрактальная поверхность'
            ],
            'typical_values': {
                'coastline': 1.2-1.3,
                'mountain_terrain': 2.1-2.3,
                'clouds': 2.3-2.5,
                'quantum_foam': '~2.5 (гипотетически)'
            }
        }
    
    def roughness_spectrum(self):
        """Спектр шероховатости (аналог спектра CMB)"""
        # P(k) ~ k^n — степенной закон для неровностей
        power_laws = {
            'white_noise': 'n = 0 (случайные неровности)',
            'pink_noise': 'n = -1 (фрактальная поверхность)',
            'brownian_noise': 'n = -2 (броуновское движение)',
            'cmb_spectrum': 'n ≈ 1 (первоначальные флуктуации)'
        }
        return power_laws

# --- CLASS: BubbleSpotModel ---
class BubbleSpotModel:
    """Математическая модель бурлящего пятна"""
    
    def spot_diameter(self, h, Q, v):
        """
        h - глубина воды (м)
        Q - расход воды (м³/с)
        v - скорость струи (м/с)
        """
        # Эмпирическая формула на основе наблюдений
        # Диаметр пропорционален корню из кинетической энергии
        kinetic_energy = 0.5 * 1000 * Q * v**2
        
        # Диссипация пропорциональна глубине
        dissipation = 0.1 * h
        
        # Диаметр пятна
        D = 0.3 * np.sqrt(kinetic_energy / dissipation)
        
        return D
    
    def wave_generation(self, D, h, g=9.81):
        """
        Генерация волн от бурлящего пятна
        D - диаметр пятна
        h - глубина
        """
        # Частота пульсаций (Гц)
        f = 1 / (2 * np.pi * np.sqrt(D / (2 * g)))
        
        # Длина волны (м)
        wavelength = np.sqrt(g * h) / f
        
        # Амплитуда (м) - пропорциональна энергии
        amplitude = 0.01 * D / h
        
        return {
            'frequency': f,
            'wavelength': wavelength,
            'amplitude': amplitude
        }

