class IrresistibleIncentivesEngine:
    """Двигатель создания взаимовыгодных 'плюшек'"""
    
    def __init__(self):
        self.incentive_mechanisms = {
            'economic_gravity': self._create_economic_gravity,
            'knowledge_magnets': self._create_knowledge_magnets,
            'stability_premiums': self._create_stability_premiums,
            'future_proofing': self._create_future_proofing
        }
    
    def generate_region_incentives(self, region_data: Dict, rubric_context: Dict) -> List[Dict]:
        """Генерация 'неотразимых' стимулов для региона"""
        
        incentives = []
        
        for mechanism_name, creator in self.incentive_mechanisms.items():
            mechanism_incentives = creator(region_data, rubric_context)
            incentives.extend(mechanism_incentives)
        
        # Фильтрация и ранжирование по привлекательности
        scored_incentives = []
        for incentive in incentives:
            attractiveness = self._calculate_attractiveness_score(incentive)
            incentive['attractiveness_score'] = attractiveness
            scored_incentives.append(incentive)
        
        scored_incentives.sort(key=lambda x: x['attractiveness_score'], reverse=True)
        return scored_incentives[:10]  # Топ-10 самых привлекательных

