# --- CLASS: DataCategory ---
class DataCategory(Enum):
    """Категории данных для классификации"""
    SYSTEM_ARCHITECTURE = "system_architecture"
    ECONOMIC_MODELS = "economic_models"
    ANALYTICS = "analytics"
    SECURITY = "security"
    INTEGRATION = "integration"
    INNOVATION = "innovation"

# --- CLASS: SessionEntity ---
class SessionEntity:
    """Базовая сущность сессионных данных"""
    id: str
    content: Any
    category: DataCategory
    timestamp: datetime
    tags: List[str]
    metadata: Dict[str, Any]
    version: int = 1
    
    def to_dict(self) -> Dict[str, Any]:
        """Преобразование в словарь"""
        return {
            'id': self.id,
            'content': self.content,
            'category': self.category.value,
            'timestamp': self.timestamp.isoformat(),
            'tags': self.tags,
            'metadata': self.metadata,
            'version': self.version
        }

# --- CLASS: SessionDataManager ---
class SessionDataManager:
    """
    🎯 МЕНЕДЖЕР СЕССИОННЫХ ДАННЫХ
    Емкая структура для хранения и анализа данных сессии
    """
    
    def __init__(self, session_id: str = None):
        self.session_id = session_id or f"session_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
        self.entities: Dict[str, SessionEntity] = {}
        self.relationships: Dict[str, List[str]] = {}
        self.analysis_cache = {}
        
        # Индексы для быстрого поиска
        self._category_index: Dict[DataCategory, List[str]] = {category: [] for category in DataCategory}
        self._tag_index: Dict[str, List[str]] = {}
        
    def add_entity(self, 
                   content: Any,
                   category: DataCategory,
                   entity_id: str = None,
                   tags: List[str] = None,
                   metadata: Dict[str, Any] = None) -> str:
        """
        Добавление новой сущности в сессию
        
        Args:
            content: Данные сущности
            category: Категория данных
            entity_id: Уникальный ID (автогенерация если None)
            tags: Список тегов для классификации
            metadata: Дополнительные метаданные
            
        Returns:
            ID созданной сущности
        """
        entity_id = entity_id or f"ent_{len(self.entities) + 1:06d}"
        
        entity = SessionEntity(
            id=entity_id,
            content=content,
            category=category,
            timestamp=datetime.now(),
            tags=tags or [],
            metadata=metadata or {}
        )
        
        # Сохранение сущности
        self.entities[entity_id] = entity
        
        # Обновление индексов
        self._category_index[category].append(entity_id)
        for tag in entity.tags:
            if tag not in self._tag_index:
                self._tag_index[tag] = []
            self._tag_index[tag].append(entity_id)
            
        return entity_id
    
    def create_relationship(self, source_id: str, target_id: str, relationship_type: str = "related_to"):
        """
        Создание связи между сущностями
        
        Args:
            source_id: ID исходной сущности
            target_id: ID целевой сущности  
            relationship_type: Тип связи
        """
        if source_id not in self.relationships:
            self.relationships[source_id] = []
        
        self.relationships[source_id].append({
            'target': target_id,
            'type': relationship_type,
            'created': datetime.now().isoformat()
        })
    
    def get_entities_by_category(self, category: DataCategory) -> List[SessionEntity]:
        """Получение сущностей по категории"""
        return [self.entities[eid] for eid in self._category_index.get(category, [])]
    
    def get_entities_by_tag(self, tag: str) -> List[SessionEntity]:
        """Получение сущностей по тегу"""
        return [self.entities[eid] for eid in self._tag_index.get(tag, [])]
    
    def search_entities(self, 
                       query: str = None,
                       category: DataCategory = None,
                       tags: List[str] = None) -> List[SessionEntity]:
        """
        Расширенный поиск сущностей
        
        Args:
            query: Текстовый запрос для поиска в content
            category: Фильтр по категории
            tags: Фильтр по тегам
            
        Returns:
            Список найденных сущностей
        """
        results = []
        
        for entity in self.entities.values():
            # Фильтр по категории
            if category and entity.category != category:
                continue
                
            # Фильтр по тегам
            if tags and not any(tag in entity.tags for tag in tags):
                continue
                
            # Текстовый поиск
            if query:
                content_str = str(entity.content).lower()
                if query.lower() not in content_str:
                    continue
                    
            results.append(entity)
            
        return results
    
    def update_entity(self, entity_id: str, **updates) -> bool:
        """
        Обновление сущности
        
        Args:
            entity_id: ID сущности для обновления
            **updates: Поля для обновления
            
        Returns:
            True если обновление успешно
        """
        if entity_id not in self.entities:
            return False
            
        entity = self.entities[entity_id]
        
        for key, value in updates.items():
            if hasattr(entity, key):
                setattr(entity, key, value)
                
        entity.version += 1
        return True
    
    def export_to_json(self, filename: str, include_relationships: bool = True) -> None:
        """
        Экспорт данных в JSON файл
        
        Args:
            filename: Имя файла для экспорта
            include_relationships: Включать связи в экспорт
        """
        export_data = {
            'session_id': self.session_id,
            'export_timestamp': datetime.now().isoformat(),
            'entities': {eid: entity.to_dict() for eid, entity in self.entities.items()},
            'statistics': self.get_session_statistics()
        }
        
        if include_relationships:
            export_data['relationships'] = self.relationships
            
        with open(filename, 'w', encoding='utf-8') as f:
            json.dump(export_data, f, ensure_ascii=False, indent=2)
    
    def export_to_dataframe(self) -> pd.DataFrame:
        """Экспорт данных в pandas DataFrame для анализа"""
        data = []
        for entity in self.entities.values():
            row = {
                'id': entity.id,
                'category': entity.category.value,
                'timestamp': entity.timestamp,
                'tags': ', '.join(entity.tags),
                'content_length': len(str(entity.content)),
                'version': entity.version
            }
            row.update(entity.metadata)
            data.append(row)
            
        return pd.DataFrame(data)
    
    def get_session_statistics(self) -> Dict[str, Any]:
        """Статистика сессии"""
        total_entities = len(self.entities)
        category_stats = {cat.value: len(entities) for cat, entities in self._category_index.items()}
        tag_stats = {tag: len(entities) for tag, entities in self._tag_index.items()}
        
        return {
            'total_entities': total_entities,
            'categories': category_stats,
            'tags': tag_stats,
            'relationships': len(self.relationships),
            'session_duration_hours': self._calculate_session_duration()
        }
    
    def _calculate_session_duration(self) -> float:
        """Расчет продолжительности сессии в часах"""
        if not self.entities:
            return 0.0
            
        timestamps = [entity.timestamp for entity in self.entities.values()]
        start_time = min(timestamps)
        end_time = max(timestamps)
        
        return (end_time - start_time).total_seconds() / 3600

# --- CLASS: InformationGravityModel ---
class InformationGravityModel:
    """
    Концептуальная модель анализа информационных потоков на основе метафоры гравитации.
    Теоретический инструмент для понимания структуры коммуникаций.
    """
    
    def __init__(self):
        self.nodes = {}  # Узлы (источники/приемники информации)
        self.edges = {}  # Связи между узлами
        self.gravity_constants = {
            'hierarchy': 1.0,
            'proximity': 1.5,
            'frequency': 2.0,
            'security': -0.5
        }
    
    def add_node(self, node_id, node_type, attributes):
        """Добавление узла в модель"""
        self.nodes[node_id] = {
            'type': node_type,
            'attributes': attributes,
            'mass': self._calculate_node_mass(attributes)
        }
    
    def _calculate_node_mass(self, attributes):
        """Расчет 'массы' узла на основе его характеристик"""
        mass = 0
        # Теоретические факторы влияния:
        if attributes.get('hierarchy_level'):
            mass += attributes['hierarchy_level'] * 10
        if attributes.get('connected_nodes'):
            mass += len(attributes['connected_nodes']) * 5
        if attributes.get('communication_frequency'):
            mass += attributes['communication_frequency'] * 2
        return mass
    
    def calculate_gravity_force(self, node1_id, node2_id):
        """Расчет силы гравитационного притяжения между узлами"""
        if node1_id not in self.nodes or node2_id not in self.nodes:
            return 0
        
        node1 = self.nodes[node1_id]
        node2 = self.nodes[node2_id]
        
        # Теоретический расчет на основе гипотетических параметров
        force = (node1['mass'] * node2['mass']) / self._calculate_distance(node1, node2)**2
        
        # Корректировки на основе типов связи
        force *= self._calculate_connection_modifier(node1, node2)
        
        return force
    
    def _calculate_distance(self, node1, node2):
        """Расчет 'расстояния' между узлами (метафорическое)"""
        distance = 1.0
        
        # Факторы, увеличивающие 'расстояние':
        if node1['type'] != node2['type']:
            distance *= 1.2
        if node1['attributes'].get('security_level') != node2['attributes'].get('security_level'):
            distance *= 1.5
            
        return max(distance, 0.1)
    
    def _calculate_connection_modifier(self, node1, node2):
        """Модификатор связи на основе характеристик"""
        modifier = 1.0
        
        # Совместные атрибуты усиливают связь
        common_attributes = set(node1['attributes'].keys()) & set(node2['attributes'].keys())
        modifier += len(common_attributes) * 0.1
        
        return modifier
    
    def find_central_nodes(self, threshold=0.7):
        """Поиск центральных узлов с наибольшим гравитационным влиянием"""
        centrality_scores = {}
        
        for node_id in self.nodes:
            total_force = 0
            for other_id in self.nodes:
                if node_id != other_id:
                    total_force += self.calculate_gravity_force(node_id, other_id)
            
            centrality_scores[node_id] = total_force
        
        # Нормализация оценок
        max_score = max(centrality_scores.values()) if centrality_scores else 1
        normalized_scores = {nid: score/max_score for nid, score in centrality_scores.items()}
        
        # Возвращаем узлы с оценкой выше порога
        return {nid: score for nid, score in normalized_scores.items() if score >= threshold}

# --- CLASS: SecurityManager ---
class SecurityManager:
    """Менеджер безопасности для обработки чувствительных данных"""
    
    def __init__(self):
        self.encryption_key = os.getenv('ENCRYPTION_KEY', Fernet.generate_key())
        self.cipher_suite = Fernet(self.encryption_key)
        self.jwt_secret = os.getenv('JWT_SECRET', 'default-secret-change-in-production')
    
    def encrypt_sensitive_data(self, data: Dict) -> str:
        """Шифрование чувствительных данных"""
        json_data = json.dumps(data)
        encrypted_data = self.cipher_suite.encrypt(json_data.encode())
        return encrypted_data.decode()
    
    def decrypt_sensitive_data(self, encrypted_data: str) -> Dict:
        """Дешифрование данных"""
        decrypted_data = self.cipher_suite.decrypt(encrypted_data.encode())
        return json.loads(decrypted_data.decode())
    
    def create_api_token(self, payload: Dict) -> str:
        """Создание JWT токена для API"""
        return jwt.encode(payload, self.jwt_secret, algorithm='HS256')
    
    def verify_api_token(self, token: str) -> Optional[Dict]:
        """Верификация JWT токена"""
        try:
            return jwt.decode(token, self.jwt_secret, algorithms=['HS256'])
        except jwt.InvalidTokenError:
            return None

# --- CLASS: APIClientWithRetry ---
class APIClientWithRetry:
    """Продвинутый HTTP клиент с повторными попытками и кэшированием"""
    
    def __init__(self):
        self.timeout = ClientTimeout(total=30)
        self.connector = TCPConnector(ssl=False, limit=100)
        self.security = SecurityManager()
        
    @backoff.on_exception(
        backoff.expo,
        (aiohttp.ClientError, asyncio.TimeoutError),
        max_tries=3,
        max_time=60
    )
    async def make_secure_request(self, method: str, url: str, 
                                headers: Dict = None, data: Dict = None) -> Dict:
        """Выполнение запроса с повторными попытками"""
        async with aiohttp.ClientSession(
            timeout=self.timeout,
            connector=self.connector
        ) as session:
            
            try:
                async with session.request(method, url, headers=headers, json=data) as response:
                    if response.status == 200:
                        return await response.json()
                    elif response.status == 429:  # Rate limiting
                        await asyncio.sleep(1)
                        raise aiohttp.ClientError("Rate limit exceeded")
                    else:
                        response.raise_for_status()
            except Exception as e:
                print(f"Request failed: {e}")
                raise

# --- CLASS: CacheManager ---
class CacheManager:
    """Продвинутая система кэширования с TTL"""
    
    def __init__(self):
        self.cache = {}
        self.default_ttl = 300  # 5 минут
        
    def get(self, key: str) -> Optional[Any]:
        """Получение данных из кэша"""
        if key in self.cache:
            data, expiry = self.cache[key]
            if datetime.now() < expiry:
                return data
            else:
                del self.cache[key]
        return None
    
    def set(self, key: str, data: Any, ttl: int = None):
        """Сохранение данных в кэш"""
        expiry = datetime.now() + timedelta(seconds=ttl or self.default_ttl)
        self.cache[key] = (data, expiry)
    
    def clear_expired(self):
        """Очистка просроченных записей"""
        current_time = datetime.now()
        expired_keys = [
            key for key, (_, expiry) in self.cache.items()
            if current_time >= expiry
        ]
        for key in expired_keys:
            del self.cache[key]

