# --- CLASS: DataSourceConfig ---
class DataSourceConfig:
    name: str
    api_endpoint: str
    api_key: str = ""
    rate_limit: int = 1000
    enabled: bool = True

# --- CLASS: DataCollector ---
class DataCollector:
    def __init__(self):
        self.sources = {
            'telegram': DataSourceConfig(
                name="Telegram Channels",
                api_endpoint="https://api.telegram.org",
                rate_limit=30
            ),
            'twitter': DataSourceConfig(
                name="X/Twitter API",
                api_endpoint="https://api.twitter.com/2",
                rate_limit=300
            ),
            'news_api': DataSourceConfig(
                name="News API", 
                api_endpoint="https://newsapi.org/v2",
                rate_limit=100
            ),
            'satellite': DataSourceConfig(
                name="Satellite Imagery",
                api_endpoint="https://api.planet.com",
                rate_limit=50
            ),
            'economic': DataSourceConfig(
                name="World Bank API",
                api_endpoint="https://api.worldbank.org/v2",
                rate_limit=500
            )
        }
        
        self.cache = {}
        self.session = None

    async def initialize(self):
        """Инициализация асинхронной сессии"""
        self.session = aiohttp.ClientSession()

    async def collect_region_data(self, region: str, timeframe_days: int = 7) -> Dict[str, Any]:
        """Сбор данных по региону из всех источников"""
        tasks = []
        
        # Параллельный сбор данных
        for source_name, config in self.sources.items():
            if config.enabled:
                task = self._fetch_source_data(source_name, region, timeframe_days)
                tasks.append(task)
        
        results = await asyncio.gather(*tasks, return_exceptions=True)
        
        # Агрегация результатов
        aggregated_data = {
            'region': region,
            'timestamp': datetime.now(),
            'timeframe_days': timeframe_days,
            'sources': {}
        }
        
        for source_name, result in zip(self.sources.keys(), results):
            if not isinstance(result, Exception):
                aggregated_data['sources'][source_name] = result
        
        return aggregated_data

    async def _fetch_source_data(self, source: str, region: str, timeframe: int) -> Dict[str, Any]:
        """Запрос данных из конкретного источника"""
        try:
            if source == 'telegram':
                return await self._fetch_telegram_data(region, timeframe)
            elif source == 'twitter':
                return await self._fetch_twitter_data(region, timeframe)
            elif source == 'news_api':
                return await self._fetch_news_data(region, timeframe)
            elif source == 'economic':
                return await self._fetch_economic_data(region, timeframe)
            elif source == 'satellite':
                return await self._fetch_satellite_data(region, timeframe)
        except Exception as e:
            print(f"Ошибка сбора данных из {source}: {e}")
            return {}

    async def _fetch_telegram_data(self, region: str, timeframe: int) -> Dict[str, Any]:
        """Сбор данных из Telegram каналов"""
        # Имитация API запроса - в реальности будет интеграция с Telegram API
        channels = self._get_region_channels(region)
        
        mock_data = {
            'message_count': 1500,
            'active_channels': len(channels),
            'sentiment_distribution': {'positive': 0.4, 'negative': 0.3, 'neutral': 0.3},
            'top_topics': ['политика', 'экономика', 'социальные вопросы'],
            'engagement_metrics': {
                'avg_views': 2500,
                'avg_reactions': 150,
                'virality_index': 0.67
            }
        }
        
        await asyncio.sleep(0.1)  # Имитация задержки сети
        return mock_data

    async def _fetch_twitter_data(self, region: str, timeframe: int) -> Dict[str, Any]:
        """Сбор данных из Twitter/X"""
        # Имитация данных Twitter API v2
        mock_data = {
            'tweet_volume': 50000,
            'unique_authors': 12000,
            'hashtag_trends': [
                {'tag': f'#{region}', 'volume': 15000},
                {'tag': '#новости', 'volume': 8000},
                {'tag': '#политика', 'volume': 6000}
            ],
            'sentiment_analysis': {
                'compound_score': -0.12,  # Негативный тренд
                'subjectivity': 0.78
            },
            'influence_network': {
                'centralization_index': 0.45,
                'key_influencers_count': 23
            }
        }
        
        await asyncio.sleep(0.2)
        return mock_data

    def _get_region_channels(self, region: str) -> List[str]:
        """Получение списка каналов для региона"""
        region_channels = {
            'middle_east': ['@middleeast_news', '@arab_news', '@gulf_events'],
            'eastern_europe': ['@easteurope_news', '@baltic_news', '@ukraine_events'],
            'global': ['@world_news', '@breaking_news', '@reuters']
        }
        return region_channels.get(region, region_channels['global'])

