# --- CLASS: RiskPredictor ---
class RiskPredictor:
    def __init__(self):
        self.models = {}
        self.scalers = {}
        self.feature_columns = [
            'social_cohesion', 'economic_stability', 'information_entropy',
            'polarization_index', 'trust_metrics', 'conflict_indicators'
        ]
        
        self._initialize_models()
    
    def _initialize_models(self):
        """Инициализация ML моделей"""
        # Модель классификации уровня угрозы
        self.models['threat_classifier'] = RandomForestClassifier(
            n_estimators=100,
            max_depth=10,
            random_state=42
        )
        
        # Модель обнаружения аномалий
        self.models['anomaly_detector'] = IsolationForest(
            contamination=0.1,
            random_state=42
        )
        
        # Модель кластеризации регионов
        self.models['region_clusterer'] = DBSCAN(eps=0.5, min_samples=2)
        
        # Скалер для нормализации признаков
        self.scalers['standard'] = StandardScaler()
    
    def train_models(self, historical_data: pd.DataFrame):
        """Обучение моделей на исторических данных"""
        try:
            # Подготовка признаков
            features = historical_data[self.feature_columns]
            labels = historical_data['threat_level']
            
            # Нормализация данных
            scaled_features = self.scalers['standard'].fit_transform(features)
            
            # Обучение классификатора
            self.models['threat_classifier'].fit(scaled_features, labels)
            
            # Обучение детектора аномалий
            self.models['anomaly_detector'].fit(scaled_features)
            
            print("✅ Модели успешно обучены")
            
        except Exception as e:
            print(f"❌ Ошибка обучения моделей: {e}")
    
    def predict_risk(self, current_metrics: Dict[str, float]) -> Dict[str, Any]:
        """Прогнозирование рисков на основе текущих метрик"""
        try:
            # Преобразование в вектор признаков
            feature_vector = np.array([
                current_metrics.get('social_cohesion', 0.5),
                current_metrics.get('economic_stability', 0.5), 
                current_metrics.get('information_entropy', 0.5),
                current_metrics.get('polarization_index', 0.5),
                current_metrics.get('trust_metrics', 0.5),
                current_metrics.get('conflict_indicators', 0.5)
            ]).reshape(1, -1)
            
            # Нормализация
            scaled_features = self.scalers['standard'].transform(feature_vector)
            
            # Предсказание уровня угрозы
            threat_level = self.models['threat_classifier'].predict(scaled_features)[0]
            threat_probability = self.models['threat_classifier'].predict_proba(scaled_features)[0]
            
            # Обнаружение аномалий
            is_anomaly = self.models['anomaly_detector'].predict(scaled_features)[0] == -1
            anomaly_score = self.models['anomaly_detector'].decision_function(scaled_features)[0]
            
            return {
                'threat_level': threat_level,
                'threat_probability': max(threat_probability),
                'is_anomaly': bool(is_anomaly),
                'anomaly_score': float(anomaly_score),
                'confidence': 0.85,  # Можно вычислять на основе качества модели
                'recommended_actions': self._suggest_actions(threat_level, is_anomaly)
            }
            
        except Exception as e:
            print(f"❌ Ошибка предсказания: {e}")
            return {
                'threat_level': 'UNKNOWN',
                'threat_probability': 0.0,
                'is_anomaly': False,
                'anomaly_score': 0.0,
                'confidence': 0.0,
                'recommended_actions': ['Требуется дополнительный анализ']
            }
    
    def _suggest_actions(self, threat_level: str, is_anomaly: bool) -> List[str]:
        """Генерация рекомендаций на основе уровня угрозы"""
        base_actions = [
            "Мониторинг ситуации в реальном времени",
            "Подготовка информационных материалов"
        ]
        
        if threat_level in ['HIGH', 'CRITICAL']:
            base_actions.extend([
                "Активация протокола экстренного реагирования",
                "Координация с местными властями",
                "Подготовка гуманитарных коридоров"
            ])
        
        if is_anomaly:
            base_actions.extend([
                "Углубленный анализ аномальных паттернов",
                "Проверка данных на манипуляции"
            ])
        
        return base_actions

# --- CLASS: SyntheticDataGenerator ---
class SyntheticDataGenerator:
    def __init__(self):
        self.rng = np.random.default_rng(42)
    
    def generate_historical_data(self, n_samples: int = 1000) -> pd.DataFrame:
        """Генерация исторических данных для обучения"""
        data = []
        
        for i in range(n_samples):
            # Генерация реалистичных метрик
            social_cohesion = self.rng.normal(0.6, 0.2)
            economic_stability = self.rng.normal(0.5, 0.25)
            information_entropy = self.rng.normal(0.4, 0.15)
            
            # Определение уровня угрозы на основе комбинации факторов
            threat_score = (
                (1 - social_cohesion) * 0.4 +
                (1 - economic_stability) * 0.3 + 
                information_entropy * 0.3
            )
            
            if threat_score < 0.3:
                threat_level = 'LOW'
            elif threat_score < 0.6:
                threat_level = 'MEDIUM' 
            elif threat_score < 0.8:
                threat_level = 'HIGH'
            else:
                threat_level = 'CRITICAL'
            
            data.append({
                'social_cohesion': max(0, min(1, social_cohesion)),
                'economic_stability': max(0, min(1, economic_stability)),
                'information_entropy': max(0, min(1, information_entropy)),
                'polarization_index': self.rng.normal(0.5, 0.2),
                'trust_metrics': self.rng.normal(0.6, 0.15),
                'conflict_indicators': self.rng.normal(0.3, 0.1),
                'threat_level': threat_level
            })
        
        return pd.DataFrame(data)

# --- CLASS: AdvancedDataCollector ---
class AdvancedDataCollector:
    """Продвинутый сборщик данных с реальными API интеграциями"""
    
    def __init__(self):
        self.api_integrations = RealAPIIntegrations()
        self.security = SecurityManager()
        self.rate_limiter = RateLimiter()
        
    async def collect_comprehensive_region_data(self, region: str, 
                                              timeframe_days: int = 7) -> Dict[str, Any]:
        """Комплексный сбор данных по региону"""
        print(f"🔍 Сбор данных для региона: {region}")
        
        # Параллельный сбор данных из всех источников
        tasks = {
            'telegram_data': self._collect_telegram_data(region),
            'twitter_data': self._collect_twitter_data(region),
            'news_data': self._collect_news_data(region),
            'economic_data': self._collect_economic_data(region),
            'satellite_data': self._collect_satellite_data(region)
        }
        
        # Выполнение всех задач параллельно
        results = {}
        for task_name, task in tasks.items():
            try:
                results[task_name] = await task
            except Exception as e:
                print(f"❌ Ошибка в {task_name}: {e}")
                results[task_name] = {'error': str(e)}
        
        # Агрегация и обогащение данных
        aggregated_data = await self._aggregate_and_enrich_data(region, results)
        
        # Шифрование чувствительных данных
        encrypted_data = self.security.encrypt_sensitive_data({
            'raw_metrics': aggregated_data.get('raw_metrics', {}),
            'source_data': aggregated_data.get('source_data', {})
        })
        
        aggregated_data['encrypted_raw_data'] = encrypted_data
        return aggregated_data
    
    async def _collect_telegram_data(self, region: str) -> Dict:
        """Сбор данных из Telegram"""
        await self.rate_limiter.wait_for_capacity('telegram', 1)
        
        channels = self._get_region_telegram_channels(region)
        channel_data = []
        
        for channel in channels[:5]:  # Ограничение для демо
            data = await self.api_integrations.get_telegram_channel_stats(channel)
            channel_data.append(data)
        
        return {
            'channels_analyzed': len(channel_data),
            'total_members': sum(c['channel_info']['members_count'] for c in channel_data),
            'engagement_analysis': self._analyze_telegram_engagement(channel_data),
            'channel_data': channel_data
        }
    
    async def _collect_twitter_data(self, region: str) -> Dict:
        """Сбор данных из Twitter"""
        await self.rate_limiter.wait_for_capacity('twitter', 1)
        
        trends = await self.api_integrations.get_twitter_trends(region)
        
        return {
            'trending_topics': trends['trends'],
            'analysis': self._analyze_twitter_trends(trends['trends']),
            'regional_activity': self._estimate_regional_activity(region)
        }
    
    async def _collect_news_data(self, region: str) -> Dict:
        """Сбор новостных данных"""
        await self.rate_limiter.wait_for_capacity('newsapi', 1)
        
        articles = await self.api_integrations.get_news_articles(region)
        
        return {
            'article_count': articles['totalResults'],
            'sentiment_breakdown': self._analyze_news_sentiment(articles['articles']),
            'key_themes': self._extract_news_themes(articles['articles']),
            'articles_sample': articles['articles'][:3]  # Первые 3 статьи для примера
        }
    
    async def _collect_economic_data(self, region: str) -> Dict:
        """Сбор экономических данных"""
        country_code = self._region_to_country_code(region)
        economic_data = await self.api_integrations.get_economic_indicators(country_code)
        
        return {
            'economic_health': self._calculate_economic_health(economic_data['indicators']),
            'stability_index': self._calculate_economic_stability(economic_data['indicators']),
            'raw_indicators': economic_data['indicators']
        }
    
    async def _collect_satellite_data(self, region: str) -> Dict:
        """Сбор спутниковых данных (мок)"""
        # В реальности интеграция с Planet.com или NASA APIs
        return {
            'night_light_index': self._random_float(0.1, 1.0),
            'urban_development_score': self._random_float(0.3, 0.9),
            'agricultural_activity': self._random_float(0.2, 0.8),
            'environmental_changes': self._random_float(-0.1, 0.1)
        }
    
    async def _aggregate_and_enrich_data(self, region: str, source_data: Dict) -> Dict:
        """Агрегация и обогащение данных из всех источников"""
        
        # Расчет интегральных метрик
        composite_metrics = {
            'social_cohesion': self._calculate_social_cohesion(source_data),
            'information_entropy': self._calculate_information_entropy(source_data),
            'economic_stability': source_data.get('economic_data', {}).get('stability_index', 0.5),
            'political_tension': self._calculate_political_tension(source_data),
            'human_development_index': self._estimate_hdi(region),
            'conflict_probability': self._estimate_conflict_probability(source_data)
        }
        
        return {
            'region': region,
            'timestamp': datetime.now().isoformat(),
            'composite_metrics': composite_metrics,
            'source_data': source_data,
            'data_quality_score': self._calculate_data_quality(source_data),
            'collection_metadata': {
                'sources_used': len([v for v in source_data.values() if not v.get('error')]),
                'total_data_points': self._count_data_points(source_data),
                'processing_time': 'real_time'  # В реальности было бы вычислено
            }
        }
    
    def _calculate_social_cohesion(self, data: Dict) -> float:
        """Расчет индекса социальной сплочённости"""
        telegram_engagement = data.get('telegram_data', {}).get('engagement_analysis', {}).get('avg_engagement', 0)
        twitter_activity = data.get('twitter_data', {}).get('regional_activity', 0.5)
        news_sentiment = data.get('news_data', {}).get('sentiment_breakdown', {}).get('positive_ratio', 0.5)
        
        return (telegram_engagement * 0.3 + twitter_activity * 0.3 + news_sentiment * 0.4)
    
    def _calculate_information_entropy(self, data: Dict) -> float:
        """Расчет информационной энтропии"""
        news_diversity = len(data.get('news_data', {}).get('key_themes', [])) / 10.0
        twitter_trend_variety = len(data.get('twitter_data', {}).get('trending_topics', [])) / 5.0
        
        return min(1.0, (1 - news_diversity) * 0.6 + (1 - twitter_trend_variety) * 0.4)

# --- CLASS: RateLimiter ---
class RateLimiter:
    """Система ограничения частоты запросов"""
    
    def __init__(self):
        self.buckets = {}
        self.default_rates = {
            'telegram': 30,  # запросов в минуту
            'twitter': 300,
            'newsapi': 100,
            'worldbank': 500
        }
    
    async def wait_for_capacity(self, service: str, cost: int = 1):
        """Ожидание доступности capacity для запроса"""
        if service not in self.buckets:
            self.buckets[service] = {
                'tokens': self.default_rates[service],
                'last_refill': datetime.now()
            }
        
        bucket = self.buckets[service]
        self._refill_bucket(bucket, service)
        
        while bucket['tokens'] < cost:
            await asyncio.sleep(0.1)
            self._refill_bucket(bucket, service)
        
        bucket['tokens'] -= cost
    
    def _refill_bucket(self, bucket: Dict, service: str):
        """Пополнение токенов в bucket"""
        now = datetime.now()
        time_passed = (now - bucket['last_refill']).total_seconds()
        
        tokens_to_add = time_passed * (self.default_rates[service] / 60)
        bucket['tokens'] = min(self.default_rates[service], bucket['tokens'] + tokens_to_add)
        bucket['last_refill'] = now

# --- CLASS: BaseSection ---
class BaseSection(BaseModel):
    model_config = ConfigDict(extra="allow", str_strip_whitespace=True)

# --- CLASS: ProjectSection ---
class ProjectSection(BaseSection):
    name: Optional[str] = Field(None, max_length=200)
    start_year: Optional[int] = Field(None, ge=1900, le=2100)
    end_year: Optional[int] = Field(None, ge=1900, le=2100)

    @field_validator("end_year")
    @classmethod
    def check_years(cls, v, info):
        start = info.data.get("start_year")
        if v is not None and start is not None and v < start:
            raise ValueError(f"end_year ({v}) < start_year ({start})")
        return v

# --- CLASS: InnovationSection ---
class InnovationSection(BaseSection):
    tokenization: Optional[str] = Field(None, pattern="^(planned|in_progress|done|cancelled)$")
    phases: Optional[List[str]] = None

    @field_validator("phases")
    @classmethod
    def check_phases(cls, v):
        if v is None:
            return v
        allowed = {"pilot", "scaling", "integration", "research", "production"}
        for phase in v:
            if phase not in allowed:
                raise ValueError(f"Недопустимая фаза: {phase!r}. Доступно: {allowed}")
        return v

# --- CLASS: FinanceSection ---
class FinanceSection(BaseSection):
    capital_structure: Optional[Dict[str, float]] = None
    WACC: Optional[float] = Field(None, ge=0.0, le=1.0)
    currency: Optional[str] = Field(None, max_length=10)
    total_budget: Optional[float] = Field(None, ge=0)

    @field_validator("capital_structure")
    @classmethod
    def check_shares(cls, v):
        if v is None:
            return v
        for k, share in v.items():
            if not (0.0 <= share <= 1.0):
                raise ValueError(f"Доля {k}={share} вне диапазона [0,1]")
        total = sum(v.values())
        if not (0.99 <= total <= 1.01):
            raise ValueError(f"Сумма долей должна быть ≈1.0, получено {total:.3f}")
        return v

