# --- CLASS: SniperTransition ---
class SniperTransition:
    """Ладья-снайпер — прямой переход через слои."""
    from_node: str
    to_node: str
    from_layer: str
    to_layer: str
    distance_layers: int
    checkpoints: List[str] = field(default_factory=list)

    MAX_DISTANCE = 3
    MIN_LEVEL = "L2"

    def validate(self, initiator_level: str) -> bool:
        if self.distance_layers > self.MAX_DISTANCE:
            return False
        if self.LEVEL_INDEX(initiator_level) < self.LEVEL_INDEX(self.MIN_LEVEL):
            return False
        return True

    @staticmethod
    def LEVEL_INDEX(level: str) -> int:
        return {"L0": 0, "L1": 1, "L2": 2, "L3": 3, "L4": 4}.get(level, -1)

# --- CLASS: GuardianDeclaration ---
class GuardianDeclaration:
    """Ферзь-хранитель — защита группы узлов."""
    guardian_node: str
    level: str
    protected_nodes: List[str]
    reporting_period_days: int = 30

    def declare(self) -> Dict:
        if not self.level.startswith("L3") and not self.level.startswith("L4"):
            return {"status": "rejected", "reason": "requires_L3_or_higher"}
        return {
            "status": "active",
            "guardian": self.guardian_node,
            "protected": self.protected_nodes,
            "reporting_in": self.reporting_period_days,
            "declared_at": datetime.utcnow().isoformat(),
        }

