# --- CLASS: BishopDuo ---
class BishopDuo:
    """Дуэт слонов — парная изоляция."""
    bishop_a: str
    bishop_b: str
    target: str
    layers: List[str]
    auto_release_hours: int = 72

    def activate(self) -> Dict:
        if self.bishop_a == self.bishop_b:
            return {"status": "rejected", "reason": "same_node"}
        if len(self.layers) < 2:
            return {"status": "rejected", "reason": "needs_two_layers"}
        return {
            "status": "isolation_active",
            "target": self.target,
            "bishops": [self.bishop_a, self.bishop_b],
            "layers": self.layers,
            "release_at": (datetime.utcnow() + timedelta(hours=self.auto_release_hours)).isoformat(),
        }

