# --- CLASS: PrintableAcceleratorModel ---
class PrintableAcceleratorModel:
    def __init__(self, scale_factor=0.001):  # 1:1000
        self.scale = scale_factor
        self.phi = 1.6180339887
        
    def create_printable_components(self):
        """Создание компонентов для 3D-печати"""
        
        components = {
            "спирали": self._create_spiral_components(),
            "точка_слияния": self._create_convergence_component(),
            "кольца": self._create_ring_components(),
            "опорные_конструкции": self._create_support_structures(),
            "соединительные_элементы": self._create_connectors()
        }
        
        return components
    
    def _create_spiral_components(self):
        """Создание спиралей для печати"""
        spiral_specs = []
        
        for i in range(3):
            # Параметры спирали в метрах (масштаб 1:1000)
            height = 1.0  # 1 метр вместо 1000
            radius = 0.5  # 0.5 метра вместо 500
            turns = 7
            
            # Генерация точек спирали
            t = np.linspace(0, turns * 2 * np.pi, 500)
            z = height * t / (turns * 2 * np.pi)
            r = radius * np.exp(-t / (turns * 2 * np.pi * self.phi))
            
            angle_offset = i * 120 * np.pi / 180
            x = r * np.cos(t + angle_offset)
            y = r * np.sin(t + angle_offset)
            
            spiral_specs.append({
                "points": np.column_stack([x, y, z]),
                "diameter": 0.02,  # 20мм толщина направляющей
                "material": "PETG",  # Для прочности и гибкости
                "print_time": f"~{len(t)*0.5/60:.1f} часов",
                "support_required": "минимальное"
            })
        
        return spiral_specs
    
    def _create_convergence_component(self):
        """Точка слияния для печати"""
        return {
            "type": "сфера",
            "diameter": 0.03,  # 30мм
            "position": [0, 0, 1.0],
            "material": "ABS+",
            "complexity": "средняя",
            "print_orientation": "вертикально",
            "estimated_time": "2 часа"
        }
    
    def generate_stl_files(self):
        """Генерация STL файлов для печати"""
        
        stl_packages = {
            "package_1": {
                "files": ["spiral_1.stl", "spiral_2.stl", "spiral_3.stl"],
                "print_time": "18 часов",
                "material_volume": "45 см³ PETG",
                "layer_height": "0.15 мм"
            },
            "package_2": {
                "files": ["convergence_point.stl", "rings.stl", "connectors.stl"],
                "print_time": "12 часов", 
                "material_volume": "30 см³ ABS+",
                "layer_height": "0.15 мм"
            },
            "assembly_guide": {
                "file": "accelerator_assembly.pdf",
                "steps": 25,
                "estimated_assembly_time": "3 часа",
                "tools_required": ["суперклей", "плоскогубцы", "линейка"]
            }
        }
        
        return stl_packages

# --- CLASS: AdvancedPhiBalancer ---
class AdvancedPhiBalancer:
    def __init__(self):
        self.phi = 1.6180339887
        self.gamma = 7
        
    def drone_dynamics(self, state, t, controls):
        """Динамическая модель дрона с 6 степенями свободы"""
        x, y, z, phi, theta, psi, u, v, w, p, q, r = state
        fx, fy, fz, tau_phi, tau_theta, tau_psi = controls
        
        # Параметры дрона (примерные)
        m = 1.2  # масса
        Ixx, Iyy, Izz = 0.01, 0.01, 0.02  # моменты инерции
        
        # Уравнения движения
        dxdt = [
            u, v, w,  # позиция
            p + q*np.sin(phi)*np.tan(theta) + r*np.cos(phi)*np.tan(theta),
            q*np.cos(phi) - r*np.sin(phi),
            (q*np.sin(phi) + r*np.cos(phi)) / np.cos(theta),  # углы
            (fx/m) - (g*np.sin(theta)),
            (fy/m) + (g*np.cos(theta)*np.sin(phi)),
            (fz/m) + (g*np.cos(theta)*np.cos(phi)) - g,  # линейные скорости
            ((Iyy - Izz)*q*r + tau_phi) / Ixx,
            ((Izz - Ixx)*p*r + tau_theta) / Iyy,
            ((Ixx - Iyy)*p*q + tau_psi) / Izz  # угловые скорости
        ]
        
        return dxdt
    
    def phi_controller(self, desired_state, current_state):
        """Φ-оптимизированный контроллер"""
        errors = desired_state - current_state
        
        # Φ-оптимизированные коэффициенты
        kp_matrix = np.diag([1/self.phi, 1/self.phi, self.phi, 
                            self.phi, 1/self.phi, 1/self.phi])
        
        # Спиральная коррекция ошибок
        spiral_correction = self._spiral_error_transform(errors)
        
        controls = kp_matrix @ spiral_correction
        return controls
    
    def _spiral_error_transform(self, errors):
        """Преобразование ошибок через φ-спираль"""
        t = np.linspace(0, 2*np.pi*self.gamma, len(errors))
        spiral = np.exp(-t / (2*np.pi*self.phi)) * np.exp(1j * t * self.phi)
        
        # Применение спиральной фильтрации к ошибкам
        transformed_errors = errors * np.real(spiral[:len(errors)])
        return transformed_errors
    
    def simulate_flight(self, duration=10, dt=0.01):
        """Моделирование полета с Φ-стабилизацией"""
        t = np.arange(0, duration, dt)
        n_steps = len(t)
        
        # Начальные условия
        state0 = np.zeros(12)
        desired_trajectory = np.column_stack([
            0.5*np.sin(0.5*t),  # x - синусоидальная траектория
            0.3*np.cos(0.3*t),  # y
            2 + 0.1*t,          # z - медленный подъем
            np.zeros(n_steps),   # углы = 0 (стабилизация)
            np.zeros(n_steps),
            np.zeros(n_steps)
        ])
        
        states = np.zeros((n_steps, 12))
        states[0] = state0
        controls_log = np.zeros((n_steps, 6))
        
        for i in range(1, n_steps):
            current_state = states[i-1, :6]  # Только позиция и углы
            desired_state = desired_trajectory[i]
            
            # Вычисление управления
            controls = self.phi_controller(desired_state, current_state)
            controls_log[i] = controls
            
            # Интегрирование динамики
            state_dot = self.drone_dynamics(states[i-1], t[i-1], controls)
            states[i] = states[i-1] + state_dot * dt
        
        return t, states, controls_log, desired_trajectory

    def plot_results(self, t, states, controls, desired):
        """Визуализация результатов моделирования"""
        fig, axes = plt.subplots(3, 2, figsize=(15, 12))
        
        # Позиция
        axes[0,0].plot(t, states[:,0], 'b-', label='X фактическая')
        axes[0,0].plot(t, desired[:,0], 'r--', label='X желаемая')
        axes[0,0].set_ylabel('Позиция X (м)')
        axes[0,0].legend()
        
        axes[0,1].plot(t, states[:,1], 'g-', label='Y фактическая')
        axes[0,1].plot(t, desired[:,1], 'm--', label='Y желаемая') 
        axes[0,1].set_ylabel('Позиция Y (м)')
        axes[0,1].legend()
        
        # Углы
        axes[1,0].plot(t, np.degrees(states[:,3]), label='Крен (φ)')
        axes[1,0].set_ylabel('Угол (градусы)')
        axes[1,0].set_title('Стабилизация крена')
        
