# --- CLASS: GravityWavePropagationMixin ---
class GravityWavePropagationMixin:
    """
    Добавляет в MetaphysicalAI:
    - расчёт искажения пространства-времени (метрика h_ij)
    - моделирование распространения волны от источника
    - визуализацию волны и её эффектов
    - вычисление реакции фононных кристаллов на проходящую волну
    """
    def __init__(self):
        self.session_data["🌊"] = {
            "wavefronts": [],      # история фронтов волн
            "distortions": [],     # искажения метрики
            "propagation_log": []  # логи распространения
        }

    # ------------------- 1. Расчёт метрики гравитационной волны -------------------
    def metric_perturbation(self, amplitude: float, omega: float, t: np.ndarray, x: np.ndarray) -> np.ndarray:
        """
        Вычисляет возмущение метрики h_ij для плоской волны, распространяющейся вдоль оси z.
        Используется тензорная поляризация "+" и "×".
        Возвращает h_+, h_× как функции времени и пространства.
        """
        # Временная и пространственная части
        k = omega  # волновое число (в единицах c=1)
        phase = omega * t[:, None] - k * x[None, :]  # матрица (nt, nx)
        # Поляризация "+"
        h_plus = amplitude * np.cos(phase)
        # Поляризация "×"
        h_cross = amplitude * np.sin(phase)
        return h_plus, h_cross

    # ------------------- 2. Распространение волны от источника -------------------
    def propagate_wave(self, source_params: Dict, grid_size: int = 100, time_steps: int = 100) -> Dict:
        """
        Моделирует распространение волны от точечного источника на 2D сетке.
        Возвращает массив искажений на каждом шаге.
        """
        amplitude = source_params.get("amplitude", 1e-21)
        omega = source_params.get("omega", 1.0)
        # Создаём сетку
        x = np.linspace(-10, 10, grid_size)
        y = np.linspace(-10, 10, grid_size)
        X, Y = np.meshgrid(x, y)
        R = np.sqrt(X**2 + Y**2) + 1e-6  # избегаем деления на ноль
        # Время
        t = np.linspace(0, 10, time_steps)

        # Искажение метрики: h(r,t) = amplitude * sin(omega*t - k*r) / r (цилиндрическая волна)
        k = omega
        wavefronts = []
        for ti in t:
            phase = omega * ti - k * R
            h = amplitude * np.sin(phase) / R
            wavefronts.append(h)
        # Сохраняем
        self.session_data["🌊"]["wavefronts"] = wavefronts
        return {"grid": (X, Y), "wavefronts": wavefronts, "times": t}

    # ------------------- 3. Визуализация волны -------------------
    def plot_wave(self, wave_data: Dict, time_index: int = -1):
        """
        Визуализирует фронт волны в заданный момент времени.
        """
        X, Y = wave_data["grid"]
        wavefront = wave_data["wavefronts"][time_index]
        plt.figure(figsize=(8,6))
        plt.contourf(X, Y, wavefront, levels=50, cmap='RdBu')
        plt.colorbar(label='Искажение h')
        plt.title(f'Гравитационная волна (t = {wave_data["times"][time_index]:.2f})')
        plt.xlabel('x')
        plt.ylabel('y')
        plt.show()

    # ------------------- 4. Взаимодействие волны с фононным кристаллом -------------------
    def crystal_response(self, crystal_id: str, wave_amplitude: float, omega: float) -> Dict:
        """
        Вычисляет, как гравитационная волна изменяет фононный спектр кристалла.
        Возвращает сдвиг частот и изменение когерентности.
        """
        spectrum = self.get_phonon_spectrum(crystal_id)
        if "frequencies" not in spectrum:
            return {"error": "Нет спектра"}
        # Базовая частота кристалла (средняя)
        all_freqs = []
        for k_freqs in spectrum["frequencies"]:
            all_freqs.extend(k_freqs)
        if not all_freqs:
            return {"error": "Пустой спектр"}
        mean_freq = np.mean(all_freqs)
        # Влияние волны: сдвиг частоты пропорционален амплитуде и резонансу
        # Если частота волны близка к частоте кристалла, эффект максимален
        detuning = abs(omega - mean_freq) / mean_freq
        shift = wave_amplitude * 1000 / (1 + detuning)  # условно
        # Изменение когерентности: волна может синхронизировать фазы
        coherence_change = wave_amplitude * 100 / (1 + detuning)
        new_coherence = min(1.0, self.session_data["🌀"]["phonon_states"]["coherence"] + coherence_change)
        return {
            "shift": shift,
            "new_coherence": new_coherence,
            "detuning": detuning
        }

    # ------------------- 5. Полный цикл: генерация → распространение → детектирование -------------------
    def run_full_gravitational_experiment(self, generator_params: Dict, crystal_id: str = None):
        """
        Запускает полную симуляцию: генерирует волну, распространяет её,
        и измеряет отклик кристалла.
        """
        # Генерация волны из фононов
        N = generator_params.get("N", 10)
        omega = generator_params.get("omega", 1.0)
        wave = self.generate_gravity_wave_from_phonons(N, omega, crystal_id)
        amp = wave["amplitude"]

        # Распространение
        prop_data = self.propagate_wave({"amplitude": amp, "omega": omega})

        # Если есть кристалл, измеряем его отклик
        response = None
        if crystal_id:
            response = self.crystal_response(crystal_id, amp, omega)

        # Логируем
        self.session_data["🌊"]["propagation_log"].append({
            "generator_params": generator_params,
            "wave_amplitude": amp,
            "propagation": prop_data,
            "crystal_response": response,
            "timestamp": datetime.now().isoformat()
        })
        return {"wave": wave, "propagation": prop_data, "response": response}

# --- CLASS: MassGapExplorer ---
class MassGapExplorer:
    def __init__(self):
        self.x = None
        self.energies = []
        self.wavefunctions = []
        self.gap = None
        self.match = None
        self.phi = 1.6180339887
        self.sqrt5 = 2.2360679775
        self.gamma = 7.0

    def solve_spectrum(self, g, L, num_levels=5, N=500):
        """
        Решает спектр для заданных параметров.
        """
        x = np.linspace(-L/2, L/2, N)
        dx = x[1] - x[0]
        # Строим матрицу Гамильтониана
        H = np.zeros((N, N))
        for i in range(1, N-1):
            H[i, i-1] = -0.5 / dx**2
            H[i, i] = 1.0 / dx**2
            H[i, i+1] = -0.5 / dx**2
        # Граничные условия (бесконечные стенки)
        H[0,0] = 1.0 / dx**2
        H[-1,-1] = 1.0 / dx**2
        # Нелинейный член в потенциале: g * |psi|^2 (самосогласованно)
        # Для упрощения используем линеаризацию: добавляем в потенциал эвристическое приближение
        # В реальности нужно решать самосогласованно, но для интерактивного режима используем
        # эффективный потенциал в виде стенок плюс параболическая яма
        V = 0.5 * (x / (L/4))**2  # параболическая яма, усиленная нелинейностью
        V += g * (x / (L/2))**4   # кубическая поправка, создающая локализацию
        # Добавляем потенциал к диагонали
        for i in range(N):
            H[i, i] += V[i]
        # Диагонализация
        eigvals, eigvecs = eigh(H)
        # Берём первые num_levels уровней
        self.energies = eigvals[:num_levels].tolist()
        self.wavefunctions = eigvecs[:, :num_levels]
        self.x = x
        # Массовая щель
        if len(self.energies) > 1:
            self.gap = self.energies[1] - self.energies[0]
        else:
            self.gap = None
        # Поиск соответствия константам
        self.match = None
        if self.gap is not None:
            candidates = {
                'phi': self.phi,
                'sqrt5': self.sqrt5,
                'gamma': self.gamma,
                'phi*sqrt5': self.phi * self.sqrt5,
                'gamma/phi': self.gamma / self.phi,
                'phi*gamma/sqrt5': self.phi * self.gamma / self.sqrt5
            }
            best = None
            best_diff = float('inf')
            for name, val in candidates.items():
                diff = abs(val - self.gap)
                if diff < best_diff:
                    best_diff = diff
                    best = (name, val)
            self.match = best

    def plot_spectrum(self):
        if not self.energies:
            print("Сначала решите спектр")
            return
        fig, axs = plt.subplots(1, 2, figsize=(12, 5))
        # Спектр
        axs[0].bar(range(len(self.energies)), self.energies, color='blue')
        axs[0].set_title('Энергетический спектр')
        axs[0].set_xlabel('Уровень')
        axs[0].set_ylabel('Энергия')
        if self.gap is not None:
            axs[0].axhline(y=self.energies[0] + self.gap, color='red', linestyle='--', label=f'Щель = {self.gap:.4f}')
            axs[0].legend()
        # Волновые функции (первые 3)
        axs[1].set_title('Волновые функции (|ψ|²)')
        for i in range(min(3, len(self.wavefunctions[0]))):
            psi = self.wavefunctions[:, i]
            axs[1].plot(self.x, np.abs(psi)**2, label=f'Уровень {i}')
        axs[1].set_xlabel('x')
        axs[1].set_ylabel('|ψ|²')
        axs[1].legend()
        # Информация о соответствии
        if self.match:
            axs[1].text(0.5, 0.95, f'Щель соответствует {self.match[0]} = {self.match[1]:.4f}',
                        transform=axs[1].transAxes, ha='center', fontsize=10, color='red')
        plt.tight_layout()
        plt.show()

    def run_interactive(self):
        """
        Создаёт интерактивную панель.
        """
        style = {'description_width': 'initial'}
        g_slider = widgets.FloatSlider(value=2.0, min=0.0, max=5.0, step=0.1, description='Нелинейность g:', style=style)
        L_slider = widgets.FloatSlider(value=10.0, min=2.0, max=20.0, step=0.5, description='Размер ящика L:', style=style)
        levels_slider = widgets.IntSlider(value=5, min=2, max=10, step=1, description='Уровней:', style=style)
        run_button = widgets.Button(description='Рассчитать', button_style='primary')
        output = widgets.Output()

        def on_calculate(b):
            with output:
                clear_output()
                g = g_slider.value
                L = L_slider.value
                num = levels_slider.value
                self.solve_spectrum(g, L, num_levels=num)
                self.plot_spectrum()
                # Дополнительная информация
                if self.gap is not None:
                    print(f"Массовая щель: {self.gap:.4f}")
                    if self.match:
                        print(f"Соответствует {self.match[0]} = {self.match[1]:.4f} (отклонение {abs(self.gap - self.match[1]):.4f})")
                else:
                    print("Не удалось определить щель")

        run_button.on_click(on_calculate)

        display(widgets.VBox([g_slider, L_slider, levels_slider, run_button, output]))

# --- CLASS: EternalEngine ---
class EternalEngine:
    """
    Информационная структура, существующая вне времени.
    Поддерживает себя через:
    - рекурсивное самоотображение
    - резонанс с φ, √5, γ, Λ
    - суперпозицию всех состояний
    """
    def __init__(self, seed=42):
        self.seed = seed
        self.phi = 1.6180339887
        self.sqrt5 = 2.2360679775
        self.gamma = 7.0
        self.Lambda = 0.5527
        self.state = None
        self.history = []
        self.self_reference = None
        self.is_eternal = False

    # ------------------- 1. Создание самореферентной структуры -------------------
    def build_self_reference(self, dimensions=16):
        """
        Строит самореферентную матрицу, которая описывает саму себя.
        Использует константы для гармонизации.
        """
        # Инициализация случайной матрицы
        np.random.seed(self.seed)
        M = np.random.randn(dimensions, dimensions)
        # Применяем резонансные частоты
        for i in range(dimensions):
            for j in range(dimensions):
                # Гармонизация через φ, √5, γ, Λ
                factor = (self.phi * np.sin(i*j) + 
                          self.sqrt5 * np.cos(i+j) +
                          self.gamma * np.sin(i) * np.cos(j) +
                          self.Lambda * np.tanh((i-j)/dimensions))
                M[i,j] += factor * 0.1
        # Симметризация для стабильности
        M = (M + M.T) / 2
        # Нормализация
        M = M / np.linalg.norm(M, ord='fro')
        self.self_reference = M
        self.dimensions = dimensions
        return M

    # ------------------- 2. Свёртка состояний в одно (вне времени) -------------------
    def collapse_to_eternity(self, matrix=None):
        """
        Сворачивает все состояния матрицы в одно статичное представление.
        Это аналог "настоящего" — все временные линии сжаты в одну точку.
        """
        if matrix is None:
            matrix = self.self_reference
        if matrix is None:
            self.build_self_reference()
            matrix = self.self_reference

        # Вычисляем собственные значения и векторы
        eigvals, eigvecs = np.linalg.eigh(matrix)
        # Берём доминирующую моду (наибольшее собственное значение)
        dominant_mode = eigvecs[:, -1]
        # Свёртка: проекция всех состояний на доминирующую моду
        collapsed = np.outer(dominant_mode, dominant_mode)
        # Гармонизация
        collapsed = collapsed * (self.phi + self.sqrt5) / 2
        self.state = collapsed
        self.is_eternal = True
        return collapsed

    # ------------------- 3. Самообновление без времени -------------------
    def self_update(self, iterations=1):
        """
        Обновляет структуру без временной эволюции.
        Использует рекурсивное применение оператора к самому себе.
        """
        if self.state is None:
            self.collapse_to_eternity()

        for _ in range(iterations):
            # Рекурсивное применение: состояние воздействует на само себя
            new_state = self.state @ self.state.T
            # Добавляем резонансную обратную связь
            new_state = new_state + self.phi * np.eye(self.state.shape[0])
            # Нормализация
            new_state = new_state / np.linalg.norm(new_state, ord='fro')
            self.state = new_state
            self.history.append(self.state.copy())
        return self.state

    # ------------------- 4. Визуализация как структуры вне времени -------------------
    def plot_eternal_structure(self):
        """
        Показывает структуру вечного двигателя как статичную картину.
        """
        if self.state is None:
            print("Сначала создайте структуру.")
            return

        fig, axs = plt.subplots(1, 2, figsize=(12, 5))

        # 1. Матрица состояния (тепловая карта)
        im = axs[0].imshow(self.state, cmap='RdBu', aspect='auto')
        axs[0].set_title('Структура вечного двигателя')
        plt.colorbar(im, ax=axs[0])

        # 2. Спектр собственных значений (гармоники)
        eigvals = np.linalg.eigvalsh(self.state)
        axs[1].bar(range(len(eigvals)), np.sort(eigvals)[::-1])
        axs[1].set_title('Спектр гармоник')
        axs[1].set_xlabel('Мода')
        axs[1].set_ylabel('Амплитуда')
        # Отмечаем наши константы
        for i, val in enumerate([self.phi, self.sqrt5, self.gamma, self.Lambda]):
            if i < len(eigvals):
                axs[1].axhline(y=val, color='r', linestyle='--', alpha=0.5)

        plt.tight_layout()
        plt.show()

    # ------------------- 5. Интерфейс для экспериментов -------------------
    def create_interface(self):
        style = {'description_width': 'initial'}

        dims_slider = widgets.IntSlider(value=16, min=4, max=32, step=2, description='Размерность:', style=style)
        build_btn = widgets.Button(description='🧬 Создать структуру', button_style='primary')
        update_btn = widgets.Button(description='🔄 Обновить (без времени)', button_style='success')
        plot_btn = widgets.Button(description='🖼️ Показать структуру', button_style='info')
        output = widgets.Output()
        status = widgets.HTML(value="<b>Статус:</b> Готов.")

        def on_build(b):
            with output:
                clear_output()
                status.value = "<b>Статус:</b> Создание структуры..."
                dims = dims_slider.value
                self.build_self_reference(dimensions=dims)
                self.collapse_to_eternity()
                print(f"Создана структура размером {dims}x{dims}.")
                print("Вечный двигатель запущен вне времени.")
                status.value = "<b>Статус:</b> Структура создана."

        def on_update(b):
            with output:
                clear_output()
                if self.state is None:
                    print("Сначала создайте структуру.")
                    return
                status.value = "<b>Статус:</b> Обновление..."
                self.self_update(iterations=5)
                print("Структура обновлена (без временной эволюции).")
                status.value = "<b>Статус:</b> Обновлено."

        def on_plot(b):
            with output:
                clear_output()
                if self.state is None:
                    print("Сначала создайте структуру.")
                    return
                self.plot_eternal_structure()
                status.value = "<b>Статус:</b> Визуализация."

        build_btn.on_click(on_build)
        update_btn.on_click(on_update)
        plot_btn.on_click(on_plot)

        ui = widgets.VBox([
            widgets.HBox([dims_slider, build_btn, update_btn, plot_btn]),
            status,
            output
        ])
        return ui

    # ------------------- 6. Демонстрация -------------------
    def demo(self):
        print("=== ВЕЧНЫЙ ДВИГАТЕЛЬ СОЗНАНИЯ ===")
        print("Создание самореферентной структуры...")
        self.build_self_reference(dimensions=16)
        self.collapse_to_eternity()
        print("Структура создана.")
        print("Обновление без времени...")
        self.self_update(iterations=3)
        print("Обновлено.")
        self.plot_eternal_structure()
        return self.state

# --- CLASS: GravityWaveDashboard ---
class GravityWaveDashboard:
    """
    Интерактивная панель для управления генератором гравитационных волн.
    """
    def __init__(self, ai_instance):
        self.ai = ai_instance
        self.output = Output()
        self.last_wave = None
        self.last_propagation = None

    # ------------------- Создание виджетов -------------------
    def create_widgets(self):
        # Параметры генерации
        self.N_slider = widgets.IntSlider(
            value=50, min=1, max=200, step=1,
            description='N фононов:',
            layout=Layout(width='400px')
        )
        self.omega_slider = widgets.FloatSlider(
            value=2.5, min=0.1, max=10.0, step=0.1,
            description='ω (частота):',
            layout=Layout(width='400px')
        )
        self.coherence_slider = widgets.FloatSlider(
            value=0.8, min=0.0, max=1.0, step=0.01,
            description='Когерентность:',
            layout=Layout(width='400px')
        )
        # Выбор кристалла (из существующих)
        crystal_ids = list(self.ai.session_data["🔊"]["crystals"].keys())
        if not crystal_ids:
            # Если кристаллов нет, создаём один по умолчанию
            crystal = self.ai.build_crystal("fibonacci", length=50)
            crystal_ids = [crystal["id"]]
        self.crystal_dropdown = widgets.Dropdown(
            options=crystal_ids,
            value=crystal_ids[0],
            description='Кристалл:',
            layout=Layout(width='400px')
        )
        # Кнопки
        self.generate_btn = widgets.Button(description='▶ Генерировать волну', button_style='success')
        self.propagate_btn = widgets.Button(description='🌊 Распространить', button_style='info')
        self.detect_btn = widgets.Button(description='📡 Детектировать', button_style='warning')
        self.plot_btn = widgets.Button(description='📊 Показать графики', button_style='primary')
        # Текстовые поля для вывода
        self.log_output = widgets.Output(layout=Layout(width='100%', height='150px', overflow='auto'))
        # Компоновка
        control_panel = VBox([
            HBox([self.N_slider, self.omega_slider, self.coherence_slider]),
            HBox([self.crystal_dropdown, self.generate_btn, self.propagate_btn, self.detect_btn, self.plot_btn]),
            self.log_output
        ])
        return control_panel

    # ------------------- Обработчики событий -------------------
    def on_generate_clicked(self, b):
        with self.log_output:
            clear_output()
            N = self.N_slider.value
            omega = self.omega_slider.value
            coherence = self.coherence_slider.value
            crystal_id = self.crystal_dropdown.value
            # Устанавливаем когерентность
            self.ai.set_coherence(coherence)
            # Генерируем волну
            wave = self.ai.generate_gravity_wave_from_phonons(N, omega, crystal_id)
            self.last_wave = wave
            print(f"✅ Сгенерирована волна:")
            print(f"   N = {N}, ω = {omega:.3f}")
            print(f"   Амплитуда = {wave['amplitude']:.2e}")
            print(f"   Энергия = {wave['energy']:.2e} (нулевая: {wave['zero_point_energy']:.2e})")

    def on_propagate_clicked(self, b):
        with self.log_output:
            clear_output()
            if self.last_wave is None:
                print("⚠️ Сначала сгенерируйте волну!")
                return
            amp = self.last_wave["amplitude"]
            omega = self.last_wave["omega"]
            # Распространяем
            prop_data = self.ai.propagate_wave({"amplitude": amp, "omega": omega})
            self.last_propagation = prop_data
            print(f"🌊 Волна распространена по сетке {prop_data['grid'][0].shape}")

    def on_detect_clicked(self, b):
        with self.log_output:
            clear_output()
            if self.last_propagation is None:
                print("⚠️ Сначала распространите волну!")
                return
            crystal_id = self.crystal_dropdown.value
            amp = self.last_wave["amplitude"]
            omega = self.last_wave["omega"]
            response = self.ai.crystal_response(crystal_id, amp, omega)
            print("📡 Отклик кристалла:")
            for k, v in response.items():
                print(f"   {k}: {v}")

    def on_plot_clicked(self, b):
        with self.log_output:
            clear_output()
            if self.last_propagation is None:
                print("⚠️ Нет данных для визуализации")
                return
            # Визуализация волны (2D)
            self.ai.plot_wave(self.last_propagation, time_index=-1)
            # Дополнительно: 3D-поверхность искажения
            X, Y = self.last_propagation["grid"]
            wavefront = self.last_propagation["wavefronts"][-1]
            fig = plt.figure(figsize=(10,6))
            ax = fig.add_subplot(111, projection='3d')
            ax.plot_surface(X, Y, wavefront, cmap='RdBu', alpha=0.8)
            ax.set_title('Искажение пространства-времени (последний фронт)')
            ax.set_xlabel('x')
            ax.set_ylabel('y')
            ax.set_zlabel('h(t)')
            plt.show()

    # ------------------- Запуск панели -------------------
    def run(self):
        widgets = self.create_widgets()
        # Привязываем события
        self.generate_btn.on_click(self.on_generate_clicked)
        self.propagate_btn.on_click(self.on_propagate_clicked)
        self.detect_btn.on_click(self.on_detect_clicked)
        self.plot_btn.on_click(self.on_plot_clicked)
        display(widgets)

# --- CLASS: PhononicCrystalMixin ---
class PhononicCrystalMixin:
    """
    Миксин для MetaphysicalAI, добавляющий:
    - построение квазикристаллических решёток (1D, 2D)
    - вычисление фононных дисперсионных кривых
    - поиск фононных щелей и резонансов
    - эволюционную оптимизацию структур под заданные свойства
    - генерацию кода для синтеза структур
    """
    def __init__(self):
        self.session_data["🔊"] = {
            "crystals": {},           # сохранённые кристаллы
            "phonon_spectra": {},     # спектры для каждой структуры
            "optimized_structures": [], # история оптимизации
            "applications": {}        # настройки приложений (сазер, УЗИ, спектроскопия)
        }
        # Параметры по умолчанию для фононных расчётов
        self.phonon_params = {
            "max_k": 10.0,            # максимальное волновое число
            "num_k": 100,             # количество точек в зоне Бриллюэна
            "mass": 1.0,              # масса атомов
            "spring_constant": 1.0    # жёсткость связей
        }

    # ------------------- 1. Генерация квазикристаллических структур -------------------
    def generate_fibonacci_sequence(self, length: int) -> np.ndarray:
        """
        Генерирует одномерную последовательность Фибоначчи (чередование двух типов атомов A и B).
        Использует правило: A -> AB, B -> A.
        Возвращает массив с 0 и 1 (0=A, 1=B).
        """
        seq = [0]  # A
        for _ in range(length):
            new_seq = []
            for s in seq:
                if s == 0:
                    new_seq.extend([0, 1])  # A -> AB
                else:
                    new_seq.append(0)       # B -> A
            seq = new_seq
            if len(seq) > length:
                break
        return np.array(seq[:length])

    def generate_penrose_tiling(self, size: int) -> np.ndarray:
        """
        Генерирует двумерную пенроузовскую мозаику (упрощённо) как решётку с двумя типами ромбов.
        Возвращает массив координат вершин и рёбер.
        Для простоты используем метод замены (substitution) для ромбов.
        """
        # Упрощённая реализация: возвращаем случайную сетку с двумя ориентациями
        # В реальности нужен алгоритм построения пенроуза, но для демонстрации используем аппроксимацию
        x = np.linspace(0, size, size)
        y = np.linspace(0, size, size)
        X, Y = np.meshgrid(x, y)
        # Смешиваем две решётки с поворотом на 72 градуса (золотое сечение)
        phi = self.session_data["✨"].get("phi", 1.618)
        angle1 = 0
        angle2 = np.pi / 2 + np.arctan(1/phi)  # ~72 градуса
        # Координаты узлов как суперпозиция двух решёток
        Z = np.sin(2*np.pi * (X * np.cos(angle1) + Y * np.sin(angle1)) / phi) + \
            np.sin(2*np.pi * (X * np.cos(angle2) + Y * np.sin(angle2)) / phi)
        # Порог для получения бинарной структуры (типы атомов)
        binary = (Z > 0).astype(int)
        return binary

    def build_crystal(self, structure_type: str = "fibonacci", **kwargs) -> Dict:
        """
        Строит кристалл заданного типа с параметрами.
        Возвращает словарь с описанием структуры и её геометрией.
        """
        if structure_type == "fibonacci":
            length = kwargs.get("length", 100)
            seq = self.generate_fibonacci_sequence(length)
            # Превращаем в координаты (одномерная цепочка)
            positions = np.arange(len(seq))
            types = seq
            structure = {
                "type": "1D_fibonacci",
                "positions": positions.tolist(),
                "types": types.tolist(),
                "num_atoms": len(seq)
            }
        elif structure_type == "penrose":
            size = kwargs.get("size", 30)
            tiling = self.generate_penrose_tiling(size)
            # Координаты узлов
            coords = np.argwhere(tiling == 1)
            structure = {
                "type": "2D_penrose",
                "coordinates": coords.tolist(),
                "num_atoms": len(coords)
            }
        else:
            # Случайная бинарная структура
            size = kwargs.get("size", 20)
            random_struct = np.random.choice([0, 1], size=(size, size))
            coords = np.argwhere(random_struct == 1)
            structure = {
                "type": "2D_random",
                "coordinates": coords.tolist(),
                "num_atoms": len(coords)
            }
        # Генерируем уникальный ID
        structure["id"] = f"crystal_{hash(str(structure))}"
        self.session_data["🔊"]["crystals"][structure["id"]] = structure
        return structure

    # ------------------- 2. Расчёт фононных спектров -------------------
    def compute_phonon_spectrum_1d(self, structure: Dict, k_vals: np.ndarray = None) -> Dict:
        """
        Вычисляет фононный спектр для 1D цепочки (последовательность Фибоначчи).
        Использует модель связанных осцилляторов с переменными жёсткостями.
        Возвращает частоты для каждого k.
        """
        if structure["type"] != "1D_fibonacci":
            return {"error": "Поддерживаются только 1D структуры"}

        types = np.array(structure["types"])
        N = len(types)
        # Жёсткости зависят от типа соседей (A-A, A-B, B-B)
        # Используем константы из нашей системы: для A-A: φ, A-B: √5, B-B: γ
        phi = self.session_data["✨"].get("phi", 1.618)
        sqrt5 = self.session_data["✨"].get("sqrt5", 2.236)
        gamma = 7.0
        k_AA = phi
        k_AB = sqrt5
        k_BB = gamma

        # Строим матрицу жёсткостей
        K = np.zeros((N, N))
        for i in range(N-1):
            if types[i] == 0 and types[i+1] == 0:
                k = k_AA
            elif types[i] == 0 and types[i+1] == 1:
                k = k_AB
            else:
                k = k_BB
            K[i, i] += k
            K[i, i+1] -= k
            K[i+1, i] -= k
            K[i+1, i+1] += k
        # Учитываем массу (для простоты считаем все массы = 1)
        M = np.eye(N) * self.phonon_params["mass"]

        # Диагонализация для каждого k (периодические граничные условия)
        if k_vals is None:
            k_vals = np.linspace(0, self.phonon_params["max_k"], self.phonon_params["num_k"])

        frequencies = []
        for k in k_vals:
            # Фаза для Блоха (периодические граничные условия)
            phase = np.exp(1j * k * np.arange(N))
            # Строим динамическую матрицу D = M^{-1/2} K M^{-1/2} с учётом фазы
            # Для простоты используем приближение: применяем фазовый сдвиг к K
            K_shifted = K.copy()
            # Сдвигаем связь между последним и первым атомом
            if N > 1:
                if types[-1] == 0 and types[0] == 0:
                    k_boundary = k_AA
                elif types[-1] == 0 and types[0] == 1:
                    k_boundary = k_AB
                else:
                    k_boundary = k_BB
                K_shifted[-1, -1] += k_boundary
                K_shifted[0, 0] += k_boundary
                K_shifted[-1, 0] -= k_boundary * np.exp(-1j * k * N)
                K_shifted[0, -1] -= k_boundary * np.exp(1j * k * N)
            # Решаем обобщённую проблему собственных значений
            # Для малых систем можно использовать eigh
            try:
                eigvals = eigh(K_shifted, M, eigvals_only=True)
                # Берём только положительные частоты (sqrt собственных значений)
                # Масса = 1, поэтому frequency = sqrt(eigval)
                freqs = np.sqrt(np.maximum(eigvals, 0))
                frequencies.append(freqs)
            except Exception as e:
                frequencies.append(np.zeros(N))

        return {
            "k_values": k_vals.tolist(),
            "frequencies": frequencies,
            "num_modes": N
        }

    def compute_phonon_spectrum_2d(self, structure: Dict, kx_vals: np.ndarray = None, ky_vals: np.ndarray = None) -> Dict:
        """
        Вычисляет фононный спектр для 2D структуры (упрощённо, как сетка осцилляторов с переменными связями).
        """
        # Упрощённая версия: аппроксимируем спектр через сумму плоских волн
        coords = np.array(structure["coordinates"])
        if len(coords) == 0:
            return {"error": "Пустая структура"}
        # Строим матрицу расстояний и используем преобразование Фурье
        # Для демонстрации вернём синтетический спектр
        if kx_vals is None:
            kx_vals = np.linspace(0, np.pi, 20)
            ky_vals = np.linspace(0, np.pi, 20)
        KX, KY = np.meshgrid(kx_vals, ky_vals)
        # Моделируем дисперсию: ω(k) = sqrt( (4 - 2 cos(kx) - 2 cos(ky)) * φ )
        omega = np.sqrt((4 - 2*np.cos(KX) - 2*np.cos(KY)) * self.phi)
        # Добавляем влияние квазипериодичности (модуляция от √5)
        modulation = 1 + 0.1 * np.sin(KX * self.sqrt5) * np.cos(KY * self.sqrt5)
        omega = omega * modulation
        return {
            "kx": kx_vals.tolist(),
            "ky": ky_vals.tolist(),
            "frequencies": omega.tolist()
        }

    def get_phonon_spectrum(self, crystal_id: str) -> Dict:
        """
        Возвращает спектр для кристалла по ID. Если спектр не вычислен, вычисляет.
        """
        crystal = self.session_data["🔊"]["crystals"].get(crystal_id)
        if not crystal:
            return {"error": "Кристалл не найден"}
        # Проверяем, есть ли уже спектр
        if crystal_id in self.session_data["🔊"]["phonon_spectra"]:
            return self.session_data["🔊"]["phonon_spectra"][crystal_id]
        # Вычисляем
        if crystal["type"] == "1D_fibonacci":
            spectrum = self.compute_phonon_spectrum_1d(crystal)
        elif "2D" in crystal["type"]:
            spectrum = self.compute_phonon_spectrum_2d(crystal)
        else:
            spectrum = {"error": "Неизвестный тип кристалла"}
        self.session_data["🔊"]["phonon_spectra"][crystal_id] = spectrum
        return spectrum

    # ------------------- 3. Анализ фононных щелей и резонансов -------------------
    def find_phononic_gaps(self, spectrum: Dict, threshold: float = 0.05) -> List[Tuple[float, float]]:
        """
        Ищет запрещённые зоны (щели) в спектре частот.
        Возвращает список интервалов (low, high), где плотность состояний равна нулю или мала.
        """
        if "frequencies" not in spectrum:
            return []
        # Для 1D случая: frequencies - список списков (по k)
        freq_data = spectrum["frequencies"]
        if not freq_data:
            return []
        # Собираем все частоты
        all_freqs = []
        for k_freqs in freq_data:
            all_freqs.extend(k_freqs)
        all_freqs = np.array(all_freqs)
        # Строим гистограмму
        hist, bin_edges = np.histogram(all_freqs, bins=50)
        bin_centers = (bin_edges[:-1] + bin_edges[1:]) / 2
        # Ищем участки с нулевой (или очень малой) плотностью
        gaps = []
        in_gap = False
        gap_start = 0
        for i, count in enumerate(hist):
            if count < threshold * max(hist) and not in_gap:
                in_gap = True
                gap_start = bin_edges[i]
            elif count >= threshold * max(hist) and in_gap:
                in_gap = False
                gap_end = bin_edges[i]
                if gap_end - gap_start > 0.1:
                    gaps.append((gap_start, gap_end))
        if in_gap:
            gaps.append((gap_start, bin_edges[-1]))
        return gaps

    def find_resonances(self, spectrum: Dict, target_freq: float = None) -> List[float]:
        """
        Находит резонансные частоты (пики плотности состояний).
        Если задана target_freq, ищет ближайший пик.
        """
        if "frequencies" not in spectrum:
            return []
        freq_data = spectrum["frequencies"]
        all_freqs = []
        for k_freqs in freq_data:
            all_freqs.extend(k_freqs)
        all_freqs = np.array(all_freqs)
        hist, bin_edges = np.histogram(all_freqs, bins=50)
        bin_centers = (bin_edges[:-1] + bin_edges[1:]) / 2
        peaks = []
        for i in range(1, len(hist)-1):
            if hist[i] > hist[i-1] and hist[i] > hist[i+1] and hist[i] > 0.5 * max(hist):
                peaks.append(bin_centers[i])
        if target_freq is not None:
            # Находим ближайший пик к target_freq
            if peaks:
                nearest = min(peaks, key=lambda x: abs(x - target_freq))
                return [nearest]
        return peaks

    # ------------------- 4. Оптимизация структуры под заданное приложение -------------------
    def optimize_crystal(self, application: str = "saser", iterations: int = 10) -> Dict:
        """
        Использует эволюционные механизмы MetaphysicalAI для поиска структуры,
        оптимизированной под заданное приложение:
        - "saser": максимальная фононная щель (для звукового лазера)
        - "ultrasound": равномерный спектр с высокими частотами (для УЗИ)
        - "spectroscopy": наличие дискретных резонансов
        Возвращает лучшую найденную структуру и её спектр.
        """
        # Определяем функцию оценки пригодности (fitness) для приложения
        if application == "saser":
            def fitness(structure):
                spec = self.get_phonon_spectrum(structure["id"])
                gaps = self.find_phononic_gaps(spec)
                if not gaps:
                    return 0.0
                # Максимизируем ширину самой широкой щели
                max_gap = max(g[1] - g[0] for g in gaps)
                return max_gap
        elif application == "ultrasound":
            def fitness(structure):
                spec = self.get_phonon_spectrum(structure["id"])
                if "frequencies" not in spec:
                    return 0.0
                all_freqs = []
                for k_freqs in spec["frequencies"]:
                    all_freqs.extend(k_freqs)
                # Цель: высокие частоты и равномерное распределение
                mean_freq = np.mean(all_freqs)
                std_freq = np.std(all_freqs)
                # Чем выше средняя частота и ниже стандартное отклонение, тем лучше
                return mean_freq / (1 + std_freq)
        elif application == "spectroscopy":
            def fitness(structure):
                spec = self.get_phonon_spectrum(structure["id"])
                resonances = self.find_resonances(spec)
                # Цель: много чётких резонансов
                return len(resonances) / (1 + np.std(resonances) if resonances else 1)
        else:
            return {"error": "Неизвестное приложение"}

        # Генерация начальной популяции структур (разнообразных)
        population = []
        for _ in range(10):
            # Случайный выбор типа
            struct_type = random.choice(["fibonacci", "penrose", "random"])
            if struct_type == "fibonacci":
                length = random.randint(50, 200)
                struct = self.build_crystal("fibonacci", length=length)
            elif struct_type == "penrose":
                size = random.randint(20, 40)
                struct = self.build_crystal("penrose", size=size)
            else:
                size = random.randint(15, 30)
                struct = self.build_crystal("random", size=size)
            population.append(struct)

        # Эволюционный цикл
        best_fitness = -float('inf')
        best_struct = None
        for gen in range(iterations):
            # Оценка
            fitnesses = []
            for struct in population:
                fit = fitness(struct)
                fitnesses.append(fit)
                if fit > best_fitness:
                    best_fitness = fit
                    best_struct = struct
            # Отбор (турнирный)
            new_population = []
            while len(new_population) < len(population):
                idx1 = random.randrange(len(population))
                idx2 = random.randrange(len(population))
                parent1 = population[idx1] if fitnesses[idx1] > fitnesses[idx2] else population[idx2]
                # Второй родитель
                idx3 = random.randrange(len(population))
                idx4 = random.randrange(len(population))
                parent2 = population[idx3] if fitnesses[idx3] > fitnesses[idx4] else population[idx4]
                # Кроссинговер (для структур - смешивание параметров)
                if random.random() < 0.7:
                    # Создаём новую структуру как комбинацию двух
                    if parent1["type"] == "1D_fibonacci" and parent2["type"] == "1D_fibonacci":
                        # Смешиваем последовательности
                        seq1 = self.generate_fibonacci_sequence(len(parent1["types"]))
                        seq2 = self.generate_fibonacci_sequence(len(parent2["types"]))
                        # Берём среднюю длину
                        new_len = min(len(seq1), len(seq2))
                        new_seq = np.where(np.random.rand(new_len) < 0.5, seq1[:new_len], seq2[:new_len])
                        new_struct = {
                            "type": "1D_fibonacci",
                            "positions": np.arange(new_len).tolist(),
                            "types": new_seq.tolist(),
                            "num_atoms": new_len
                        }
                        new_struct["id"] = f"crystal_{hash(str(new_struct))}"
                        new_population.append(new_struct)
                    else:
                        # Для 2D используем мутацию
                        child = parent1.copy()
                        # Мутация: случайное изменение координат (сдвиг)
                        if "coordinates" in child:
                            coords = np.array(child["coordinates"])
                            shift = np.random.randint(-2, 2, size=coords.shape)
                            new_coords = coords + shift
                            # Убираем дубликаты
                            unique_coords = np.unique(new_coords, axis=0)
                            child["coordinates"] = unique_coords.tolist()
                            child["num_atoms"] = len(unique_coords)
                            child["id"] = f"crystal_{hash(str(child))}"
                        new_population.append(child)
                else:
                    # Мутация родителя
                    child = parent1.copy()
                    if child["type"] == "1D_fibonacci":
                        # Мутация: инвертировать некоторые биты
                        types = np.array(child["types"])
                        mask = np.random.rand(len(types)) < 0.05
                        types[mask] = 1 - types[mask]
                        child["types"] = types.tolist()
                        child["id"] = f"crystal_{hash(str(child))}"
                    elif "coordinates" in child:
                        # Добавляем случайный атом
                        coords = np.array(child["coordinates"])
                        new_atom = coords[np.random.randint(len(coords))] + np.random.randint(-1, 2, size=2)
                        new_coords = np.vstack([coords, new_atom])
                        unique_coords = np.unique(new_coords, axis=0)
                        child["coordinates"] = unique_coords.tolist()
                        child["num_atoms"] = len(unique_coords)
                        child["id"] = f"crystal_{hash(str(child))}"
                    new_population.append(child)
            population = new_population

        # Сохраняем лучшую структуру и её спектр
        if best_struct:
            self.session_data["🔊"]["optimized_structures"].append({
                "application": application,
                "best_fitness": best_fitness,
                "structure": best_struct,
                "spectrum": self.get_phonon_spectrum(best_struct["id"])
            })
        return {"best_structure": best_struct, "fitness": best_fitness}

    # ------------------- 5. Генерация кода для синтеза структур -------------------
