# --- CLASS: ECat ---
class ECat(Enum):
    CUR = "current_generation"
    NEXT = "next_generation"
    FUT = "future_concepts"

# --- CLASS: App ---
class App(Enum):
    CIV = "civilian"
    NAVY = "navy"
    DUAL = "dual_use"

# --- CLASS: Eff ---
class Eff:
    thermal: float
    sfc: float          # удельный расход, г/кВт·ч
    pwr_weight: float   # кВт/т
    co2: float

# --- CLASS: Spec ---
class Spec:
    power: List[float]  # [min, max] кВт
    cyl: List[int]
    fuel: str
    disp: float

# --- CLASS: Engine ---
class Engine:
    def __init__(self, eid: str, name: str, cat: ECat, app: App):
        self.id = eid
        self.name = name
        self.cat = cat
        self.app = app
        self.spec: Optional[Spec] = None
        self.eff: Optional[Eff] = None
        self.features: List[str] = []
        self.tech: Dict[str, Any] = {}
        self.created = datetime.now()
        self.updated = datetime.now()

    def set_spec(self, s: Spec): self.spec = s; self._touch()
    def set_eff(self, e: Eff): self.eff = e; self._touch()
    def add_feat(self, f: str): self.features.append(f); self._touch()
    def set_tech(self, k: str, v: Any): self.tech[k] = v; self._touch()
    def _touch(self): self.updated = datetime.now()

    def to_dict(self) -> dict:
        return {
            'id': self.id, 'name': self.name,
            'cat': self.cat.value, 'app': self.app.value,
            'spec': asdict(self.spec) if self.spec else None,
            'eff': asdict(self.eff) if self.eff else None,
            'features': self.features,
            'tech': self.tech,
            'timestamps': {'created': self.created.isoformat(), 'updated': self.updated.isoformat()}
        }

# --- CLASS: DB ---
class DB:
    def __init__(self):
        self.engines: Dict[str, Engine] = {}
        self._cache = {}

    def add(self, eng: Engine):
        if eng.id in self.engines: raise ValueError(f"Engine {eng.id} exists")
        self.engines[eng.id] = eng
        self._cache.clear()

    def get(self, eid: str) -> Optional[Engine]: return self.engines.get(eid)

    def find(self, cat: Optional[ECat] = None, app: Optional[App] = None, min_power: Optional[float] = None) -> List[Engine]:
        res = []
        for e in self.engines.values():
            if cat and e.cat != cat: continue
            if app and e.app != app: continue
            if min_power and e.spec and e.spec.power[0] < min_power: continue
            res.append(e)
        return res

    def iter(self) -> Generator[Engine, None, None]:
        yield from self.engines.values()

    def stats(self) -> dict:
        if 'stats' in self._cache: return self._cache['stats']
        effs = [e.eff.thermal for e in self.engines.values() if e.eff]
        powers = []
        for e in self.engines.values():
            if e.spec: powers.extend(e.spec.power)
        stats = {
            'total': len(self.engines),
            'avg_eff': sum(effs)/len(effs) if effs else 0,
            'max_eff': max(effs) if effs else 0,
            'min_eff': min(effs) if effs else 0,
            'power_min': min(powers) if powers else 0,
            'power_max': max(powers) if powers else 0,
            'power_avg': sum(powers)/len(powers) if powers else 0
        }
        self._cache['stats'] = stats
        return stats

    def export(self, fname: str):
        data = {
            'meta': {'export': datetime.now().isoformat(), 'total': len(self.engines), 'stats': self.stats()},
            'engines': {eid: e.to_dict() for eid, e in self.engines.items()}
        }
        with open(fname, 'w', encoding='utf-8') as f:
            json.dump(data, f, ensure_ascii=False, indent=2)

    @classmethod
    def import_from(cls, fname: str) -> 'DB':
        with open(fname, 'r', encoding='utf-8') as f:
            data = json.load(f)
        db = cls()
        for eid, edata in data['engines'].items():
            cat = ECat(edata['cat'])
            app = App(edata['app'])
            eng = Engine(eid, edata['name'], cat, app)
            if edata['spec']:
                eng.spec = Spec(**edata['spec'])
            if edata['eff']:
                eng.eff = Eff(**edata['eff'])
            eng.features = edata['features']
            eng.tech = edata['tech']
            eng.created = datetime.fromisoformat(edata['timestamps']['created'])
            eng.updated = datetime.fromisoformat(edata['timestamps']['updated'])
            db.add(eng)
        return db

# --- CLASS: Status ---
class Status(Enum): PLANNED='planned'; IN_PROGRESS='in_progress'; ACHIEVED='achieved'; EXPANDING='expanding'

# --- CLASS: Category ---
class Category(Enum): SECURITY='security'; ECONOMY='economy'; POLITICAL='political'; HUMANITARIAN='humanitarian'; INSTITUTIONAL='institutional'

# --- CLASS: SCOAchievement ---
class SCOAchievement:
    title: str; category: Category; status: Status; description: str
    start_year: Optional[int]=None; end_year: Optional[int]=None
    participants: List[str]=None; metrics: Dict[str, Any]=None; tags: List[str]=None
    def __post_init__(self):
        if self.participants is None: self.participants=[]
        if self.metrics is None: self.metrics={}
        if self.tags is None: self.tags=[]

# --- CLASS: SCODataManager ---
class SCODataManager:
    def __init__(self):
        self.achievements: List[SCOAchievement] = []
        self.history: List[Dict] = []
        self._init_base_data()
    def _init_base_data(self):
        base = [
            SCOAchievement("Борьба с терроризмом", Category.SECURITY, Status.ACHIEVED, "РАТС, учения", 2001, metrics={"учения":50}, tags=["безопасность"]),
            SCOAchievement("Расширение", Category.INSTITUTIONAL, Status.EXPANDING, "Индия, Пакистан, Иран", 2017, metrics={"члены":9}, tags=["расширение"]),
            SCOAchievement("Экономическая интеграция", Category.ECONOMY, Status.IN_PROGRESS, "Торговля, инвестиции", 2003, metrics={"товарооборот_млрд":800}, tags=["торговля"]),
            SCOAchievement("Многополярность", Category.POLITICAL, Status.IN_PROGRESS, "Центр силы", 2001, tags=["геополитика"]),
            SCOAchievement("Зона свободной торговли", Category.ECONOMY, Status.PLANNED, "FTA", 2025, tags=["FTA"]),
            SCOAchievement("Беларусь", Category.INSTITUTIONAL, Status.IN_PROGRESS, "Вступление", 2024, tags=["расширение"])
        ]
        self.achievements = base
        self._log_change("init", "Base data loaded")
    def add(self, a): self.achievements.append(a); self._log_change("add", a.title)
    def update(self, idx, **kw):
        if 0 <= idx < len(self.achievements):
            for k,v in kw.items():
                if hasattr(self.achievements[idx], k): setattr(self.achievements[idx], k, v)
            self._log_change("update", self.achievements[idx].title)
    def filter_cat(self, cat): return [a for a in self.achievements if a.category==cat]
    def filter_status(self, st): return [a for a in self.achievements if a.status==st]
    def filter_tag(self, tag): return [a for a in self.achievements if tag in a.tags]
    def timeline(self):
        tl={}
        for a in self.achievements:
            if a.start_year:
                tl.setdefault(a.start_year, []).append(a)
        return tl
    def summary(self):
        from collections import Counter
        cats=Counter(a.category for a in self.achievements)
        sts=Counter(a.status for a in self.achievements)
        print("=== SCO SUMMARY ===")
        print(f"Всего: {len(self.achievements)}")
        print("По категориям:", dict(cats))
        print("По статусам:", dict(sts))
    def _log_change(self, act, det):
        self.history.append({'ts': datetime.now().isoformat(), 'action': act, 'details': det})
    def export(self, fname=None):
        data={'achievements':[asdict(a) for a in self.achievements], 'history':self.history}
        js=json.dumps(data, ensure_ascii=False, indent=2, default=str)
        if fname: open(fname,'w',encoding='utf-8').write(js)
        return js
    def import_json(self, fname):
        with open(fname,'r',encoding='utf-8') as f: data=json.load(f)
        self.achievements=[]
        for ad in data['achievements']:
            ad['category']=Category(ad['category']); ad['status']=Status(ad['status'])
            self.achievements.append(SCOAchievement(**ad))
        self.history=data.get('history',[])
        self._log_change("import", fname)

