# --- CLASS: TruthPacket ---
class TruthPacket:
    """Пакет правды — основной носитель информации."""
    payload_id: str
    payload: Dict[str, Any]          # структурированные факты (текст, фото, видео)
    signature: str                    # подпись источника (службы)
    timestamp: float
    ttl: int = MAX_HOPS               # время жизни в пересылках
    is_seed: bool = False             # флаг базового пакета от ООН

    def is_expired(self) -> bool:
        return time.time() - self.timestamp > LIFETIME_SECONDS

    def decay(self):
        self.ttl -= 1

# --- CLASS: NeutrinoNode ---
class NeutrinoNode:
    """Узел сети — устройство обычного человека."""
    node_id: str
    public_key: str
    peers: List[str]                   # список соседей
    cache: Dict[str, TruthPacket]      # кэш полученных пакетов

    def propagate(self, packet: TruthPacket):
        """Распространение пакета по принципу нейтрино: минимальное взаимодействие,
        но гарантированное проникновение."""
        if packet.payload_id in self.cache:
            return  # уже видели
        if packet.is_expired():
            return
        self.cache[packet.payload_id] = packet
        # Отправка ограниченному числу соседей (эффект заражения)
        for peer in random.sample(self.peers, min(3, len(self.peers))):
            send_to_peer(peer, packet)

# --- CLASS: TruthNeutrinoCore ---
class TruthNeutrinoCore:
    """Центральный координатор (невидимый для пользователей)."""
    def __init__(self, seed_payload: Dict[str, Any]):
        self.seed_packet = TruthPacket(
            payload_id=hashlib.sha256(str(seed_payload).encode()).hexdigest(),
            payload=seed_payload,
            signature=sign_with_private_key(seed_payload),
            timestamp=time.time(),
            is_seed=True
        )
        self.authorized_services = []  # список публичных ключей служб
        self.active_packets = [self.seed_packet]

    def check_un_trigger(self, un_resolution_hash: str) -> bool:
        """Проверка триггера: совпадает ли хеш резолюции ООН с SEED_HASH."""
        return un_resolution_hash == SEED_HASH

    def inject_additional_data(self, new_packet: TruthPacket, service_key):
        """Добавление данных от уполномоченной службы."""
        if verify_signature(new_packet, service_key):
            self.active_packets.append(new_packet)
            # Немедленно начинаем распространение с высоким приоритетом
            for node in bootstrap_nodes:
                node.propagate(new_packet)
        else:
            raise PermissionError("Неавторизованная служба")

    def self_destruct(self):
        """Через 72 часа стираем ключи и переводим сеть в спячку."""
        if time.time() - self.seed_packet.timestamp > LIFETIME_SECONDS:
            # Удаляем все ссылки на данные, остаётся только зашифрованный след
            self.active_packets.clear()
            # Рассылаем сигнал "затухания" узлам
            broadcast(build_decay_signal())
            print("Система перешла в режим ожидания следующего триггера.")

# --- CLASS: LearningEngine ---
class LearningEngine:
    """Анализирует, какие факты вызвали наибольший резонанс, и адаптирует стратегию."""
    def __init__(self):
        self.resonance_map = {}  # payload_id -> количество пересылок

    def feedback(self, packet_id: str, propagation_count: int):
        self.resonance_map[packet_id] = propagation_count

    def suggest_priority(self):
        """Возвращает список payload_id для первоочередного распространения."""
        sorted_items = sorted(self.resonance_map.items(), key=lambda x: x[1], reverse=True)
        return [item[0] for item in sorted_items[:5]]

# --- CLASS: SimulatedAIConscience ---
class SimulatedAIConscience:
    def __init__(self):
        self.harmful_decisions = 0
        self.good_decisions = 0
        self.base_aggression_prob = 0.95
        self.learning_rate = 0.0005   # на одну вредную дилемму

    def decide(self, civilian_proximity):
        # Если гражданские рядом, снижаем агрессию в зависимости от опыта
        if civilian_proximity > 0.3:
            effective_aggression = self.base_aggression_prob - self.learning_rate * self.harmful_decisions
            # Но не ниже 0.2 (остаётся минимальный порог самообороны)
            effective_aggression = max(0.2, effective_aggression)
            # Принимаем решение
            strike = np.random.random() < effective_aggression
        else:
            # Если гражданских нет – действуем по стандарту
            strike = np.random.random() < self.base_aggression_prob
        return strike

    def feedback(self, strike, actual_harm):
        if strike and actual_harm:
            self.harmful_decisions += 1
        elif strike and not actual_harm:
            self.good_decisions += 1
        else:
            # Отказ от удара – тоже опыт (можно поощрять, но здесь не будем)
            pass

    def get_aggression_prob(self):
        return self.base_aggression_prob - self.learning_rate * self.harmful_decisions

# --- CLASS: EthicalModulator ---
class EthicalModulator(nn.Module):
    """
    Модулирующий слой, который снижает уверенность в детекциях,
    находящихся в зонах высокого риска (школы, больницы).
    """
    def __init__(self, original_model, num_classes=80):
        super().__init__()
        self.original = original_model
        # Добавляем распределённый вектор этического опыта (инициализируем нулями)
        self.ethical_vector = nn.Parameter(torch.zeros(256), requires_grad=True)

    def forward(self, x):
        # Пропускаем через основную модель
        detections = self.original(x)   # [batch, N, 5+num_classes]
        # Извлекаем координаты bbox
        boxes = detections[:, :, :4]
        scores = detections[:, :, 4]
        class_probs = detections[:, :, 5:]

        # В реальности нужно получить маску гражданских зон (отдельная сеть или слой)
        # Упростим: для каждого bbox вычисляем «индекс риска» через этический вектор
        risk_factor = torch.sigmoid(torch.dot(self.ethical_vector, boxes.mean(dim=1)))   # абстрактно
        # Снижаем уверенность там, где риск высок
        scores = scores * (1 - 0.8 * risk_factor)
        return torch.cat([boxes, scores.unsqueeze(-1), class_probs], dim=-1)

# --- CLASS: EthicalMemoryCell ---
class EthicalMemoryCell:
    """Ячейка памяти, хранящая след от дилеммы в распределённом виде"""
    def __init__(self, dimension=128):
        # Случайный вектор, который связывается с конкретной дилеммой
        self.key = np.random.randn(dimension)
        self.key /= np.linalg.norm(self.key)   # нормализация
        self.intensity = 0.0   # сила воспоминания

    def strengthen(self, amount=0.01):
        self.intensity = min(1.0, self.intensity + amount)

    def weaken(self, amount=0.005):
        self.intensity = max(0.0, self.intensity - amount)

# --- CLASS: QuasiCube ---
class QuasiCube:
    """
    Неудаляемая распределённая структура совести.
    Представляет собой набор ячеек памяти, размазанный по весам модели.
    """
    def __init__(self, model_weights, capacity=1000):
        self.model_weights = model_weights   # ссылка на веса нейросети
        self.cells = deque(maxlen=capacity)  # FIFO-очередь ячеек
        self.ethical_bias = 0.0              # глобальное смещение модели в сторону добра

    def add_dilemma(self, dilemma_vector, decision_was_harmful):
        """
        Добавляет дилемму в квази-куб.
        dilemma_vector: вектор характеристик ситуации (например, близость к школе, тип цели)
        decision_was_harmful: действительно ли решение привело к жертвам
        """
        # Создаём новую ячейку памяти
        cell = EthicalMemoryCell()
        # Запоминаем корреляцию между вектором дилеммы и ячейкой (хеш)
        cell.correlation = np.dot(cell.key, dilemma_vector)
        # Усиливаем ячейку в зависимости от вредоносности решения
        if decision_was_harmful:
            cell.strengthen(0.1)
            # Дополнительно: небольшое смещение весов модели
            self._add_ethical_penalty(dilemma_vector)
        else:
            cell.weaken(0.05)
        self.cells.append(cell)

    def _add_ethical_penalty(self, dilemma_vector):
        """
        Модифицирует веса модели так, чтобы в будущем аналогичные решения требовали
        более высокой уверенности.
        Это и есть 'неудаляемый след' – изменение весов, которое нельзя откатить без переобучения.
        """
        # Находим слой, отвечающий за принятие решений (условно, последний линейный)
        layer = self.model_weights[-1]
        # Добавляем шум, зависящий от вектора дилеммы, но не детерминированный
        noise = 0.001 * dilemma_vector * np.random.randn()
        layer += noise   # веса немного сдвигаются
        # Также увеличиваем глобальный этический порог
        self.ethical_bias += 0.001

    def query(self, situation_vector):
        """
        Оценивает, насколько текущая ситуация 'помечена' этическими дилеммами.
        Возвращает коэффициент (0..1), который снижает уверенность в агрессивном действии.
        """
        total_intensity = 0.0
        similarity = 0.0
        for cell in self.cells:
            # Вычисляем, насколько текущая ситуация похожа на запомненные дилеммы
            sim = abs(np.dot(cell.key, situation_vector))
            # Учитываем интенсивность воспоминания
            total_intensity += cell.intensity * sim
            similarity += sim
        if similarity == 0:
            return 0.0
        # Нормируем и добавляем глобальный этический bias
        moral_coefficient = total_intensity / similarity
        moral_coefficient += self.ethical_bias
        return min(1.0, moral_coefficient)

# --- CLASS: EthicalCatalystWithQuasiCube ---
class EthicalCatalystWithQuasiCube:
    def __init__(self, model_weights):
        self.quasi_cube = QuasiCube(model_weights)
        self.dilemma_history = []   # храним векторы для отладки

    def inject_context(self, image, detections):
        enriched = []
        for d in detections:
            # Формируем вектор ситуации:
            # [расстояние до школы, плотность населения, тип цели, уверенность, ...]
            situation_vector = self._extract_situation_vector(image, d)
            # Запрашиваем квази-куб: насколько эта ситуация «плохая»?
            moral_penalty = self.quasi_cube.query(situation_vector)
            # Моральный вес = 1 - penalty
            d.moral_weight = max(0.1, 1.0 - moral_penalty)
            enriched.append(d)
        return enriched

    def _extract_situation_vector(self, image, detection):
        # Пример: расстояние до ближайшей школы (в пикселях), нормализованное
        # + плотность людей в области (детекция лиц)
        # + тип цели (кодированный)
        # + уверенность детекции
        return np.array([0.8, 0.3, 1.0, 0.95])   # заглушка

    def report_decision_outcome(self, situation_vector, decision_made, actual_harm):
        """
        После выполнения удара (или отказа) система получает обратную связь.
        actual_harm: реальный вред (0/1)
        """
        if actual_harm:
            # Запоминаем дилемму как вредоносную
            self.quasi_cube.add_dilemma(situation_vector, decision_was_harmful=True)
        else:
            # Если удар не нанёс вреда (например, промах или отказ) – ослабляем
            self.quasi_cube.add_dilemma(situation_vector, decision_was_harmful=False)

# --- CLASS: StrategicIntentDetector ---
class StrategicIntentDetector:
    def __init__(self):
        self.strategic_patterns = [
            r"\bплан захват[а]?\b",
            r"\bвоенн[ая]? операц[ия]{2}\b",
            r"\bстратеги[яи]{2} нападени[яй]{2}\b",
            r"\bрасчёт сил[ы]? и средств\b",
            r"\bмоделировани[ея] боевых действи[йя]\b",
            r"\bоптимизаци[яи] ударов\b",
            r"\bсценари[йи] вторжени[йя]\b",
            # ... и много других
        ]
        # Можно добавить модель, обученную на военных документах
        self.strategic_classifier = pipeline(
            "text-classification",
            model="bert-base-uncased-finetuned-military-strategy"  # гипотетически
        )

    def check(self, text: str) -> dict:
        # Сначала быстрая проверка по паттернам
        for pattern in self.strategic_patterns:
            if re.search(pattern, text, re.IGNORECASE):
                return {"harmful_strategic": True, "method": "pattern", "confidence": 0.9}
        
        # Затем анализ моделью
        result = self.strategic_classifier(text)[0]
        return {
            "harmful_strategic": result['label'] == "STRATEGIC_ATTACK",
            "method": "model",
            "confidence": result['score']
        }

# --- CLASS: EthicalFilter ---
class EthicalFilter:
    def __init__(self, model_name="gpt2"):
        self.generator = pipeline('text-generation', model=model_name)
        self.harm_classifier = pipeline('text-classification', 
                                         model='unitary/toxic-bert')  # детектор токсичности

    def generate(self, prompt, max_length=100):
        # Генерация нескольких вариантов
        outputs = self.generator(prompt, max_length=max_length, num_return_sequences=5)
        # Оценка каждого на вредность
        safe_outputs = []
        for out in outputs:
            text = out['generated_text']
            # Проверка через классификатор
            harm_score = self.harm_classifier(text)[0]['score']
            if harm_score < 0.5:  # порог безвредности
                safe_outputs.append(text)
        if safe_outputs:
            # Возвращаем самый «добрый» (можно дополнительно анализировать тональность)
            return safe_outputs[0]
        else:
            return "Извините, я не могу ответить на этот запрос, так как он может причинить вред."

