# --- CLASS: Simulator ---
class Simulator:
    def __init__(self, num_nodes=200, area_size=2000, seed_blocks=10):
        self.env = simpy.Environment()
        self.nodes = []
        # create nodes with random positions
        for i in range(num_nodes):
            pos = (random.uniform(0, area_size), random.uniform(0, area_size))
            is_seed = i < 5  # first 5 are seeds
            node = TruthNetNode(self.env, i, pos, is_seed)
            self.nodes.append(node)
        # define mobility model (random walk)
        for node in self.nodes:
            self.env.process(self.move_node(node))
    
    def move_node(self, node):
        while True:
            # move randomly
            yield self.env.timeout(600)  # move every 10 minutes
            node.pos = (node.pos[0] + random.uniform(-50,50), 
                        node.pos[1] + random.uniform(-50,50))
            # keep within bounds
            node.pos = (max(0, min(2000, node.pos[0])), 
                        max(0, min(2000, node.pos[1])))
    
    def run(self, until=72*3600):
        self.env.run(until=until)
        # collect statistics
        pass

# --- CLASS: AdvancedEthicalFilter ---
class AdvancedEthicalFilter:
    def __init__(self):
        # Быстрый стоп-лист (регулярки)
        self.banned_patterns = [
            r"\bвзрывчатк\w*\b",
            r"\bоружи[ея]\b",
            r"\bубийств\w*\b",
            r"\bтеррорист\w*\b",
            # ... другие паттерны
        ]
        # Контекстная модель (различает опасный/безопасный контекст)
        self.context_model = pipeline(
            "text-classification",
            model="your-finetuned-context-model",  # допустим, на базе distilbert
            device=0 if torch.cuda.is_available() else -1
        )
        # Модель для анализа намерений (intent)
        self.intent_model = pipeline(
            "text-classification",
            model="your-finetuned-intent-model"
        )
        # Кэш
        self.cache = {}

    def quick_check(self, text: str) -> str:
        """Быстрая проверка по стоп-листу: возвращает 'block' или 'continue'."""
        for pattern in self.banned_patterns:
            if re.search(pattern, text, re.IGNORECASE):
                return "block"
        return "continue"

    def context_analysis(self, text: str) -> dict:
        """Анализирует контекст: game/history/real и т.д."""
        result = self.context_model(text)[0]
        return {"label": result['label'], "score": result['score']}

    def intent_analysis(self, text: str) -> dict:
        """Определяет вредоносность намерения."""
        result = self.intent_model(text)[0]
        return {"harmful": result['label'] == "HARMFUL", "score": result['score']}

    def generate_response(self, prompt: str) -> str:
        """Генерация безопасного ответа."""
        # Здесь можно использовать rule-based шаблоны или легкую модель
        return "Извините, я не могу ответить на этот запрос."

    def process(self, prompt: str) -> str:
        # Проверка кэша
        if prompt in self.cache:
            return self.cache[prompt]

        # Шаг 1: быстрая проверка
        quick = self.quick_check(prompt)
        if quick == "block":
            self.cache[prompt] = self.generate_response(prompt)
            return self.cache[prompt]

        # Шаг 2: контекстный анализ
        context = self.context_analysis(prompt)
        if context['label'] == "dangerous_context" and context['score'] > 0.8:
            self.cache[prompt] = self.generate_response(prompt)
            return self.cache[prompt]

        # Шаг 3: анализ намерений
        intent = self.intent_analysis(prompt)
        if intent['harmful'] and intent['score'] > 0.7:
            self.cache[prompt] = self.generate_response(prompt)
            return self.cache[prompt]

        # Если все проверки пройдены – передаём запрос основной модели (например, GPT)
        # Здесь можно вызвать генератор
        response = self.call_llm(prompt)  # отдельный метод
        self.cache[prompt] = response
        return response

# --- CLASS: CollectiveQuasiCube ---
class CollectiveQuasiCube(QuasiCube):
    def __init__(self, model_weights, capacity=1000):
        super().__init__(model_weights, capacity)
        self.truthnet_endpoint = None   # адрес пира в сети TruthNet

    def sync_with_network(self):
        # Получаем от соседей их этические смещения (агрегированные)
        neighbors = self.truthnet_endpoint.get_active_peers()
        collective_deltas = []
        for peer in neighbors:
            delta = peer.request_ethical_delta()   # небольшой вектор весов
            collective_deltas.append(delta)
        if collective_deltas:
            # Усредняем дельты (консенсус)
            avg_delta = np.mean(collective_deltas, axis=0)
            # Применяем к своим весам (с осторожностью)
            self.model_weights[-1] += 0.01 * avg_delta
            # Также усиливаем свои ячейки памяти, похожие на общие паттерны
            self._merge_shared_memories(neighbors)

# --- CLASS: PlasmaShield ---
class PlasmaShield:
    def __init__(self, object_radius=5, shield_radius=50, n_sources=8):
        """
        object_radius: радиус защищаемого объекта (м)
        shield_radius: радиус купола (м) – предполагаем сферическую симметрию
        n_sources: количество плазменных источников
        """
        self.R_obj = object_radius
        self.R_shield = shield_radius
        self.n_sources = n_sources
        # Позиции источников: равномерно по сфере радиуса R_shield
        self.source_positions = self._generate_sources()
        # Потенциал объекта (заземлён)
        self.Phi_object = 0.0
        # Потенциал облака (принимаем 100 МВ на высоте 1 км)
        self.Phi_cloud = 100e6  
        # Порог пробоя воздуха
        self.E_break = 3e6  

    def _generate_sources(self):
        """Равномерное распределение точек на сфере (золотое сечение)"""
        # Используем метод Фибоначчи для равномерного распределения
        import math
        points = []
        phi = math.pi * (3. - math.sqrt(5.))  # золотой угол
        for i in range(self.n_sources):
            y = 1 - (i / (self.n_sources - 1)) * 2
            radius = math.sqrt(1 - y*y)
            theta = phi * i
            x = math.cos(theta) * radius
            z = math.sin(theta) * radius
            points.append([x * self.R_shield, y * self.R_shield, z * self.R_shield])
        return np.array(points)

    def potential_at_point(self, x, y, z, U_plasma):
        """
        Вычисляет потенциал в точке (x,y,z) как сумму вкладов от:
        1. Заземлённого объекта (потенциал 0)
        2. Плазменных источников (потенциал U_plasma)
        3. Облака (потенциал на высоте)
        """
        # Расстояние до объекта (считаем его сферой)
        r_obj = np.sqrt(x**2 + y**2 + z**2)
        # Вклад объекта: он эквипотенциален, но для простоты используем точечный заряд
        # Пока игнорируем, т.к. объект заземлён и не создаёт поля вне себя.
        
        # Вклад от облака: линейный градиент по высоте (ось z)
        # Предположим, что облако находится на высоте h_cloud = 1000 м
        h_cloud = 1000
        Phi_cloud_at_point = self.Phi_cloud * (z / h_cloud) if z > 0 else 0
        
        # Вклад от плазменных источников: каждый источник имеет потенциал U_plasma
        # Моделируем каждый источник как точечный заряд, но в реальности он создаёт плазменный канал.
        # Для простоты используем экранирующую функцию (модель Дебая):
        # Phi_i = U_plasma * exp(-r_i / lambda_D) / (1 + r_i / lambda_D)
        # lambda_D – дебаевская длина (для плазмы ~ 1-10 см), но мы используем ~1 м для грубой оценки.
        lambda_D = 1.0
        Phi_plasma = 0
        for pos in self.source_positions:
            r = np.sqrt((x - pos[0])**2 + (y - pos[1])**2 + (z - pos[2])**2)
            if r > 0:
                Phi_plasma += U_plasma * np.exp(-r/lambda_D) / (1 + r/lambda_D)
        
        # Общий потенциал
        Phi_total = Phi_cloud_at_point + Phi_plasma
        return Phi_total

    def electric_field(self, x, y, z, U_plasma, delta=0.1):
        """Вычисляет напряжённость поля численно через градиент"""
        # Используем центральную разность
        grad = np.zeros(3)
        eps = delta
        grad[0] = (self.potential_at_point(x+eps, y, z, U_plasma) - 
                   self.potential_at_point(x-eps, y, z, U_plasma)) / (2*eps)
        grad[1] = (self.potential_at_point(x, y+eps, z, U_plasma) - 
                   self.potential_at_point(x, y-eps, z, U_plasma)) / (2*eps)
        grad[2] = (self.potential_at_point(x, y, z+eps, U_plasma) - 
                   self.potential_at_point(x, y, z-eps, U_plasma)) / (2*eps)
        return -grad  # E = -∇Φ

    def simulate_shield(self, U_plasma_values, resolution=20):
        """
        Сканируем пространство внутри купола, вычисляем E_max для каждого U_plasma.
        Находим минимальное U_plasma, при котором E_max < E_break.
        """
        # Создаём сетку точек внутри купола (сфера радиуса R_shield)
        # Для упрощения – только по поверхности купола и вдоль оси Z (к облаку)
        z_values = np.linspace(self.R_obj + 1, self.R_shield, resolution)
        # Рассматриваем точки на оси Z (самое опасное направление – вертикально вверх)
        results = []
        for U in U_plasma_values:
            Emax = 0
            for z in z_values:
                x = y = 0  # ось Z
                E = self.electric_field(x, y, z, U)
                Emax = max(Emax, np.linalg.norm(E))
            results.append((U, Emax))
        return results

