# --- CLASS: LightningHarvester ---
class LightningHarvester:
    def __init__(self):
        # Молния как источник тока
        self.I_peak = 30000  # А
        self.tau = 50e-6     # длительность фронта
        # Резонансный контур
        self.L = 1e-6        # Гн
        self.C = 25e-9       # Ф
        self.R_loss = 0.01   # Ом (потери)
        # Накопитель
        self.L_smes = 10     # Гн
        self.R_smes = 1e-6   # Сверхпроводящее состояние
        
    def lightning_current(self, t):
        # Аппроксимация разряда: двусторонняя экспонента
        return self.I_peak * (np.exp(-t/self.tau) - np.exp(-t/(self.tau/5)))
    
    def circuit_equations(self, state, t, I_source):
        # state = [I_L, U_C, I_smes]
        I_L, U_C, I_smes = state
        dI_L = (I_source - I_L - U_C/self.R_loss) / self.L
        dU_C = (I_L - I_smes) / self.C
        dI_smes = U_C / self.L_smes
        return [dI_L, dU_C, dI_smes]
    
    def simulate(self, t_max=200e-6, dt=1e-9):
        t = np.arange(0, t_max, dt)
        I_source = self.lightning_current(t)
        # Начальные условия
        state0 = [0, 0, 0]
        sol = odeint(self.circuit_equations, state0, t, args=(I_source,))
        I_L, U_C, I_smes = sol.T
        # Энергия в SMES
        E_smes = 0.5 * self.L_smes * I_smes**2
        return t, I_source, I_L, U_C, I_smes, E_smes

