# --- CLASS: DataManager ---
class DataManager:
    """
    Менеджер для работы с структурированными данными, функциями обновления и экспорта.
    Аналог оригинального EmojiDataManager без использования эмодзи.
    """
    
    def __init__(self) -> None:
        # Инициализация структур данных с понятными names вместо эмодзи
        self.keys: Dict[str, Any] = {}          # Секретные ключи и метаинформация (🔑)
        self.storage: Dict[str, Any] = {}       # Основные хранимые данные (🗃️)
        self.update_functions: Dict[str, Callable] = {}  # Функции обновления (🔄)
        self.export_functions: Dict[str, Callable] = {}  # Функции экспорта (🚀)

    def update_data(self, 
                   target: str, 
                   key: str, 
                   new_data: Any, 
                   deep_merge: bool = False) -> None:
        """
        Обновляет данные в указанном хранилище.
        
        Args:
            target: Целевое хранилище ('keys' или 'storage')
            key: Ключ для обновления
            new_data: Новые данные
            deep_merge: Флаг глубокого слияния словарей
        """
        storage_map = {
            'keys': self.keys,
            'storage': self.storage
        }
        
        if target not in storage_map:
            raise ValueError(f"Неизвестное хранилище: {target}")
            
        current_data = storage_map[target]
        
        if deep_merge and isinstance(current_data.get(key), dict) and isinstance(new_data, dict):
            # Реализация глубокого слияния словарей
            self._deep_merge(current_data[key], new_data)
        else:
            current_data[key] = new_data

    def _deep_merge(self, base_dict: Dict, update_dict: Dict) -> None:
        """Рекурсивное глубокое слияние словарей"""
        for key, value in update_dict.items():
            if (key in base_dict and 
                isinstance(base_dict[key], dict) and 
                isinstance(value, dict)):
                self._deep_merge(base_dict[key], value)
            else:
                base_dict[key] = value

    def register_function(self, 
                         func_type: str, 
                         name: str, 
                         func: Callable) -> None:
        """
        Регистрирует функцию для последующего использования.
        
        Args:
            func_type: Тип функции ('update' или 'export')
            name: Имя функции
            func: Callable-объект
        """
        function_registry = {
            'update': self.update_functions,
            'export': self.export_functions
        }
        
        if func_type not in function_registry:
            raise ValueError(f"Неизвестный тип функции: {func_type}")
            
        function_registry[func_type][name] = func

    def execute_function(self, 
                        func_type: str, 
                        name: str, 
                        *args, **kwargs) -> Any:
        """
        Выполняет зарегистрированную функцию.
        
        Args:
            func_type: Тип функции ('update' или 'export')
            name: Имя функции
            *args: Аргументы функции
            **kwargs: Ключевые аргументы функции
            
        Returns:
            Результат выполнения функции
        """
        function_registry = {
            'update': self.update_functions,
            'export': self.export_functions
        }
        
        if func_type not in function_registry:
            raise ValueError(f"Неизвестный тип функции: {func_type}")
            
        func = function_registry[func_type].get(name)
        if not func or not callable(func):
            raise ValueError(f"Функция {name} не найдена или не вызываема")
            
        return func(*args, **kwargs)

    def export_to_json(self, 
                      filepath: str, 
                      include_keys: bool = True,
                      include_storage: bool = True) -> None:
        """
        Экспортирует данные в JSON-файл.
        
        Args:
            filepath: Путь к файлу для экспорта
            include_keys: Включать ли ключи в экспорт
            include_storage: Включать ли данные хранилища
        """
        export_data = {}
        
        if include_keys:
            export_data['keys'] = self.keys
            
        if include_storage:
            export_data['storage'] = self.storage
            
        with open(filepath, 'w', encoding='utf-8') as f:
            json.dump(export_data, f, ensure_ascii=False, indent=4)

