# --- CLASS: PlasmaStabilityReport ---
class PlasmaStabilityReport:
    """
    Класс для хранения и анализа данных об устойчивости плазменной системы.
    Поддерживает добавление новых данных, вычисление метрик и экспорт результатов.
    """
    
    def __init__(self, initial_data: Optional[List[Dict]] = None):
        """
        Инициализация системы мониторинга устойчивости плазмы.
        
        Parameters:
            initial_data: Начальные данные в формате списка словарей
        """
        self.data = pd.DataFrame(columns=[
            'timestamp', 'theoretical_efficiency', 'actual_efficiency',
            'turbulence_suppression', 'energy_efficiency', 
            'plasma_retention_time', 'alpha', 'beta', 'gamma', 
            'tau', 'lambda_0', 'xi', 'notes'
        ])
        
        if initial_data:
            self.add_multiple_entries(initial_data)
    
    def add_entry(self, 
                 theoretical_efficiency: float,
                 actual_efficiency: float,
                 turbulence_suppression: float,
                 energy_efficiency: float,
                 plasma_retention_time: float,
                 alpha: float = 2.0,
                 beta: float = 1.0,
                 gamma: float = 7.0,
                 tau: float = 1.0,
                 lambda_0: float = 0.5527,
                 xi: float = 1.2,
                 notes: str = "") -> None:
        """
        Добавление новой записи в систему мониторинга.
        
        Parameters:
            theoretical_efficiency: Теоретическая эффективность (%)
            actual_efficiency: Фактическая эффективность (%)
            turbulence_suppression: Подавление турбулентности (%)
            energy_efficiency: Энергоэффективность (%)
            plasma_retention_time: Время удержания плазмы (мс)
            alpha: Параметр адаптивности (по умолчанию 2.0)
            beta: Параметр единства (по умолчанию 1.0)
            gamma: Параметр глубины (по умолчанию 7.0)
            tau: Временная стабильность (по умолчанию 1.0)
            lambda_0: Базовый инвариант (по умолчанию 0.5527)
            xi: Коэффициент вихревого усиления (по умолчанию 1.2)
            notes: Произвольные заметки
        """
        new_entry = {
            'timestamp': datetime.now(),
            'theoretical_efficiency': theoretical_efficiency,
            'actual_efficiency': actual_efficiency,
            'turbulence_suppression': turbulence_suppression,
            'energy_efficiency': energy_efficiency,
            'plasma_retention_time': plasma_retention_time,
            'alpha': alpha,
            'beta': beta,
            'gamma': gamma,
            'tau': tau,
            'lambda_0': lambda_0,
            'xi': xi,
            'notes': notes
        }
        
        self.data = pd.concat([self.data, pd.DataFrame([new_entry])], 
                             ignore_index=True)
    
    def add_multiple_entries(self, entries: List[Dict]) -> None:
        """
        Добавление нескольких записей одновременно.
        
        Parameters:
            entries: Список словарей с данными записей
        """
        for entry in entries:
            self.add_entry(**entry)
    
    def calculate_metrics(self) -> Dict[str, float]:
        """
        Вычисление основных метрик системы.
        
        Returns:
            Словарь с вычисленными метриками
        """
        if self.data.empty:
            return {}
        
        latest = self.data.iloc[-1]
        
        metrics = {
            'efficiency_gap': latest['theoretical_efficiency'] - latest['actual_efficiency'],
            'stability_score': np.mean([
                latest['actual_efficiency'] / 100,
                latest['turbulence_suppression'] / 100,
                latest['energy_efficiency'] / 100
            ]),
            'composite_parameter': (latest['alpha'] * latest['gamma'] * latest['tau']) / 
                                  (latest['beta'] * latest['lambda_0']),
            'retention_quality': latest['plasma_retention_time'] * latest['actual_efficiency'] / 100
        }
        
        return metrics
    
    def get_time_series(self, column: str) -> pd.Series:
        """
        Получение временного ряда для указанного столбца.
        
        Parameters:
            column: Название столбца
            
        Returns:
            Pandas Series с временным рядом
        """
        return self.data.set_index('timestamp')[column]
    
    def plot_metrics(self, save_path: Optional[str] = None) -> None:
        """
        Построение графиков основных метрик.
        
        Parameters:
            save_path: Путь для сохранения графиков (если None - отображает)
        """
        if self.data.empty:
            print("Нет данных для визуализации")
            return
        
        fig, ((ax1, ax2), (ax3, ax4)) = plt.subplots(2, 2, figsize=(15, 10))
        
        # График эффективности
        self.data.plot(x='timestamp', y=['theoretical_efficiency', 'actual_efficiency'], 
                      ax=ax1, title='Эффективность системы')
        ax1.set_ylabel('Проценты')
        ax1.legend(['Теоретическая', 'Фактическая'])
        
        # График подавления турбулентности и энергоэффективности
        self.data.plot(x='timestamp', y=['turbulence_suppression', 'energy_efficiency'], 
                      ax=ax2, title='Подавление турбулентности и энергоэффективность')
        ax2.set_ylabel('Проценты')
        ax2.legend(['Подавление турбулентности', 'Энергоэффективность'])
        
        # График времени удержания плазмы
        self.data.plot(x='timestamp', y='plasma_retention_time', 
                      ax=ax3, title='Время удержания плазмы')
        ax3.set_ylabel('Миллисекунды')
        
        # График параметров системы
        self.data.plot(x='timestamp', y=['alpha', 'beta', 'gamma', 'tau'], 
                      ax=ax4, title='Параметры системы')
        ax4.set_ylabel('Значения')
        ax4.legend(['α', 'β', 'γ', 'τ'])
        
        plt.tight_layout()
        
        if save_path:
            plt.savefig(save_path)
            plt.close()
        else:
            plt.show()
    
    def export_to_csv(self, filepath: str) -> None:
        """
        Экспорт данных в CSV файл.
        
        Parameters:
            filepath: Путь для сохранения файла
        """
        self.data.to_csv(filepath, index=False, encoding='utf-8')
    
    def import_from_csv(self, filepath: str) -> None:
        """
        Импорт данных из CSV файла.
        
        Parameters:
            filepath: Путь к файлу с данными
        """
        new_data = pd.read_csv(filepath)
        new_data['timestamp'] = pd.to_datetime(new_data['timestamp'])
        self.data = pd.concat([self.data, new_data], ignore_index=True)
    
    def get_latest_entry(self) -> Dict:
        """
        Получение последней записи.
        
        Returns:
            Словарь с последней записью
        """
        if self.data.empty:
            return {}
        return self.data.iloc[-1].to_dict()
    
    def optimize_parameters(self) -> Dict[str, float]:
        """
        Оптимизация параметров системы на основе исторических данных.
        
        Returns:
            Словарь с оптимизированными параметрами
        """
        if len(self.data) < 2:
            return {
                'alpha': 2.0,
                'beta': 1.0,
                'gamma': 7.0,
                'tau': 1.0,
                'lambda_0': 0.5527,
                'xi': 1.2
            }
        
        # Простая оптимизация - усреднение лучших значений
        best_idx = self.data['actual_efficiency'].idxmax()
        best_entry = self.data.iloc[best_idx]
        
        # Более сложная оптимизация может быть реализована здесь
        optimized = {
            'alpha': min(2.5, max(1.5, best_entry['alpha'] * 1.05)),
            'beta': min(1.2, max(0.8, best_entry['beta'] * 0.95)),
            'gamma': min(8.0, max(6.0, best_entry['gamma'])),
            'tau': min(1.2, max(0.8, best_entry['tau'])),
            'lambda_0': best_entry['lambda_0'],
            'xi': min(1.5, max(1.0, best_entry['xi'] * 1.1))
        }
        
        return optimized

