# --- CLASS: PlasmaControlSystem ---
class PlasmaControlSystem:
    """Интегрированная система управления плазмой, объединяющая все наши наработки"""
    
    def __init__(self):
        self.parameters = {
            'alpha': ALPHA, 'beta': BETA, 'gamma': GAMMA, 
            'tau': TAU, 'lambda_0': LAMBDA_0
        }
        self.stability_history = []
        self.xi_history = []
        self.harmonic_level = 11  # Из анализа иконки
        self.trinity_factor = 3   # Из анализа иконки
        
    def calculate_invariant(self, t, xi=1.0):
        """Расчёт инварианта устойчивости с учётом параметра ξ"""
        base = (LIGHT_WAVE * SOUND_FREQ / PHI) * np.sqrt(GAMMA) * PHI * ALPHA / BETA
        time_factor = np.exp(-1j * 2 * np.pi * TAU * t)
        return base * time_factor * xi
    
    def optimal_sound_frequency(self, temperature, density):
        """Расчёт оптимальной звуковой частоты для стабилизации"""
        return np.sqrt(temperature * density) / (2 * np.pi * PHI)
    
    def plasma_grid_advanced(self, t, phi_shift=0, obstacle_factor=0.0):
        """Расширенная модель плазменной решётки"""
        base_invariant = self.calculate_invariant(t)
        phase_factor = cmath.exp(-1j * (2 * cmath.pi * TAU * t + phi_shift))
        return base_invariant * phase_factor * (1 - obstacle_factor)
    
    def fihri_surface(self, u, v, xi=1.0, stability=1.0, phase=0.0):
        """Генерация поверхности Фихри с учётом параметров плазмы"""
        r = np.abs(np.cos(u) + 1j * xi * np.sin(v))
        x = r * np.cos(u)
        y = r * np.sin(u)
        z = np.sin(u) * np.cos(v)
        
        modifier = (ALPHA / BETA) * np.sqrt(GAMMA) * stability
        x *= modifier; y *= modifier; z *= modifier
        
        x_rot = x * np.cos(phase) - y * np.sin(phase)
        y_rot = x * np.sin(phase) + y * np.cos(phase)
        
        color = stability * (0.5 + 0.5 * np.sin(PHI * u + np.sqrt(5) * v + phase))
        
        return x_rot, y_rot, z, color
    
    def calculate_optimal_xi(self, t_values):
        """Расчёт оптимального значения ξ для временного диапазона"""
        stability_scores = []
        xi_range = np.linspace(0.5, 1.5, 50)
        
        for xi in xi_range:
            invariants = [np.abs(self.calculate_invariant(t, xi)) for t in t_values]
            stability_scores.append(np.mean(invariants) / np.std(invariants))
            
        optimal_xi = xi_range[np.argmax(stability_scores)]
        self.xi_history.append(optimal_xi)
        return optimal_xi
    
    # ==================== МЕТОДЫ ИЗ АНАЛОГИИ С ПРЯЛКОЙ ====================
    def spin_plasma(self, instability_level):
        """
        Адаптивное управление по принципу прялки
        Основано на тактильном чувстве - плавная регулировка параметров
        """
        # Анализ "сопротивления" плазмы
        resistance = np.mean(instability_level)**2
        
        # Базовые значения
        tension = 1.0  # магнитное натяжение
        twist = 1.0    # спиральность поля
        
        # Плавная регулировка (как рука пряхи)
        if resistance > 0.7:
            tension *= 0.9  # ослабляем натяжение
            twist *= 1.1    # увеличиваем скручивание
        elif resistance < 0.3:
            tension *= 1.1  # увеличиваем натяжение
            twist *= 0.95   # уменьшаем скручивание
            
        return tension, twist
    
    # ==================== МЕТОДЫ ИЗ АНАЛИЗА ИКОНКИ ====================
    def icon_protection_shield(self, t):
        """
        Многослойная защита по принципу иконки от огня
        """
        base_shield = self.calculate_invariant(t)
        
        # Создаем 4 точки стабилизации (по углам иконки)
        stabilization_points = [
            base_shield * np.exp(1j * angle) 
            for angle in [0, np.pi/2, np.pi, 3*np.pi/2]
        ]
        
        # Многослойная защита с гармонией и троичностью
        harmonic_shield = base_shield * self.harmonic_level / self.trinity_factor
        
        # Три уровня защиты
        inner_layer = harmonic_shield * 0.6  # Акустический барьер
        middle_layer = harmonic_shield * 0.3  # Магнитный барьер
        outer_layer = harmonic_shield * 0.1   # Электрохимический барьер
        
        return inner_layer + middle_layer + outer_layer, stabilization_points
    
    # ==================== ИНТЕГРИРОВАННОЕ УПРАВЛЕНИЕ ====================
    def integrated_control(self, t, plasma_instability):
        """
        Интегрированная система управления, объединяющая все подходы
        """
        # 1. Базовый инвариант
        base = self.calculate_invariant(t)
        
        # 2. Регулировка по принципу прялки
        tension, twist = self.spin_plasma(plasma_instability)
        
        # 3. Многослойная защита по принципу иконки
        shield, points = self.icon_protection_shield(t)
        
        # 4. Комбинируем все эффекты
        combined_control = base * tension * twist * shield
        
        # 5. Записываем историю для анализа
        self.stability_history.append(np.abs(combined_control))
        
        return combined_control, points
    
    # ==================== ВИЗУАЛИЗАЦИЯ ====================
    def create_stability_plot(self, t_values):
        """Визуализация истории устойчивости"""
        fig = go.Figure()
        fig.add_trace(go.Scatter(
            x=list(range(len(self.stability_history))),
            y=self.stability_history,
            mode='lines',
            name='Устойчивость',
            line=dict(width=3, color='purple')
        ))
        
        fig.update_layout(
            title='Динамика устойчивости плазмы',
            xaxis_title='Время',
            yaxis_title='Устойчивость',
            hovermode='x unified'
        )
        
        return fig
    
    def create_3d_visualization(self, u, v, xi=1.0, stability=1.0, phase=0.0):
        """Создание 3D визуализации поверхности Фихри"""
        x, y, z, color = self.fihri_surface(u, v, xi, stability, phase)
        
        fig = go.Figure(data=[go.Surface(
            x=x, y=y, z=z, 
            surfacecolor=color,
            colorscale='Viridis',
            colorbar=dict(title="Устойчивость")
        )])
        
        fig.update_layout(
            title='Визуализация поверхности Фихри с устойчивостью',
            scene=dict(
                xaxis_title="X",
                yaxis_title="Y", 
                zaxis_title="Z",
                aspectmode="auto"
            )
        )
        
        return fig

