# --- CLASS: SessionHashtag ---
class SessionHashtag:
    """Генератор хештег-ссылок для сессий ABSOLUTE"""
    
    @staticmethod
    def generate_session_tag(core_data: dict = None) -> str:
        """
        🏷️ Генерирует уникальный хештег для текущей сессии
        Формат: ABS_YYYYMMDD_HHMMSS_SHORT_HASH
        """
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        
        # Используем фундаментальные константы для создания уникального хеша
        if core_data and 'fundamentals' in core_data:
            data_str = f"{core_data['fundamentals'].get('φ', 1.618)}" \
                      f"{core_data['fundamentals'].get('√5', 2.236)}" \
                      f"{timestamp}"
        else:
            data_str = f"ABSOLUTE_SYSTEM_{timestamp}"
        
        # Создаем короткий хеш (8 символов)
        short_hash = hashlib.sha256(data_str.encode()).hexdigest()[:8].upper()
        
        return f"ABS_{timestamp}_{short_hash}"

# --- CLASS: SessionLinkManager ---
class SessionLinkManager:
    """Менеджер для работы с хештег-ссылками сессий"""
    
    def __init__(self):
        self.active_sessions = {}
        self.handbook = {}
    
    def register_session(self, session_data: dict) -> str:
        """Регистрирует новую сессию и возвращает её хештег"""
        hashtag = SessionHashtag.generate_session_tag(session_data)
        
        self.active_sessions[hashtag] = {
            "data": session_data,
            "registered": datetime.now().isoformat(),
            "status": "active"
        }
        
        # Автоматически добавляем в справочник
        self.handbook[hashtag] = {
            "summary": session_data.get("summary", ""),
            "keywords": session_data.get("keywords", []),
            "core_concepts": session_data.get("core_concepts", []),
            "linked_sessions": []
        }
        
        return hashtag
    
    def get_session_info(self, hashtag: str) -> dict:
        """Возвращает информацию о сессии по хештегу"""
        return self.active_sessions.get(hashtag, {})
    
    def link_sessions(self, hashtag1: str, hashtag2: str):
        """Создает связь между двумя сессиями в справочнике"""
        if hashtag1 in self.handbook and hashtag2 in self.handbook:
            self.handbook[hashtag1]["linked_sessions"].append(hashtag2)
            self.handbook[hashtag2]["linked_sessions"].append(hashtag1)

