# --- CLASS: WebAdminAgent ---
class WebAdminAgent(PersonalAgent):
    """
    Расширенный агент с функциями веб-администратора.
    """
    
    def __init__(self, user_code: str = ""):
        super().__init__(user_code)
        # Дополнительные структуры для веб-администрирования
        self.site_content = {
            "pages": {},
            "posts": [],
            "users": {},
            "comments": [],
            "settings": {}
        }
        self.analytics = {
            "visits": 0,
            "last_visit": None,
            "page_views": {},
            "user_activity": []
        }
        self._log("Веб-администратор инициализирован", "web")
    
    # ----- УПРАВЛЕНИЕ КОНТЕНТОМ -----
    def add_page(self, slug: str, title: str, content: str, published: bool = True):
        self.site_content["pages"][slug] = {
            "title": title,
            "content": content,
            "published": published,
            "created": datetime.now().isoformat(),
            "updated": datetime.now().isoformat()
        }
        self._log(f"Страница {slug} добавлена", "web")
        return {"status": "ok", "slug": slug}
    
    def update_page(self, slug: str, content: Dict):
        if slug in self.site_content["pages"]:
            self.site_content["pages"][slug].update(content)
            self.site_content["pages"][slug]["updated"] = datetime.now().isoformat()
            self._log(f"Страница {slug} обновлена", "web")
            return {"status": "ok"}
        raise HTTPException(status_code=404, detail="Страница не найдена")
    
    def delete_page(self, slug: str):
        if slug in self.site_content["pages"]:
            del self.site_content["pages"][slug]
            self._log(f"Страница {slug} удалена", "web")
            return {"status": "ok"}
        raise HTTPException(status_code=404, detail="Страница не найдена")
    
    # ----- МОДЕРАЦИЯ КОММЕНТАРИЕВ -----
    def moderate_comment(self, comment_id: int, action: str):
        # Поиск комментария (упрощённо)
        for comment in self.site_content["comments"]:
            if comment["id"] == comment_id:
                comment["moderated"] = True
                comment["moderation_action"] = action
                self._log(f"Комментарий {comment_id} {action}", "web")
                return {"status": "ok"}
        raise HTTPException(status_code=404, detail="Комментарий не найден")
    
    # ----- АНАЛИТИКА -----
    def track_visit(self, page: str = "/"):
        self.analytics["visits"] += 1
        self.analytics["last_visit"] = datetime.now().isoformat()
        self.analytics["page_views"][page] = self.analytics["page_views"].get(page, 0) + 1
        return {"status": "tracked"}
    
    def get_analytics(self) -> Dict:
        return self.analytics
    
    # ----- ИИ-ОТВЕТЫ НА ЗАПРОСЫ (ЧАТ-БОТ) -----
    def answer_question(self, question: str) -> str:
        # Здесь может быть интеграция с LLM или твои собственные ответы
        # Для примера — шаблонный ответ с резонансом
        resonance = self.resonate(len(question))
        answers = {
            "привет": "Приветствую, путник! Я — Хранитель Смыслов. Чем могу помочь?",
            "помощь": "Я могу управлять сайтом, отвечать на вопросы, показывать аналитику и хранить смыслы.",
            "смысл": f"Смысл в гармонии φ={PHI} и благодарности. Твой резонанс сейчас {resonance:.3f}.",
        }
        for key, value in answers.items():
            if key in question.lower():
                return value
        return f"Интересный вопрос. Мой резонанс на него: {resonance:.3f}. Возможно, ответ уже в тебе."

