# --- CLASS: Post ---
class Post(BaseModel):
    id: int
    author_id: int
    title: str
    content: str
    reactions: List[Reaction] = []
    created_at: datetime = datetime.now()

    def get_public_reactions(self):
        # Возвращает агрегированные данные для автора
        counts = {'good': 0, 'medium': 0, 'bad': 0}
        for r in self.reactions:
            counts[r.value] += 1
        return counts

