# --- CLASS: EnhancedProjectData ---
class EnhancedProjectData(ProjectData):
    def __init__(self):
        super().__init__()
        self.version = "1.1"
        self.last_modified = datetime.now()
    
    def search_data(self, keyword: str) -> Dict[str, Any]:
        """Поиск данных по ключевому слову"""
        results = {}
        for section, content in self.data.items():
            matches = {}
            for key, value in content.items():
                if (keyword.lower() in str(key).lower() or 
                    keyword.lower() in str(value).lower()):
                    matches[key] = value
            if matches:
                results[section] = matches
        return results
    
    def get_timeline(self) -> List[Dict]:
        """Получить хронологию изменений"""
        return sorted(self.history, 
                     key=lambda x: x['timestamp'], 
                     reverse=True)
    
    def backup(self) -> str:
        """Создать резервную копию с timestamp"""
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = f"project_backup_{timestamp}.json"
        with open(filename, 'w', encoding='utf-8') as f:
            f.write(self.export_json())
        return filename

# --- CLASS: PersonalAgent ---
class PersonalAgent:
    """Базовый агент Хранителя (внутренний)"""
    
    def __init__(self, user_code: str = ""):
        self.user_code = user_code
        self.created_at = datetime.now()
        self.logs = []
        self.phi = settings.PHI
    
    def _log(self, msg: str, category: str = "general"):
        self.logs.append({
            "time": datetime.now().isoformat(),
            "category": category,
            "message": msg
        })
    
    def resonate(self, value: float) -> float:
        """Внутренняя метрика гармонии (не показывается снаружи)"""
        if not settings.RESONANCE_ENABLED:
            return 0.0
        return abs(math.sin(value * self.phi)) * self.phi / 2
    
    def get_status(self) -> Dict:
        return {
            "status": "active",
            "uptime_seconds": (datetime.now() - self.created_at).total_seconds(),
            "logs_count": len(self.logs)
        }

