# --- CLASS: AITracker ---
class AITracker:
    """ИИ-трекер для акселерационных программ БАС/БРС."""

    def __init__(self):
        # Корневое хранилище всех команд
        self.storage = integrate_fractal_container({
            "teams": {},
            "meta": {
                "created": datetime.now().isoformat(),
                "version": "1.0"
            }
        })

    # ── РЕГИСТРАЦИЯ КОМАНДЫ ──────────────────────────────────
    def register_team(self, team_id: str, team_name: str,
                      contact_email: str) -> dict:
        """Создаёт новый узел команды."""
        path = f"teams.{team_id}"
        self.storage[f"{path}.name"] = team_name
        self.storage[f"{path}.email"] = contact_email
        self.storage[f"{path}.status"] = "diagnostic"
        self.storage[f"{path}.created"] = datetime.now().isoformat()
        self.storage[f"{path}.diagnostic.answers"] = {}
        self.storage[f"{path}.goal"] = None
        self.storage[f"{path}.tracking.sessions"] = []
        self.storage[f"{path}.reports"] = []

        return {"status": "ok", "team_id": team_id}

    # ── ДИАГНОСТИКА ──────────────────────────────────────────
    DIAGNOSTIC_QUESTIONS = [
        "Опишите ваш проект в 2-3 предложениях",
        "Какую проблему вы решаете?",
        "Кто ваша целевая аудитория?",
        "Какой у вас текущий доход / выручка?",
        "Какой размер команды? Кто в ней?",
        "Какие у вас ключевые ресурсы?",
        "Какую цель вы хотите достичь за 12 недель?",
        "Какие препятствия видите на этом пути?",
        "Какой у вас бюджет на развитие?",
        "Готовы ли вы работать еженедельно над проектом?",
    ]

    def get_diagnostic_questions(self) -> List[str]:
        return self.DIAGNOSTIC_QUESTIONS

    def save_diagnostic(self, team_id: str,
                        answers: Dict[str, str]) -> dict:
        """Сохраняет ответы на диагностику."""
        path = f"teams.{team_id}.diagnostic.answers"
        for i, (key, value) in enumerate(answers.items()):
            self.storage[f"{path}.q{i}"] = {
                "question": key,
                "answer": value
            }
        self.storage[f"teams.{team_id}.status"] = "goal_setting"
        self.storage[f"teams.{team_id}.diagnostic.completed"] = \
            datetime.now().isoformat()
        return {"status": "ok"}

    # ── ЦЕЛЬ И ТРЕКШН-КАРТА ──────────────────────────────────
    def set_goal(self, team_id: str, goal: str,
                 milestones: List[str]) -> dict:
        """Устанавливает цель и этапы."""
        path = f"teams.{team_id}"
        self.storage[f"{path}.goal.text"] = goal
        self.storage[f"{path}.goal.set_at"] = datetime.now().isoformat()
        for i, milestone in enumerate(milestones):
            self.storage[f"{path}.goal.milestones.m{i}"] = {
                "text": milestone,
                "done": False
            }
        self.storage[f"{path}.status"] = "in_progress"
        return {"status": "ok", "milestones_count": len(milestones)}

    # ── ТРЕКИНГ-СЕССИИ ──────────────────────────────────────
    def add_tracking_session(self, team_id: str, week: int,
                             done: str, problems: str,
                             plan: str) -> dict:
        """Добавляет отчёт по неделе."""
        path = f"teams.{team_id}.tracking.sessions.w{week}"
        self.storage[f"{path}.week"] = week
        self.storage[f"{path}.done"] = done
        self.storage[f"{path}.problems"] = problems
        self.storage[f"{path}.plan"] = plan
        self.storage[f"{path}.timestamp"] = datetime.now().isoformat()
        return {"status": "ok", "week": week}

    # ── ОТЧЁТЫ ──────────────────────────────────────────────
    def generate_report(self, team_id: str) -> dict:
        """Формирует сводный отчёт по команде."""
        try:
            team_data = self.storage[f"teams.{team_id}"]
        except KeyError:
            return {"error": "Команда не найдена"}

        return {
            "team_id": team_id,
            "name": self.storage[f"teams.{team_id}.name"],
            "status": self.storage[f"teams.{team_id}.status"],
            "goal": self.storage.get(f"teams.{team_id}.goal.text"),
            "sessions_count": self._count_sessions(team_id),
            "generated_at": datetime.now().isoformat()
        }

    def _count_sessions(self, team_id: str) -> int:
        """Считает количество проведённых сессий."""
        try:
            sessions = self.storage[f"teams.{team_id}.tracking.sessions"]
            if isinstance(sessions, dict):
                return len(sessions)
            return 0
        except KeyError:
            return 0

    # ── ЭКСПОРТ ─────────────────────────────────────────────
    def export_team(self, team_id: str) -> str:
        """Экспортирует данные команды в одну строку (gzip+base64)."""
        team_node = self.storage.get_child("teams").get_child(team_id)
        if not team_node:
            raise ValueError("Команда не найдена")
        team_node.freeze()
        return team_node.dumps()

    def export_all(self) -> str:
        """Экспортирует всё хранилище."""
        self.storage.freeze()
        packed = self.storage.dumps()
        self.storage.unfreeze()  # разморозим для дальнейшей работы
        return packed

    # ── СТАТИСТИКА ──────────────────────────────────────────
    def get_stats(self) -> dict:
        """Общая статистика по всем командам."""
        teams_node = self.storage.get_child("teams")
        if not teams_node:
            return {"teams_count": 0}

        teams = teams_node.children
        return {
            "teams_count": len(teams),
            "teams": [
                {
                    "id": name,
                    "name": node.get_child("name").data
                    if node.get_child("name") else "—",
                    "status": node.get_child("status").data
                    if node.get_child("status") else "—"
                }
                for name, node in teams.items()
            ]
        }

