# --- CLASS: EmergencyResponseProtocol ---
class EmergencyResponseProtocol:
    def __init__(self):
        self.response_matrix = {
            'НИЗКИЙ_РИСК': ['дипломатические_ноты', 'правовой_анализ'],
            'СРЕДНИЙ_РИСК': ['симметричные_меры', 'финансовые_контрмеры'],
            'ВЫСОКИЙ_РИСК': ['немедленные_санкции', 'активы_репатриация']
        }
    
