# --- CLASS: EduCore ---
class EduCore:
    """ЁМКОЕ ЯДРО ОБРАЗОВАТЕЛЬНОЙ СИСТЕМЫ - накопительная структура"""
    
    def __init__(self):
        # 🎯 Фундаментальное ядро (инвариант)
        self.fundamental_core = {
            "math": {"constants": ["π", "e", "φ"], "theorems": ["PYTHAGORAS", "NEWTON_LAWS"]},
            "physics": {"laws": ["CONSERVATION_ENERGY", "THERMODYNAMICS"]},
            "literature": {"archetypes": ["HERO_JOURNEY", "TRAGEDY"]}
        }
        
        # 🌐 Граф знаний (динамический)
        self.knowledge_graph = nx.DiGraph()
        self.concept_registry = {}
        
        # 📊 Метрики системы
        self.analytics = {
            "coherence": 0.0,
            "modernity": 0.0, 
            "compliance": {}
        }
        
        self._init_core_concepts()
    
    def _init_core_concepts(self):
        """Инициализация базовых концептов"""
        core_concepts = [
            self.create_concept("math_pythagoras", "Теорема Пифагора", "mathematics", 
                               "a² + b² = c²", ["geometry_basics"], 0.9),
            self.create_concept("physics_newton1", "Первый закон Ньютона", "physics",
                               "F = ma", ["math_algebra"], 0.8)
        ]
        for concept in core_concepts:
            self.add_concept(concept)
    
    def create_concept(self, id: str, name: str, discipline: str, 
                      invariant: str, connections: List[str], importance: float) -> Dict:
        """Создание нового концепта"""
        return {
            "id": id, "name": name, "discipline": discipline,
            "invariant": invariant, "connections": connections,
            "examples": [], "importance": importance,
            "level": self._calc_complexity(invariant)
        }
    
    def add_concept(self, concept: Dict):
        """Добавление концепта в систему"""
        self.concept_registry[concept["id"]] = concept
        self.knowledge_graph.add_node(concept["id"])
        for conn in concept["connections"]:
            if conn in self.concept_registry:
                self.knowledge_graph.add_edge(conn, concept["id"])
        self._update_analytics()
    
    def add_example(self, concept_id: str, example: str):
        """Добавление современного примера к концепту"""
        if concept_id in self.concept_registry:
            self.concept_registry[concept_id]["examples"].append(example)
            self.analytics["modernity"] = min(1.0, self.analytics["modernity"] + 0.01)
    
    def find_learning_path(self, target: str) -> List[str]:
        """Поиск оптимального пути обучения"""
        try:
            roots = [n for n in self.knowledge_graph.nodes() if self.knowledge_graph.in_degree(n) == 0]
            paths = [nx.shortest_path(self.knowledge_graph, r, target) for r in roots if nx.has_path(self.knowledge_graph, r, target)]
            return min(paths, key=len) if paths else []
        except:
            return []
    
    def generate_textbook(self, discipline: str, level: int) -> Dict:
        """Генерация структуры учебника"""
        concepts = [c for c in self.concept_registry.values() 
                   if c["discipline"] == discipline and c["level"] <= level]
        concepts.sort(key=lambda x: (-x["importance"], x["level"]))
        
        return {
            "discipline": discipline,
            "level": level,
            "chapters": [{
                "title": c["name"],
                "core": c["invariant"],
                "examples": c["examples"][:3],  # 3 самых свежих примера
                "connections": [self.concept_registry[conn]["name"] for conn in c["connections"] 
                              if conn in self.concept_registry]
            } for c in concepts]
        }
    
    def _calc_complexity(self, text: str) -> int:
        """Расчет сложности концепта"""
        return min(4, max(1, len(text) // 20))
    
    def _update_analytics(self):
        """Обновление метрик системы"""
        if self.knowledge_graph.number_of_nodes() > 0:
            self.analytics["coherence"] = sum(dict(self.knowledge_graph.degree()).values()) / self.knowledge_graph.number_of_nodes() / 10
    
    def export_state(self) -> Dict:
        """Экспорт всего состояния системы"""
        return {
            "fundamental_core": self.fundamental_core,
            "concepts": self.concept_registry,
            "analytics": self.analytics,
            "graph_metrics": {
                "nodes": self.knowledge_graph.number_of_nodes(),
                "edges": self.knowledge_graph.number_of_edges()
            }
        }
    
    def import_state(self, data: Dict):
        """Импорт состояния системы"""
        self.fundamental_core = data.get("fundamental_core", {})
        self.concept_registry = data.get("concepts", {})
        self.analytics = data.get("analytics", {})
        
        # Восстановление графа
        self.knowledge_graph = nx.DiGraph()
        for concept_id in self.concept_registry:
            self.knowledge_graph.add_node(concept_id)
            for conn in self.concept_registry[concept_id]["connections"]:
                if conn in self.concept_registry:
                    self.knowledge_graph.add_edge(conn, concept_id)

# --- CLASS: KomiDataEngine ---
class KomiDataEngine:
    """
    Основной движок для хранения и анализа данных Республики Коми
    Поддерживает легкую интеграцию новых данных и глубинный анализ
    """
    
    def __init__(self):
        # Основное хранилище структурированных данных
        self.data_store = {
            'projects': {},      # Проекты и инициативы
            'finance': {},       # Финансовые показатели
            'tasks': {},         # Задачи и поручения
            'analytics': {},     # Результаты анализа
            'metadata': {        # Метаинформация
                'created': datetime.now().isoformat(),
                'last_update': datetime.now().isoformat(),
                'version': '1.0'
            }
        }
        
        # История изменений для отслеживания итераций
        self.change_log = []
        
    def add_project(self, project_id: str, project_data: Dict[str, Any]) -> None:
        """Добавление/обновление проекта"""
        self.data_store['projects'][project_id] = {
            **project_data,
            'last_modified': datetime.now().isoformat(),
            'version': self.data_store['projects'].get(project_id, {}).get('version', 0) + 1
        }
        self._log_change('project_add', project_id, project_data)
    
    def add_financial_data(self, sector: str, financials: Dict[str, Any]) -> None:
        """Добавление финансовых данных по секторам"""
        self.data_store['finance'][sector] = financials
        self._log_change('finance_update', sector, financials)
    
    def add_task(self, task_id: str, task_info: Dict[str, Any]) -> None:
        """Добавление задачи с системой отслеживания"""
        self.data_store['tasks'][task_id] = {
            **task_info,
            'status': 'active',
            'created': datetime.now().isoformat(),
            'progress': 0.0
        }
        self._log_change('task_add', task_id, task_info)
    
    def update_task_progress(self, task_id: str, progress: float, notes: str = "") -> None:
        """Обновление прогресса задачи"""
        if task_id in self.data_store['tasks']:
            self.data_store['tasks'][task_id].update({
                'progress': progress,
                'last_updated': datetime.now().isoformat(),
                'notes': notes
            })
            self._log_change('task_progress', task_id, {'progress': progress, 'notes': notes})
    
    def add_analysis(self, analysis_type: str, results: Dict[str, Any]) -> None:
        """Добавление результатов анализа"""
        self.data_store['analytics'][analysis_type] = {
            **results,
            'timestamp': datetime.now().isoformat(),
            'data_sources': list(self.data_store['projects'].keys()) + list(self.data_store['finance'].keys())
        }
        self._log_change('analysis_add', analysis_type, results)
    
    def _log_change(self, action: str, target: str, data: Dict[str, Any]) -> None:
        """Внутренний метод логирования изменений"""
        self.change_log.append({
            'timestamp': datetime.now().isoformat(),
            'action': action,
            'target': target,
            'data_snapshot': data,
            'change_id': f"ch_{len(self.change_log):06d}"
        })
        self.data_store['metadata']['last_update'] = datetime.now().isoformat()

# --- CLASS: KomiAnalyzer ---
class KomiAnalyzer:
    """
    Аналитический модуль для глубинного анализа данных
    """
    
    @staticmethod
    def analyze_budget_adequacy(finance_data: Dict[str, Any]) -> Dict[str, Any]:
        """Анализ бюджетной достаточности"""
        total_income = sum(sector.get('planned_income', 0) for sector in finance_data.values())
        total_expenses = sum(sector.get('planned_expenses', 0) for sector in finance_data.values())
        
        deficit = total_expenses - total_income
        adequacy_ratio = total_income / total_expenses if total_expenses > 0 else 0
        
        return {
            'deficit': deficit,
            'adequacy_ratio': adequacy_ratio,
            'coverage_percentage': adequacy_ratio * 100,
            'risk_level': 'high' if adequacy_ratio < 0.8 else 'medium' if adequacy_ratio < 1.0 else 'low',
            'recommendations': [
                "Оптимизация расходов" if deficit > 0 else "Расширение инвестиционных программ",
                "Привлечение федерального финансирования",
                "Развитие ГЧП"
            ]
        }
    
    @staticmethod
    def analyze_project_risks(projects: Dict[str, Any]) -> Dict[str, Any]:
        """Анализ рисков проектов"""
        risk_categories = {}
        
        for project_id, project in projects.items():
            risks = project.get('risks', [])
            for risk in risks:
                category = risk.get('category', 'other')
                if category not in risk_categories:
                    risk_categories[category] = []
                risk_categories[category].append({
                    'project': project_id,
                    'risk': risk['description'],
                    'level': risk.get('level', 'medium')
                })
        
        return {
            'risk_by_category': risk_categories,
            'total_risks': sum(len(risks) for risks in risk_categories.values()),
            'high_risk_count': sum(1 for risks in risk_categories.values() 
                                 for risk in risks if risk['level'] == 'high')
        }
    
    @staticmethod
    def calculate_task_completion(tasks: Dict[str, Any]) -> Dict[str, Any]:
        """Расчет показателей выполнения задач"""
        completed = [t for t in tasks.values() if t.get('progress', 0) >= 100]
        active = [t for t in tasks.values() if 0 < t.get('progress', 0) < 100]
        not_started = [t for t in tasks.values() if t.get('progress', 0) == 0]
        
        return {
            'completion_rate': len(completed) / len(tasks) if tasks else 0,
            'active_tasks': len(active),
            'completed_tasks': len(completed),
            'overdue_tasks': len([t for t in tasks.values() 
                                if t.get('deadline') and 
                                datetime.fromisoformat(t['deadline']) < datetime.now()])
        }

# --- CLASS: KomiDataExporter ---
class KomiDataExporter:
    """
    Модуль экспорта данных в различные форматы
    """
    
    @staticmethod
    def to_json(komi_engine: KomiDataEngine, include_history: bool = True) -> str:
        """Экспорт в JSON с поддержкой кириллицы"""
        export_data = {
            'data_store': komi_engine.data_store,
            'metadata': komi_engine.data_store['metadata'],
            'summary': KomiDataExporter._generate_summary(komi_engine)
        }
        
        if include_history:
            export_data['change_log'] = komi_engine.change_log[-100:]  # Последние 100 изменений
        
        return json.dumps(export_data, ensure_ascii=False, indent=2, default=str)
    
    @staticmethod
    def to_structured_dict(komi_engine: KomiDataEngine) -> Dict[str, Any]:
        """Экспорт в структурированный словарь для анализа"""
        return {
            'projects_summary': {
                'count': len(komi_engine.data_store['projects']),
                'projects': list(komi_engine.data_store['projects'].keys())
            },
            'finance_summary': {
                'sectors': list(komi_engine.data_store['finance'].keys()),
                'total_budget': sum(sector.get('planned_income', 0) 
                                  for sector in komi_engine.data_store['finance'].values())
            },
            'tasks_summary': KomiAnalyzer.calculate_task_completion(komi_engine.data_store['tasks']),
            'analytics_summary': {
                'types': list(komi_engine.data_store['analytics'].keys()),
                'latest_analysis': max(komi_engine.data_store['analytics'].values(), 
                                     key=lambda x: x['timestamp']) if komi_engine.data_store['analytics'] else None
            }
        }
    
    @staticmethod
    def _generate_summary(komi_engine: KomiDataEngine) -> Dict[str, Any]:
        """Генерация сводки по данным"""
        return {
            'total_projects': len(komi_engine.data_store['projects']),
            'total_tasks': len(komi_engine.data_store['tasks']),
            'financial_sectors': len(komi_engine.data_store['finance']),
            'analysis_count': len(komi_engine.data_store['analytics']),
            'last_update': komi_engine.data_store['metadata']['last_update']
        }

