# --- CLASS: MetaphysicalSession ---
class MetaphysicalSession:
    """
    Класс для хранения, обновления и верификации метафизической сессии.
    Использует эмодзи для ключей, легко расширяем.
    """
    def __init__(self):
        # Инициализация данных с эмодзи-ключами
        self.session_data: Dict[str, Any] = {
            "🔑": {},      # Секреты и ключи
            "✨": {},      # Числовые константы (φ, √5 и др.)
            "🧪": {},      # Исследовательские параметры
            "🔮": {},      # Метафизические установки
            "⚖️": {},      # Балансы параметров
            "💠": [],      # Спектральные значения
            "📅": None,    # Дата рождения
            "🌈": {},      # Спектральные компоненты
            "💫": ""       # Ключевая фраза сессии
        }
        self.validation_hash: str = ""

    def update_section(self, key: str, data: Any):
        """
        Обновить раздел сессии по эмодзи-ключу.
        Поддержка глубокого обновления словарей.
        """
        if key in self.session_data and isinstance(self.session_data[key], dict) and isinstance(data, dict):
            self.session_data[key].update(data)
        else:
            self.session_data[key] = data

    def generate_validation_hash(self):
        """
        Генерировать SHA256 хеш из скомбинированных основных параметров для валидации.
        """
        combined = (
            str(self.session_data["✨"].get("phi", "")) +
            (self.session_data["📅"].strftime("%Y%m%d") if self.session_data["📅"] else "") +
            ",".join(map(str, self.session_data["💠"])) +
            self.session_data["💫"]
        )
        self.validation_hash = hashlib.sha256(combined.encode("utf-8")).hexdigest()
        return self.validation_hash

    def export_json(self):
        """
        Экспортировать текущую сессию и хеш в JSON-словарь.
        """
        export_data = {
            "session": self.session_data,
            "validation": {
                "hash": self.validation_hash
            }
        }
        return export_data

# --- CLASS: HyperBalance7Simulation ---
class HyperBalance7Simulation:
    """
    Модель установки HyperBalance7, использующая EM-эволюцию.
    """
    def __init__(self, climate_params: dict):
        """
        climate_params: dict с ключами:
            - temp_mean (средняя температура, °C)
            - humidity_mean (средняя влажность, %)
            - wind_speed (средняя скорость ветра, м/с)
            - solar_flux (солнечная радиация, Вт/м²)
        """
        self.climate = climate_params
        # Инициализируем резонаторы на основе климата
        # E - тепловая энергия (пропорциональна солнечному потоку)
        e_amp = climate_params.get('solar_flux', 1000) / 1000.0  # нормировка
        # B - влажностный потенциал (пропорционален влажности и температуре)
        # Чем выше влажность, тем больше потенциальная конденсация
        b_amp = climate_params.get('humidity_mean', 50) / 100.0  # относительная влажность

        self.E_resonators = [EMResonator(amp=e_amp, phase=0.0, freq=0.1)]
        self.B_resonators = [EMResonator(amp=b_amp, phase=0.5, freq=0.12)]  # сдвиг фазы

        # Параметры установки
        self.hyperboloid_radius = 2.5  # м
        self.height = 6.0             # м
        self.area = np.pi * (self.hyperboloid_radius ** 2)

        # Сбор данных
        self.water_history = []
        self.time_history = []

    def evolve_EM_relational(self, steps=100, hbar=1.0, coupling=0.1):
        """Встроенная реализация метода (твой код с небольшими доработками)."""
        if not self.E_resonators or not self.B_resonators:
            print("Добавьте хотя бы один E и один B резонатор.")
            return

        e_clock = self.E_resonators[0]
        b_clock = self.B_resonators[0]
        rel_time = RelationalTime(e_clock, b_clock, hbar=hbar)

        total_water = 0.0  # литры, накопленные за эволюцию

        for step in range(steps):
            dt = rel_time.get_dt()
            tick = rel_time.tick()
            dt = rel_time.get_dt()

            if dt is None or dt == 0:
                continue

            # Эволюционируем все резонаторы
            for e in self.E_resonators:
                for b in self.B_resonators:
                    delta_phase = e.phase - b.phase
                    transfer = coupling * np.sin(delta_phase) * dt
                    e_energy = e.amp**2
                    b_energy = b.amp**2

                    # Переток энергии (E -> B = конденсация)
                    if e_energy > 0 and b_energy > 0:
                        # Ограничиваем переток, чтобы не уйти в отрицательные
                        max_transfer = min(e_energy, b_energy * 0.5)  # эмпирика
                        actual_transfer = min(transfer, max_transfer)
                        e.amp = np.sqrt(max(0, e_energy - actual_transfer))
                        b.amp = np.sqrt(max(0, b_energy + actual_transfer))
                    elif e_energy > 0 and b_energy == 0:
                        b.amp = np.sqrt(e_energy) * 0.5  # часть переходит
                        e.amp = np.sqrt(e_energy * 0.5)
                    elif b_energy > 0 and e_energy == 0:
                        e.amp = np.sqrt(b_energy) * 0.5
                        b.amp = np.sqrt(b_energy * 0.5)

                    e.tick(dt)
                    b.tick(dt)

            # После обновления полей вычисляем количество образовавшейся воды
            # Вода пропорциональна энергии, перешедшей из E в B за этот шаг
            # Мы используем изменение амплитуды B как индикатор
            # Для простоты: water = k * (b_amp_new - b_amp_old) * площадь * коэффициент
            # Но у нас нет истории старых амплитуд, поэтому используем прирост энергии B
            # Можно вести накопление, вычитая начальную энергию B
            # Здесь я упрощённо: вода = суммарная энергия B минус начальная, умноженная на коэф.
            # Запомним начальную энергию B при первом шаге
            if step == 0:
                self.initial_b_energy = self.B_resonators[0].amp**2
            # Текущая энергия B
            b_energy_now = self.B_resonators[0].amp**2
            delta_energy_b = b_energy_now - self.initial_b_energy
            # Предположим, что 1 единица энергии = 0.1 литра воды (калибровка)
            water_liters = max(0, delta_energy_b * 0.1 * self.area * self.climate.get('wind_speed', 1))
            total_water += water_liters

            self.water_history.append(total_water)
            self.time_history.append(rel_time.ticks)

            # Опционально выводим прогресс
            if step % 10 == 0:
                print(f"Шаг {step}: dt={dt:.3f}, вода={total_water:.2f} л")

        print(f"EM-эволюция завершена. Всего тиков: {rel_time.ticks:.2f}")
        print(f"Итого накоплено воды: {total_water:.2f} литров")
        return total_water

    def get_performance(self):
        """Возвращает итоговые KPI установки."""
        if not self.water_history:
            return {"water": 0, "efficiency": 0}
        total_water = self.water_history[-1]
        # Эффективность можно оценить как литры на единицу солнечной энергии
        solar_input = self.climate.get('solar_flux', 1000) * 24  # за сутки
        efficiency = total_water / solar_input if solar_input > 0 else 0
        return {
            "total_water_liters": total_water,
            "efficiency_l_per_kWh": efficiency * 1000,  # пересчёт
            "final_b_amp": self.B_resonators[0].amp,
            "final_e_amp": self.E_resonators[0].amp
        }

