    def compress(self) -> dict:
        """Возвращает всё содержимое как плоский словарь для сериализации."""
        return {
            "meta": self.meta,
            "legal": self.legal,
            "ethics": self.ethics,
            "hub": self.hub,
            "risks": self.risks,
            "formulas": self.formulas,
            "pattern": self.pattern
        }

    @classmethod
    def decompress(cls, data: dict) -> "FractalCore":
        """Восстанавливает объект из сжатого словаря."""
        core = cls()
        for key in data:
            setattr(core, key, data[key])
        return core

